// ΓöÇΓöÇΓöÇ Serveur Next.js ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function waitForServer(maxAttempts = 120) {
  return new Promise((resolve, reject) => {
    let attempts = 0
    const check = () => {
      attempts++
      const req = http.get(`http://127.0.0.1:${PORT}`, (res) => {
        res.resume()
        resolve(true)
      })
      req.on('error', () => {
        if (attempts >= maxAttempts) {
          reject(new Error("Le serveur Next.js n'a pas d├⌐marr├⌐ ├á temps"))
        } else {
          setTimeout(check, 500)
        }
      })
      req.setTimeout(2000, () => req.destroy())
    }
    check()
  })
}

function startNextServer() {
  return new Promise((resolve, reject) => {
    const userDataPath = app.getPath('userData')
    ensureDirectories(userDataPath)

    const secretPath = path.join(userDataPath, '.jwt-secret')
    const jwtSecret = fs.existsSync(secretPath)
      ? fs.readFileSync(secretPath, 'utf8').trim()
      : undefined

    const serverDir = getServerDir()
    const serverScript = path.join(serverDir, 'server.js')

    if (!fs.existsSync(serverScript)) {
      reject(new Error(`Serveur introuvable : ${serverScript}`))
      return
    }

    nextServer = spawn(process.execPath, [serverScript], {
      env: {
        ...process.env,
        NODE_ENV: 'production',
        PORT: String(PORT),
        HOSTNAME: '127.0.0.1',
        SM_USER_DATA: userDataPath,
        SM_COOKIE_SECURE: 'false',
        ELECTRON_RUN_AS_NODE: '1',
        LICENCE_SERVER_URL: process.env.LICENCE_SERVER_URL || 'https://schoolmanager-eosin.vercel.app',
        ...(jwtSecret ? { SM_JWT_SECRET: jwtSecret } : {}),
      },
      cwd: serverDir,
      stdio: ['ignore', 'pipe', 'pipe'],
      windowsHide: true,
    })

    nextServer.stdout?.on('data', (data) => {
      const msg = data.toString()
      if (msg.trim()) console.log('[next]', msg.trim())
    })
    nextServer.stderr?.on('data', (data) => {
      const msg = data.toString()
      if (msg.trim()) console.error('[next]', msg.trim())
    })
    nextServer.on('error', reject)
    nextServer.on('exit', (code) => {
      if (code !== 0 && code !== null) console.error('[next] exit code', code)
    })

    waitForServer().then(resolve).catch(reject)
  })
}

// ΓöÇΓöÇΓöÇ Utilitaires ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function ensureDirectories(userDataPath) {
  const dirs = [
    userDataPath,
    path.join(userDataPath, 'uploads', 'eleves'),
    path.join(userDataPath, 'backups'),
    path.join(userDataPath, 'exports'),
  ]
  for (const dir of dirs) {
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true })
  }
}

