function sendUpdateStatus(payload) {
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('update-status', payload)
  }
}

function setupAutoUpdater() {
  if (!app.isPackaged) return

  autoUpdater.autoDownload = false
  autoUpdater.autoInstallOnAppQuit = true

  const updateUrl = process.env.SM_UPDATE_URL
  if (updateUrl) {
    autoUpdater.setFeedURL({ provider: 'generic', url: updateUrl })
  }

  autoUpdater.on('checking-for-update', () => {
    sendUpdateStatus({ status: 'checking' })
  })
  autoUpdater.on('update-available', (info) => {
    sendUpdateStatus({ status: 'available', version: info.version })
  })
  autoUpdater.on('update-not-available', () => {
    sendUpdateStatus({ status: 'not-available' })
  })
  autoUpdater.on('download-progress', (progress) => {
    sendUpdateStatus({
      status: 'downloading',
      progress: progress.percent,
    })
  })
  autoUpdater.on('update-downloaded', (info) => {
    sendUpdateStatus({ status: 'downloaded', version: info.version })
  })
  autoUpdater.on('error', (err) => {
    sendUpdateStatus({ status: 'error', error: err.message })
  })
}

ipcMain.handle('check-for-updates', async () => {
  if (!app.isPackaged) {
    return { error: 'Les mises ├á jour ne sont disponibles que sur la version install├⌐e' }
  }
  try {
    const result = await autoUpdater.checkForUpdates()
    return { success: true, version: result?.updateInfo?.version }
  } catch (err) {
    return { error: err.message || 'Erreur lors de la v├⌐rification' }
  }
})

ipcMain.handle('download-update', async () => {
  if (!app.isPackaged) return { error: 'Non disponible en d├⌐veloppement' }
  try {
    await autoUpdater.downloadUpdate()
    return { success: true }
  } catch (err) {
    return { error: err.message || 'Erreur de t├⌐l├⌐chargement' }
  }
})

ipcMain.handle('install-update', () => {
  autoUpdater.quitAndInstall(false, true)
})

ipcMain.handle('restore-database', async () => {
  const result = await dialog.showOpenDialog(mainWindow, {
    title: 'Restaurer une sauvegarde',
    buttonLabel: 'Restaurer',
    filters: [{ name: 'Base de donn├⌐es SchoolManager', extensions: ['db'] }],
    properties: ['openFile'],
  })

  if (result.canceled || result.filePaths.length === 0) {
    return { success: false, canceled: true }
  }

  const sourcePath = result.filePaths[0]

  // Avertissement + confirmation avant d'├⌐craser la base actuelle
  const confirm = await dialog.showMessageBox(mainWindow, {
    type: 'warning',
    buttons: ['Annuler', 'Restaurer et red├⌐marrer'],
    defaultId: 0,
    cancelId: 0,
    title: 'Confirmer la restauration',
    message: 'Cette action va remplacer la base de donn├⌐es actuelle.',
    detail:
      "Une sauvegarde de s├⌐curit├⌐ de la base actuelle sera cr├⌐├⌐e automatiquement avant l'├⌐crasement. L'application va red├⌐marrer une fois la restauration termin├⌐e.",
  })

  if (confirm.response !== 1) {
    return { success: false, canceled: true }
  }

  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/api/backup/restore`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sourcePath }),
    })
    const data = await res.json()

    if (!data.success) {
      dialog.showErrorBox('Restauration ├⌐chou├⌐e', data.error || 'Erreur inconnue.')
      return { success: false, error: data.error }
    }
  } catch (err) {
    dialog.showErrorBox('Restauration ├⌐chou├⌐e', err.message)
    return { success: false, error: err.message }
  }

  // Red├⌐marre proprement pour que le serveur Next.js recharge la base restaur├⌐e
  app.relaunch()
  app.quit()
  return { success: true }
})

function runDailyBackup(userDataPath) {
  try {
    const dbPath = path.join(userDataPath, 'schoolmanager.db')
    if (!fs.existsSync(dbPath)) return

    const backupsDir = path.join(userDataPath, 'backups')
    const today = new Date().toISOString().slice(0, 10)
    const backupPath = path.join(backupsDir, `schoolmanager-${today}.db`)

    if (!fs.existsSync(backupPath)) {
      fs.copyFileSync(dbPath, backupPath)
      const files = fs.readdirSync(backupsDir)
        .filter(f => f.startsWith('schoolmanager-') && f.endsWith('.db'))
        .map(f => ({ path: path.join(backupsDir, f), mtime: fs.statSync(path.join(backupsDir, f)).mtimeMs }))
        .sort((a, b) => b.mtime - a.mtime)

      for (const file of files.slice(7)) fs.unlinkSync(file.path)
    }
  } catch (err) {
    console.error('Backup error:', err)
  }
}

