const { rebuild } = require('@electron/rebuild')

const standaloneDir = path.join(__dirname, '..', '.next', 'standalone')
const electronVersion = require('electron/package.json').version

async function rebuildIn(buildPath, label, required = false) {
  const modulesPath = path.join(buildPath, 'node_modules', 'better-sqlite3')
  if (!fs.existsSync(modulesPath)) {
    if (required) {
      console.error(`Γ¥î better-sqlite3 introuvable dans ${label}`)
      process.exit(1)
    }
    console.log(`ΓÅ¡∩╕Å  Pas de better-sqlite3 dans ${label}, ignor├⌐`)
    return false
  }
  console.log(`≡ƒöº Rebuild better-sqlite3 dans ${label}ΓÇª`)
  try {
    await rebuild({
      buildPath,
      electronVersion,
      force: true,
      onlyModules: ['better-sqlite3'],
    })
    const binary = path.join(modulesPath, 'build', 'Release', 'better_sqlite3.node')
    if (fs.existsSync(binary)) {
      const stats = fs.statSync(binary)
      console.log(`Γ£à ${label} ΓÇö ${stats.size} bytes ΓÇö ${stats.mtime.toISOString()}`)
      return true
    }
    console.error(`Γ¥î Binaire introuvable dans ${label}`)
    process.exit(1)
  } catch (e) {
    console.error(`Γ¥î Rebuild ${label} ├⌐chou├⌐:`, e.message)
    process.exit(1)
  }
}

