                    <td className="px-5 py-3.5">
                      <Link href={`/${slug}/eleves/${el.id}`}
                        className="inline-flex items-center gap-1 text-sm text-emerald-600 hover:underline font-medium">
                        {t('detail.students.profile')} <ChevronRight className="w-4 h-4" />
                      </Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {matieres.length > 0 && (
        <div className="card p-6">
          <div className="flex items-center gap-2 mb-4">
            <BookOpen className="w-5 h-5 text-slate-500" />
            <h2 className="font-semibold text-slate-800">{t('detail.subjects.title', { count: matieres.length })}</h2>
          </div>
          <div className="flex flex-wrap gap-2">
            {matieres.map(m => (
              <span key={m.id} className="px-3 py-1.5 bg-slate-100 text-slate-700 rounded-lg text-sm font-medium">
                {m.nom}
              </span>
            ))}
          </div>
        </div>
      )}
    </PageShell>
  )
}

'use client'

import { useState, useEffect, useMemo } from 'react'
import Link from 'next/link'
import { useParams } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { Plus, School, UserCheck, ChevronRight, Layers, ArrowRightLeft, Search } from 'lucide-react'
import toast from 'react-hot-toast'
import PageShell from '@/components/layout/PageShell'
import Modal from '@/components/ui/Modal'
import Badge from '@/components/ui/Badge'
import EmptyState from '@/components/ui/EmptyState'
import SmartFilterBar from '@/components/filters/SmartFilterBar'
import { useSchool } from '@/components/layout/SchoolProvider'
import { useSmartFilters } from '@/hooks/useSmartFilters'
import { useSectionOptions, useTranslatedEnums } from '@/hooks/useTranslatedEnums'
import { canWriteModule } from '@/lib/rbac'
import {
  CAMEROON_SECTIONS,
  SECTION_ORDER,
  type SectionRef,
} from '@/lib/cameroon-levels'

interface Classe {
  id: string
  nom: string
  section: string
  niveau: string
  annee_scolaire: string
  capacite_max: number
  nb_eleves: number
  personnel_id: string | null
  enseignant_nom: string | null
  enseignant_prenom: string | null
}

interface Enseignant {
  id: string
  nom: string
  prenom: string | null
}

export default function ClassesPage() {
  const { slug } = useParams()
  const { anneeScolaire, userRole } = useSchool()
  const t = useTranslations('classes')
  const tc = useTranslations('common')
  const tf = useTranslations('filters')
  const te = useTranslatedEnums()
  const sectionOptions = useSectionOptions()
  const canCreateClass = canWriteModule(userRole, 'classes')
  const [classes, setClasses] = useState<Classe[]>([])
  const [enseignants, setEnseignants] = useState<Enseignant[]>([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [showReferentiel, setShowReferentiel] = useState(false)
  const [saving, setSaving] = useState(false)
  const [selectedNiveaux, setSelectedNiveaux] = useState<Set<string>>(new Set())

  const [form, setForm] = useState({
    nom: '', section: 'francophone', niveau: '',
    annee_scolaire: anneeScolaire, capacite_max: '60',
  })

  const up = (f: string, v: string) => setForm(p => ({ ...p, [f]: v }))

  const filterFields = useMemo(() => [
    {
      key: 'q',
      type: 'search' as const,
      placeholder: t('list.searchPlaceholder'),
      debounce: true,
    },
    {
      key: 'section',
      type: 'select' as const,
      label: tf('section.label'),
      options: sectionOptions,
      defaultValue: '',
    },
  ], [t, tf, sectionOptions])

  const { values, debouncedValues, setFilter, reset, activeFilters } = useSmartFilters(filterFields)

  const filteredClasses = useMemo(() => {
    const q = debouncedValues.q?.toLowerCase().trim()
    const section = debouncedValues.section
    return classes.filter(c => {
      if (section && c.section !== section) return false
      if (q) {
        const hay = `${c.nom} ${c.niveau} ${c.enseignant_nom ?? ''} ${c.enseignant_prenom ?? ''}`.toLowerCase()
        if (!hay.includes(q)) return false
      }
      return true
    })
  }, [classes, debouncedValues.q, debouncedValues.section])

  const fetchClasses = async () => {
    setLoading(true)
    const [cRes, pRes] = await Promise.all([
      fetch('/api/classes'),
      fetch('/api/personnel?type=enseignant'),
    ])
    const cData = await cRes.json()
    const pData = await pRes.json()
    setClasses(cData.classes || [])
    setEnseignants(pData.personnel || [])
    setLoading(false)
  }

  useEffect(() => { fetchClasses() }, [])

  const handleCreate = async () => {
    if (!form.nom || !form.section) return
    setSaving(true)
    const res = await fetch('/api/classes', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form),
    })
    if (!res.ok) {
      toast.error(t('list.toasts.createError'))
      setSaving(false)
      return
    }
    toast.success(t('list.toasts.created'))
    setShowForm(false)
    setForm({ nom: '', section: 'francophone', niveau: '', annee_scolaire: anneeScolaire, capacite_max: '60' })
    await fetchClasses()
    setSaving(false)
  }

  const handleBulkCreate = async () => {
    if (selectedNiveaux.size === 0) return
    setSaving(true)
    const toCreate: { nom: string; section: string; niveau: string; code: string }[] = []

    for (const key of selectedNiveaux) {
      const [section, code] = key.split('::')
      const sec = CAMEROON_SECTIONS.find(s => s.id === section)
      if (!sec) continue
      for (const cycle of sec.cycles) {
        const nv = cycle.niveaux.find(n => n.code === code)
        if (nv) {
          toCreate.push({ nom: nv.nomDefaut, section, niveau: nv.code, code: nv.code })
        }
      }
    }

    const res = await fetch('/api/classes', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ classes: toCreate, annee_scolaire: anneeScolaire }),
    })
    const data = await res.json()
    if (!res.ok) {
      toast.error(t('list.toasts.createError'))
      setSaving(false)
      return
    }
    toast.success(t('list.toasts.createdBulk', { count: data.created }))
    setShowReferentiel(false)
    setSelectedNiveaux(new Set())
    await fetchClasses()
    setSaving(false)
  }

  const toggleNiveau = (section: string, code: string) => {
    const key = `${section}::${code}`
    setSelectedNiveaux(prev => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  }

  const isNiveauCreated = (section: string, nomDefaut: string) =>
    classes.some(c => c.section === section && (c.nom === nomDefaut || c.niveau === nomDefaut))

  const handleAssignEnseignant = async (classeId: string, personnelId: string) => {
    const res = await fetch('/api/classes', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: classeId, personnel_id: personnelId || null }),
    })
    if (!res.ok) {
      toast.error(t('list.toasts.assignError'))
      return
    }
    toast.success(t('list.toasts.assigned'))
    await fetchClasses()
  }

  const grouped = SECTION_ORDER.reduce((acc: Record<string, Classe[]>, section) => {
    const items = filteredClasses.filter(c => c.section === section)
    if (items.length > 0) acc[section] = items
    return acc
  }, {})

  return (
    <PageShell
      title={t('list.title')}
      subtitle={t('list.subtitle', { count: filteredClasses.length, year: anneeScolaire })}
      breadcrumb={t('list.breadcrumb')}
      actions={
        <div className="flex items-center gap-2">
          <Link href={`/${slug}/classes/transferts`} className="btn-secondary flex items-center gap-2 py-2.5">
            <ArrowRightLeft className="w-5 h-5" /> {t('list.transfers')}
          </Link>
          {canCreateClass && (
            <>
              <button onClick={() => setShowReferentiel(true)} className="btn-secondary flex items-center gap-2 py-2.5">
                <Layers className="w-5 h-5" /> {t('list.referential')}
              </button>
              <button onClick={() => setShowForm(true)} className="btn-primary flex items-center gap-2 py-2.5">
                <Plus className="w-5 h-5" /> {t('list.newClass')}
              </button>
            </>
          )}
        </div>
      }
    >
      <SmartFilterBar
        fields={filterFields}
        values={values}
        onChange={setFilter}
        onReset={reset}
        activeFilters={activeFilters}
        resultCount={filteredClasses.length}
        resultLabel={t('list.resultLabel')}
        loading={loading}
        className="mb-6"
      />

      <Modal open={showReferentiel} onClose={() => setShowReferentiel(false)} title={t('list.referentialTitle')}>
        <p className="text-sm text-slate-500 mb-4">
          {t('list.referentialDesc', { year: anneeScolaire })}
        </p>
        <div className="max-h-80 overflow-y-auto space-y-4 mb-4">
          {CAMEROON_SECTIONS.map((sec: SectionRef) => (
            <div key={sec.id}>
              <p className="font-semibold text-slate-700 mb-2">{sec.label}</p>
              {sec.cycles.map(cycle => (
                <div key={cycle.nom} className="mb-3 pl-2">
                  <p className="text-xs text-slate-400 mb-1.5">{cycle.nom}</p>
                  <div className="space-y-1">
                    {cycle.niveaux.map(nv => {
                      const key = `${sec.id}::${nv.code}`
                      const created = isNiveauCreated(sec.id, nv.nomDefaut)
                      return (
                        <label key={nv.code} className={`flex items-center gap-3 p-2 rounded-lg cursor-pointer ${created ? 'opacity-50' : 'hover:bg-slate-50'}`}>
                          <input
                            type="checkbox"
                            disabled={created}
                            checked={selectedNiveaux.has(key)}
                            onChange={() => toggleNiveau(sec.id, nv.code)}
                            className="rounded border-slate-300"
                          />
                          <span className="text-sm text-slate-700">{nv.nomDefaut}</span>
                          <span className="text-xs text-slate-400">{nv.label}</span>
                          {created && <Badge variant="success" size="sm">{t('list.exists')}</Badge>}
                        </label>
                      )
                    })}
                  </div>
                </div>
              ))}
            </div>
          ))}
        </div>
        <button
          onClick={handleBulkCreate}
          disabled={saving || selectedNiveaux.size === 0}
          className="w-full btn-primary"
        >
          {saving ? t('list.creating') : t('list.createCount', { count: selectedNiveaux.size })}
        </button>
      </Modal>

      <Modal open={showForm} onClose={() => setShowForm(false)} title={t('list.modalNewTitle')}>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('list.fields.section')}</label>
            <select value={form.section} onChange={e => { up('section', e.target.value); up('niveau', '') }} className="input-field">
              <option value="francophone">{te.section('francophone')}</option>
              <option value="anglophone">{te.section('anglophone')}</option>
              <option value="maternelle">{te.section('maternelle')}</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('list.fields.level')}</label>
            <select value={form.niveau} onChange={e => {
              const sec = CAMEROON_SECTIONS.find(s => s.id === form.section)
              const nv = sec?.cycles.flatMap(c => c.niveaux).find(n => n.code === e.target.value)
              up('niveau', e.target.value)
              if (nv) up('nom', nv.nomDefaut)
            }} className="input-field">
              <option value="">{t('list.fields.chooseLevel')}</option>
              {CAMEROON_SECTIONS.find(s => s.id === form.section)?.cycles.flatMap(c =>
                c.niveaux.map(nv => (
                  <option key={nv.code} value={nv.code}>{nv.nomDefaut} ΓÇö {nv.label}</option>
                ))
              )}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('list.fields.className')}</label>
            <input value={form.nom} onChange={e => up('nom', e.target.value)}
              placeholder={t('list.fields.classNamePlaceholder')}
              className="input-field" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('list.fields.schoolYear')}</label>
              <input value={form.annee_scolaire} onChange={e => up('annee_scolaire', e.target.value)} className="input-field" />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('list.fields.maxCapacity')}</label>
              <input type="number" value={form.capacite_max} onChange={e => up('capacite_max', e.target.value)} className="input-field" />
            </div>
          </div>
          <button onClick={handleCreate} disabled={saving || !form.nom} className="w-full btn-primary">
            {saving ? t('list.creating') : t('list.createClass')}
          </button>
        </div>
      </Modal>

      {loading ? (
        <div className="card p-16 text-center text-slate-400">{tc('loading')}</div>
      ) : classes.length === 0 ? (
        <EmptyState
          icon={School}
          title={t('list.emptyTitle')}
          description={t('list.emptyDescription')}
          action={
            canCreateClass ? (
              <button onClick={() => setShowReferentiel(true)} className="btn-primary">
                {t('list.emptyAction')}
              </button>
            ) : undefined
          }
        />
      ) : filteredClasses.length === 0 ? (
        <EmptyState
          icon={Search}
          title={t('list.noMatchTitle')}
          description={t('list.noMatchDescription')}
          action={
            <button onClick={reset} className="btn-secondary">
              {t('list.resetFilters')}
            </button>
          }
        />
      ) : (
        <div className="space-y-8">
          {Object.entries(grouped).map(([section, items]) => (
            <div key={section}>
              <h2 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                {te.section(section)}
                <span className="text-slate-400 font-normal normal-case">({items.length})</span>
              </h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {items.map(c => {
                  const taux = c.capacite_max > 0 ? Math.round((c.nb_eleves / c.capacite_max) * 100) : 0
                  const plein = c.nb_eleves >= c.capacite_max
                  return (
                    <Link
                      key={c.id}
                      href={`/${slug}/classes/${c.id}`}
                      className="card p-5 hover:shadow-md hover:border-emerald-300 border border-transparent transition-all group block"
                    >
                      <div className="flex items-start justify-between mb-3">
                        <div>
                          <h3 className="font-bold text-slate-800 text-lg group-hover:text-emerald-600 transition-colors">{c.nom}</h3>
                          {c.niveau && c.niveau !== c.nom && (
                            <p className="text-xs text-slate-400 mt-0.5">{c.niveau}</p>
                          )}
                        </div>
                        <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-emerald-500 transition-colors shrink-0" />
                      </div>
                      <p className="text-sm text-slate-400 mb-4">{c.annee_scolaire}</p>
                      <div className="mb-3">
                        <div className="flex justify-between text-sm text-slate-600 mb-1.5">
                          <span className="font-medium">{t('list.studentsCount', { count: c.nb_eleves })}</span>
                          <span>{t('list.places', { count: c.capacite_max })}</span>
                        </div>
                        <div className="w-full bg-slate-100 rounded-full h-2">
                          <div
                            className={`h-2 rounded-full transition-all ${plein ? 'bg-red-500' : taux > 80 ? 'bg-amber-500' : 'bg-emerald-500'}`}
                            style={{ width: `${Math.min(taux, 100)}%` }}
                          />
                        </div>
                      </div>
                      <div className="pt-3 border-t border-slate-100" onClick={e => e.preventDefault()}>
                        <label className="flex items-center gap-1.5 text-xs font-medium text-slate-500 mb-1.5">
                          <UserCheck className="w-3.5 h-3.5" /> {t('list.titulaire')}
                        </label>
                        <select
                          value={c.personnel_id || ''}
                          onClick={e => e.stopPropagation()}
                          onChange={e => { e.stopPropagation(); handleAssignEnseignant(c.id, e.target.value) }}
                          className="input-field text-sm py-2"
                        >
                          <option value="">
                            {c.enseignant_nom ? `${c.enseignant_nom}${c.enseignant_prenom ? ` ${c.enseignant_prenom}` : ''}` : t('list.notAssigned')}
                          </option>
                          {enseignants.filter(en => en.id !== c.personnel_id).map(en => (
                            <option key={en.id} value={en.id}>
                              {en.nom}{en.prenom ? ` ${en.prenom}` : ''}
                            </option>
                          ))}
                        </select>
                      </div>
                      <div className="mt-3 flex items-center justify-between">
                        {plein ? (
                          <Badge variant="danger">{t('list.full')}</Badge>
                        ) : taux > 80 ? (
                          <Badge variant="warning">{t('list.almostFull')}</Badge>
                        ) : (
                          <span className="text-sm text-slate-400">{t('list.available', { pct: 100 - taux })}</span>
                        )}
                        <span className="text-xs text-emerald-600 font-medium opacity-0 group-hover:opacity-100 transition-opacity">
                          {tc('viewDetails')}
                        </span>
                      </div>
                    </Link>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </PageShell>
  )
}

'use client'

import { Suspense, useState, useEffect, useCallback, useMemo } from 'react'
import { useTranslations } from 'next-intl'
import { GripVertical, ArrowRightLeft } from 'lucide-react'
import toast from 'react-hot-toast'
import PageShell from '@/components/layout/PageShell'
import SmartFilterBar from '@/components/filters/SmartFilterBar'
import { useSmartFilters } from '@/hooks/useSmartFilters'
import { useSectionOptions, useTranslatedEnums } from '@/hooks/useTranslatedEnums'

interface Classe {
  id: string
  nom: string
  section: string
  capacite_max: number
  nb_eleves: number
}

interface Eleve {
  id: string
  nom: string
  prenom: string
  numero_matricule: string
  sexe: string
  classe_id: string | null
}

function TransfersFallback() {
  const t = useTranslations('classes')
  const tc = useTranslations('common')

  return (
    <PageShell title={t('transfers.title')} breadcrumb={t('transfers.breadcrumb')}>
      <div className="card p-16 text-center text-slate-400">{tc('loading')}</div>
    </PageShell>
  )
}

export default function ClassTransferBoard() {
  return (
    <Suspense fallback={<TransfersFallback />}>
      <ClassTransferBoardContent />
    </Suspense>
  )
}

function ClassTransferBoardContent() {
  const t = useTranslations('classes')
  const tc = useTranslations('common')
  const tf = useTranslations('filters')
  const te = useTranslatedEnums()
  const sectionOptions = useSectionOptions()
  const [classes, setClasses] = useState<Classe[]>([])
  const [eleves, setEleves] = useState<Eleve[]>([])
  const [loading, setLoading] = useState(true)
  const [draggingId, setDraggingId] = useState<string | null>(null)
  const [transferring, setTransferring] = useState(false)

  const filterFields = useMemo(() => [
    {
      key: 'section',
      type: 'pills' as const,
      label: tf('section.label'),
      options: [
        { value: 'tous', label: tf('allFeminine') },
        ...sectionOptions.filter(s => s.value).map(s => ({ value: s.value, label: s.label })),
      ],
      defaultValue: 'tous',
    },
    { key: 'q', type: 'search' as const, placeholder: t('transfers.searchPlaceholder'), debounce: true },
  ], [t, tf, sectionOptions])

  const { values, debouncedValues, setFilter, reset, activeFilters } = useSmartFilters(filterFields)

  const fetchData = useCallback(async () => {
    setLoading(true)
    const [cRes, eRes] = await Promise.all([
      fetch('/api/classes'),
      fetch('/api/eleves'),
    ])
    const cData = await cRes.json()
    const eData = await eRes.json()
    setClasses(cData.classes || [])
    setEleves((eData.eleves || []).filter((e: Eleve & { statut?: string }) => e.statut !== 'archive'))
    setLoading(false)
  }, [])

  useEffect(() => { fetchData() }, [fetchData])

  const filteredClasses = values.section === 'tous'
    ? classes
    : classes.filter(c => c.section === values.section)

  const searchQ = debouncedValues.q?.toLowerCase().trim() ?? ''

  const getElevesForClasse = (classeId: string | null) => {
    let list = eleves.filter(e => (classeId ? e.classe_id === classeId : !e.classe_id))
    if (searchQ) {
      list = list.filter(e =>
        `${e.nom} ${e.prenom} ${e.numero_matricule}`.toLowerCase().includes(searchQ)
      )
    }
    return list
  }

  const visibleEleveCount = useMemo(() => {
    const sansClasse = getElevesForClasse(null).length
    const inClasses = filteredClasses.reduce((s, c) => s + getElevesForClasse(c.id).length, 0)
    return sansClasse + inClasses
  }, [eleves, filteredClasses, searchQ])

  const handleDrop = async (eleveId: string, targetClasseId: string | null) => {
    const eleve = eleves.find(e => e.id === eleveId)
    if (!eleve || eleve.classe_id === targetClasseId) return

    setTransferring(true)
    const res = await fetch('/api/eleves/transfer', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ eleve_id: eleveId, classe_id: targetClasseId }),
    })
    const data = await res.json()
    setTransferring(false)

    if (!res.ok) {
      toast.error(data.error || t('transfers.transferError'))
      return
    }

    setEleves(prev => prev.map(e =>
      e.id === eleveId ? { ...e, classe_id: targetClasseId } : e
    ))
    toast.success(t('transfers.transferSuccess', { name: `${eleve.nom} ${eleve.prenom}` }))
    fetchData()
  }

  const onDragStart = (e: React.DragEvent, eleveId: string) => {
    e.dataTransfer.setData('text/eleve-id', eleveId)
    e.dataTransfer.effectAllowed = 'move'
    setDraggingId(eleveId)
  }

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'
  }

  const onDrop = (e: React.DragEvent, classeId: string | null) => {
    e.preventDefault()
    const eleveId = e.dataTransfer.getData('text/eleve-id')
    setDraggingId(null)
    if (eleveId) handleDrop(eleveId, classeId)
  }

  const renderColumn = (classe: Classe | null) => {
    const classeId = classe?.id ?? null
    const columnEleves = getElevesForClasse(classeId)
    const isOverCapacity = classe && columnEleves.length > classe.capacite_max

    return (
      <div
        key={classe?.id ?? 'sans-classe'}
        onDragOver={onDragOver}
        onDrop={e => onDrop(e, classeId)}
        className={`card flex flex-col min-w-[260px] max-w-[300px] shrink-0 transition-all ${
          draggingId ? 'ring-2 ring-emerald-400/30' : ''
        }`}
      >
        <div className="p-4 border-b border-slate-200 dark:border-slate-600">
          <h3 className="font-bold text-slate-800 text-sm">
            {classe ? classe.nom : t('transfers.noClass')}
          </h3>
          <p className="text-xs text-slate-500 mt-0.5">
            {classe ? te.section(classe.section) : t('transfers.notAssigned')}
            {' ┬╖ '}
            <span className={isOverCapacity ? 'text-red-500 font-semibold' : ''}>
              {columnEleves.length}
              {classe ? ` / ${classe.capacite_max}` : ''}
            </span>
          </p>
        </div>
        <div className="flex-1 p-2 space-y-1.5 min-h-[120px] max-h-[420px] overflow-y-auto">
          {columnEleves.length === 0 ? (
            <p className="text-xs text-slate-400 text-center py-8">
              {t('transfers.dropHint')}
            </p>
          ) : columnEleves.map(el => (
            <div
              key={el.id}
              draggable={!transferring}
              onDragStart={e => onDragStart(e, el.id)}
              onDragEnd={() => setDraggingId(null)}
              className={`flex items-center gap-2 p-2.5 rounded-lg border cursor-grab active:cursor-grabbing transition-all ${
                draggingId === el.id
                  ? 'opacity-50 border-emerald-400 bg-emerald-50'
                  : 'border-slate-200 bg-white hover:border-emerald-300 hover:shadow-sm'
              }`}
            >
              <GripVertical className="w-4 h-4 text-slate-300 shrink-0" />
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold text-slate-800 truncate">
                  {el.nom} {el.prenom}
                </p>
                <p className="text-xs text-slate-400 font-mono truncate">{el.numero_matricule}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <PageShell
      title={t('transfers.title')}
      subtitle={t('transfers.subtitle')}
      breadcrumb={t('transfers.breadcrumb')}
    >
      <SmartFilterBar
        fields={filterFields}
        values={values}
        onChange={setFilter}
        onReset={reset}
        activeFilters={activeFilters}
        resultCount={visibleEleveCount}
        resultLabel={t('transfers.resultLabel')}
        loading={loading}
        className="mb-6"
      />

      <div className="card p-4 mb-6 flex items-start gap-3 bg-emerald-50 border-emerald-200">
        <ArrowRightLeft className="w-5 h-5 text-emerald-600 shrink-0 mt-0.5" />
        <div className="text-sm text-emerald-800">
          <p className="font-semibold">{t('transfers.howToTitle')}</p>
          <p className="text-emerald-700 mt-1">
            {t('transfers.howToBody')}
          </p>
        </div>
      </div>

      {loading ? (
        <div className="card p-16 text-center text-slate-400">{tc('loading')}</div>
      ) : (
        <div className="flex gap-4 overflow-x-auto pb-4">
          {renderColumn(null)}
          {filteredClasses.map(c => renderColumn(c))}
        </div>
      )}

      {transferring && (
        <div className="fixed bottom-6 right-6 bg-slate-900 text-white px-4 py-2 rounded-xl text-sm shadow-lg">
          {t('transfers.transferring')}
        </div>
      )}
    </PageShell>
  )
}

import { cookies } from 'next/headers'
import Link from 'next/link'
import { getLocale, getTranslations } from 'next-intl/server'
import { verifyToken } from '@/lib/auth'
import { prepareSchoolDb } from '@/lib/school-db'
import { getDb } from '@/lib/db-server'
import { getElevesSituation } from '@/lib/paiements-utils'
import { studentLinks } from '@/lib/student-context-links'
import { getIntlLocale, type Locale } from '@/i18n/config'
import PageShell from '@/components/layout/PageShell'
import EncaissementsChart from '@/components/dashboard/EncaissementsChart'
import ClassesPaiementChart from '@/components/dashboard/ClassesPaiementChart'
import {
  Users, DoorOpen, UserCheck, Banknote,
  CreditCard, ClipboardList, CheckSquare,
  UserPlus, TrendingUp, BookOpen, Calendar,
  AlertTriangle, Info, AlertCircle,
} from 'lucide-react'


type Alert = { level: 'danger' | 'warn' | 'info'; text: string; sub: string }

const STAT_STYLES = [
  { bar: 'bg-emerald-500', icon: 'bg-emerald-100 text-emerald-600', trend: 'text-emerald-600' },
  { bar: 'bg-blue-500',    icon: 'bg-blue-100    text-blue-600',    trend: 'text-slate-400'   },
  { bar: 'bg-violet-500',  icon: 'bg-violet-100  text-violet-600',  trend: 'text-slate-400'   },
  { bar: 'bg-amber-500',   icon: 'bg-amber-100   text-amber-600',   trend: 'text-emerald-600' },
]

const MODULE_STYLES = [
  { icon: 'bg-emerald-100 text-emerald-600' },
  { icon: 'bg-amber-100   text-amber-600'   },
  { icon: 'bg-blue-100    text-blue-600'    },
  { icon: 'bg-violet-100  text-violet-600'  },
  { icon: 'bg-pink-100    text-pink-600'    },
  { icon: 'bg-teal-100    text-teal-600'    },
  { icon: 'bg-orange-100  text-orange-600'  },
  { icon: 'bg-indigo-100  text-indigo-600'  },
]
const MODULE_ICONS = [Users, CreditCard, DoorOpen, ClipboardList, BookOpen, CheckSquare, UserCheck, Calendar]

const ALERT_ICON: Record<Alert['level'], React.ElementType> = {
  danger: AlertCircle,
  warn:   AlertTriangle,
  info:   Info,
}
const ALERT_BG: Record<Alert['level'], string> = {
  danger: 'bg-red-100 text-red-500',
  warn:   'bg-amber-100 text-amber-500',
  info:   'bg-blue-100 text-blue-500',
}


export default async function DashboardPage({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  const t = await getTranslations('dashboard')
  const tCommon = await getTranslations('common')
  const locale = (await getLocale()) as Locale
  const intlLocale = getIntlLocale(locale)

  const cookieStore = await cookies()
  const token = cookieStore.get('sm_token')?.value
  if (!token) return null
  const payload = await verifyToken(token)
  if (!payload) return null

  if (process.env.VERCEL && payload.ecole_slug) {
    await prepareSchoolDb(payload.ecole_slug)
  }

  const nom    = payload.nom as string
  const prenom = payload.prenom as string | undefined
  const initials = ((prenom?.[0] ?? '') + (nom?.[0] ?? '')).toUpperCase() || 'AD'

  const db = getDb(slug)

  const ecole = db.prepare('SELECT * FROM ecoles WHERE slug = ?').get(slug) as { id: string; nom: string } | undefined
  if (!ecole) return null

  // ΓöÇΓöÇ stats ΓöÇΓöÇ
  const totalEleves = (db.prepare(
    'SELECT COUNT(*) as count FROM eleves WHERE ecole_id = ? AND statut = ?'
  ).get(ecole?.id, 'actif') as any)?.count ?? 0

  const totalClasses = (db.prepare(
    'SELECT COUNT(*) as count FROM classes WHERE ecole_id = ?'
  ).get(ecole?.id) as any)?.count ?? 0

  const totalPersonnel = (db.prepare(
    'SELECT COUNT(*) as count FROM personnel WHERE ecole_id = ?'
  ).get(ecole?.id) as any)?.count ?? 0

  const debutMois = new Date(); debutMois.setDate(1)
  const totalMois = (db.prepare(`
    SELECT COALESCE(SUM(montant), 0) as total FROM paiements
    WHERE ecole_id = ? AND date_paiement >= ?
  `).get(ecole.id, debutMois.toISOString().split('T')[0]) as { total: number })?.total ?? 0

  const debutMoisPrecedent = new Date(debutMois)
  debutMoisPrecedent.setMonth(debutMoisPrecedent.getMonth() - 1)
  const finMoisPrecedent = new Date(debutMois)
  finMoisPrecedent.setDate(0)
  const totalMoisPrecedent = (db.prepare(`
    SELECT COALESCE(SUM(montant), 0) as total FROM paiements
    WHERE ecole_id = ? AND date_paiement >= ? AND date_paiement <= ?
  `).get(
    ecole.id,
    debutMoisPrecedent.toISOString().split('T')[0],
    finMoisPrecedent.toISOString().split('T')[0],
  ) as { total: number })?.total ?? 0

  let trendCollecte = t('stats.noCollection')
  let trendCollecteUp = false
  if (totalMoisPrecedent > 0) {
    const pct = Math.round(((totalMois - totalMoisPrecedent) / totalMoisPrecedent) * 100)
    trendCollecteUp = pct >= 0
    trendCollecte = t('stats.trendVsLastMonth', { pct: `${pct >= 0 ? '+' : ''}${pct}` })
  } else if (totalMois > 0) {
    trendCollecte = t('stats.firstCollection')
    trendCollecteUp = true
  }

  // ΓöÇΓöÇ alertes ΓöÇΓöÇ
  const classesVides = (db.prepare(`
    SELECT COUNT(*) as count FROM classes c WHERE c.ecole_id = ?
    AND (SELECT COUNT(*) FROM eleves e WHERE e.classe_id = c.id AND e.statut = 'actif') = 0
  `).get(ecole?.id) as any)?.count ?? 0

  const impayes = (db.prepare(`
    SELECT COUNT(*) as count FROM eleves e
    WHERE e.ecole_id = ? AND e.statut = 'actif'
    AND COALESCE((SELECT SUM(pa.montant) FROM paiements pa WHERE pa.eleve_id = e.id), 0)
      < COALESCE((SELECT SUM(tc.montant_attendu) FROM tranches_config tc WHERE tc.classe_id = e.classe_id), 0)
  `).get(ecole.id) as { count: number })?.count ?? 0

  const classesSansEnseignant = (db.prepare(`
    SELECT COUNT(*) as count FROM classes
    WHERE ecole_id = ? AND (personnel_id IS NULL OR personnel_id = '')
  `).get(ecole.id) as { count: number })?.count ?? 0

  const alerts: Alert[] = []
  if (classesVides > 0)
    alerts.push({ level: 'danger', text: t('alerts.emptyClasses', { count: classesVides }), sub: t('alerts.emptyClassesSub') })
  if (impayes > 0)
    alerts.push({ level: 'warn', text: t('alerts.unpaid', { count: impayes }), sub: t('alerts.unpaidSub') })
  if (classesSansEnseignant > 0)
    alerts.push({ level: 'warn', text: t('alerts.noTeacher', { count: classesSansEnseignant }), sub: t('alerts.noTeacherSub') })
  if (alerts.length === 0)
    alerts.push({
      level: 'info',
      text: t('alerts.allGood'),
      sub: t('alerts.updatedOn', { date: new Date().toLocaleDateString(intlLocale) }),
    })

  // ΓöÇΓöÇ taux d'├⌐l├¿ves ├á jour dans leurs paiements, par classe ΓöÇΓöÇ
  // S'appuie sur la m├¬me logique m├⌐tier que la page paiements
  // (getElevesSituation) pour rester coh├⌐rent avec le badge "impay├⌐s" d├⌐j├á
  // affich├⌐ ailleurs, plut├┤t que de recalculer un crit├¿re diff├⌐rent ici.
  // Les ├⌐l├¿ves "non_configure" (aucune tranche d├⌐finie pour leur classe)
  // sont exclus du calcul plut├┤t que compt├⌐s comme impay├⌐s, car il n'y a
  // rien ├á leur reprocher si la classe n'a pas encore de tranches.
  const { situations } = getElevesSituation(db, ecole?.id ?? '')
  const classesPaiementMap = new Map<string, { classe: string; effectif: number; payes: number }>()
  for (const s of situations) {
    if (!s.classe_id || s.statut === 'non_configure') continue
    const entry = classesPaiementMap.get(s.classe_id) ?? { classe: s.classe_nom ?? 'ΓÇö', effectif: 0, payes: 0 }
    entry.effectif += 1
    if (s.statut === 'paye') entry.payes += 1
    classesPaiementMap.set(s.classe_id, entry)
  }
  const classesPaiement = Array.from(classesPaiementMap.values())
    .map(c => ({ ...c, pct: c.effectif > 0 ? Math.round((c.payes / c.effectif) * 100) : 0 }))
    .sort((a, b) => a.pct - b.pct)

  const capaciteMoyenne = totalClasses > 0
    ? Math.round((db.prepare('SELECT COALESCE(AVG(capacite_max), 60) as avg FROM classes WHERE ecole_id = ?').get(ecole?.id) as { avg: number }).avg)
    : 60

  // ΓöÇΓöÇ derniers paiements ΓöÇΓöÇ
  const derniersPaiements = db.prepare(`
    SELECT p.montant, p.date_paiement, p.mode_paiement,
           e.id as eleve_id, e.nom as eleve_nom, e.prenom as eleve_prenom,
           e.numero_matricule,
           c.nom as classe_nom
    FROM paiements p
    JOIN eleves e ON e.id = p.eleve_id
    LEFT JOIN classes c ON c.id = e.classe_id
    WHERE p.ecole_id = ?
    ORDER BY p.created_at DESC LIMIT 5
  `).all(ecole?.id) as any[]

  // ΓöÇΓöÇ licence ΓöÇΓöÇ
  const licence = db.prepare(
    'SELECT * FROM licences WHERE ecole_id = ? AND is_active = 1 ORDER BY date_fin DESC LIMIT 1'
  ).get(ecole?.id) as any

  const licenceColor: Record<string, string> = {
    starter:  'bg-slate-700 text-slate-200',
    standard: 'bg-blue-900  text-blue-200',
    premium:  'bg-emerald-600 text-white',
  }

  const stats = [
    { label: t('stats.activeStudents'), value: totalEleves.toLocaleString(intlLocale), suffix: undefined, Icon: Users, trend: t('stats.inClasses', { count: totalClasses }), trendUp: false },
    { label: t('stats.classes'), value: totalClasses.toLocaleString(intlLocale), suffix: undefined, Icon: DoorOpen, trend: t('stats.avgCapacity', { count: capaciteMoyenne }), trendUp: false },
    { label: t('stats.staff'), value: totalPersonnel.toLocaleString(intlLocale), suffix: undefined, Icon: UserCheck, trend: totalPersonnel === 0 ? t('stats.noStaff') : t('stats.activeMembers'), trendUp: false },
    { label: t('stats.collectedThisMonth'), value: Number(totalMois).toLocaleString(intlLocale), suffix: tCommon('currency'), Icon: Banknote, trend: trendCollecte, trendUp: trendCollecteUp },
  ]

  const modules = [
    { label: t('modules.students.label'), desc: t('modules.students.desc'), href: `/${slug}/eleves` },
    { label: t('modules.payments.label'), desc: t('modules.payments.desc'), href: `/${slug}/paiements` },
    { label: t('modules.classes.label'), desc: t('modules.classes.desc'), href: `/${slug}/classes` },
    { label: t('modules.grades.label'), desc: t('modules.grades.desc'), href: `/${slug}/notes/saisie` },
    { label: t('modules.reportCards.label'), desc: t('modules.reportCards.desc'), href: `/${slug}/notes/bulletins` },
    { label: t('modules.attendance.label'), desc: t('modules.attendance.desc'), href: `/${slug}/presences` },
    { label: t('modules.staff.label'), desc: t('modules.staff.desc'), href: `/${slug}/personnel` },
    { label: t('modules.announcements.label'), desc: t('modules.announcements.desc'), href: `/${slug}/annonces` },
  ]

  const modeBadge: Record<string, string> = {
    especes:      'bg-emerald-100 text-emerald-700',
    orange_money: 'bg-orange-100  text-orange-700',
    mtn_momo:     'bg-yellow-100  text-yellow-700',
    virement:     'bg-blue-100    text-blue-700',
  }
  const modeLabel: Record<string, string> = {
    especes: t('payments.methods.especes'),
    orange_money: t('payments.methods.orange_money'),
    mtn_momo: t('payments.methods.mtn_momo'),
    virement: t('payments.methods.virement'),
  }

  const dateStr = new Date().toLocaleDateString(intlLocale, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })


  return (
    <PageShell
      title={t('greeting', { name: prenom ?? nom })}
      subtitle={
        <span className="flex items-center gap-2">
          <span className="inline-block w-2 h-2 rounded-full bg-emerald-500" />
          {ecole?.nom} ΓÇö {dateStr}
        </span>
      }
      breadcrumb={t('breadcrumb')}
      actions={
        <Link
          href={`/${slug}/eleves/nouveau`}
          className="btn-primary flex items-center gap-2 py-2.5"
        >
          <UserPlus size={17} />
          {t('enrollStudent')}
        </Link>
      }
    >
      <div className="flex flex-col gap-7">
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-5">
          {stats.map((stat, i) => {
            const s = STAT_STYLES[i]; const Icon = stat.Icon
            return (
              <div key={i} className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
                <div className={`h-1.5 ${s.bar}`} />
                <div className="p-6">
                  <div className={`w-11 h-11 rounded-xl flex items-center justify-center mb-5 ${s.icon}`}>
                    <Icon size={22} />
                  </div>
                  <p className="text-sm text-slate-500 mb-1">{stat.label}</p>
                  <p className="text-4xl font-bold text-slate-800 leading-none">
                    {stat.value}
                    {stat.suffix && <span className="text-base font-normal text-slate-400 ml-2">{stat.suffix}</span>}
                  </p>
                  <p className={`text-sm mt-2.5 flex items-center gap-1 ${s.trend}`}>
                    {stat.trendUp && <TrendingUp size={13} />}
                    {stat.trend}
                  </p>
                </div>
              </div>
            )
          })}
        </div>

        {/* graphiques */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">

          {/* encaissements ΓÇö graphique interactif avec filtres */}
          <EncaissementsChart slug={slug} />

          {/* taux de paiement par classe */}
          <ClassesPaiementChart data={classesPaiement} slug={slug} />
        </div>

        {/* modules + alertes */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          <div className="lg:col-span-2 flex flex-col gap-3">
            <h2 className="text-xs font-semibold text-slate-400 uppercase tracking-widest">{t('sections.modules')}</h2>
            <div className="grid grid-cols-3 gap-3">
              {modules.map((mod, i) => {
                const Icon = MODULE_ICONS[i]; const s = MODULE_STYLES[i]
                return (
                  <Link key={i} href={mod.href}
                    className="bg-white rounded-2xl border border-slate-200 p-5 hover:border-emerald-400 hover:shadow-sm transition-all group flex flex-col gap-3">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${s.icon}`}>
                      <Icon size={19} />
                    </div>
                    <div>
                      <p className="text-base font-semibold text-slate-800 group-hover:text-emerald-600 transition-colors leading-tight">{mod.label}</p>
                      <p className="text-sm text-slate-400 leading-tight mt-0.5">{mod.desc}</p>
                    </div>
                  </Link>
                )
              })}
            </div>
          </div>

          {/* alertes */}
          <div className="flex flex-col gap-3">
            <h2 className="text-xs font-semibold text-slate-400 uppercase tracking-widest">{t('sections.alerts')}</h2>
            <div className="bg-white rounded-2xl border border-slate-200 divide-y divide-slate-100 flex-1">
              {alerts.map((a, i) => {
                const Icon = ALERT_ICON[a.level]
                return (
                  <div key={i} className="flex items-start gap-3.5 p-5">
                    <div className={`mt-0.5 w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 ${ALERT_BG[a.level]}`}>
                      <Icon size={14} />
                    </div>
                    <div>
                      <p className="text-sm text-slate-700 leading-snug font-medium">{a.text}</p>
                      <p className="text-xs text-slate-400 mt-1">{a.sub}</p>
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        </div>

        {/* derniers paiements + acc├¿s rapides */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">

          {/* tableau paiements */}
          <div className="lg:col-span-2 flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <h2 className="text-xs font-semibold text-slate-400 uppercase tracking-widest">{t('sections.recentPayments')}</h2>
              <Link href={`/${slug}/paiements`} className="text-xs text-emerald-600 hover:underline font-medium">{tCommon('seeAll')}</Link>
            </div>
            <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
              {derniersPaiements.length === 0 ? (
                <div className="p-10 text-center text-slate-400 text-sm">{t('payments.empty')}</div>
              ) : (
                <table className="w-full">
                  <thead>
                    <tr className="border-b border-slate-100 bg-slate-50">
                      <th className="text-left text-xs font-semibold text-slate-400 px-5 py-3">{t('payments.student')}</th>
                      <th className="text-left text-xs font-semibold text-slate-400 px-5 py-3">{t('payments.class')}</th>
                      <th className="text-left text-xs font-semibold text-slate-400 px-5 py-3">{t('payments.method')}</th>
                      <th className="text-right text-xs font-semibold text-slate-400 px-5 py-3">{t('payments.amount')}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {derniersPaiements.map((p: { eleve_id: string; eleve_nom: string; eleve_prenom: string; numero_matricule?: string; classe_nom?: string; mode_paiement: string; montant: number }, i: number) => (
                      <tr key={i} className="hover:bg-slate-50 transition-colors">
                        <td className="px-5 py-3.5 text-sm font-medium text-slate-700">
                          <Link href={studentLinks(slug, {
                            id: p.eleve_id,
                            nom: p.eleve_nom,
                            prenom: p.eleve_prenom,
                            numero_matricule: p.numero_matricule || '',
                          }).fiche} className="hover:text-emerald-700">
                            {p.eleve_prenom} {p.eleve_nom}
                          </Link>
                        </td>
                        <td className="px-5 py-3.5 text-sm text-slate-500">{p.classe_nom ?? 'ΓÇö'}</td>
                        <td className="px-5 py-3.5">
                          <span className={`text-xs font-medium px-2.5 py-1 rounded-full ${modeBadge[p.mode_paiement] ?? 'bg-slate-100 text-slate-500'}`}>
                            {modeLabel[p.mode_paiement] ?? p.mode_paiement}
                          </span>
                        </td>
                        <td className="px-5 py-3.5 text-sm font-bold text-slate-800 text-right">
                          {Number(p.montant).toLocaleString(intlLocale)} <span className="font-normal text-slate-400 text-xs">{tCommon('currency')}</span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>

          {/* acc├¿s rapides */}
          <div className="flex flex-col gap-3">
            <h2 className="text-xs font-semibold text-slate-400 uppercase tracking-widest">{t('sections.quickAccess')}</h2>
            <div className="flex flex-col gap-2">
              {[
                { label: t('quickAccess.newPayment.label'), desc: t('quickAccess.newPayment.desc'), href: `/${slug}/paiements/nouveau`, Icon: CreditCard, color: 'text-amber-600  bg-amber-100' },
                { label: t('quickAccess.enterGrades.label'), desc: t('quickAccess.enterGrades.desc'), href: `/${slug}/notes/saisie`, Icon: BookOpen, color: 'text-violet-600 bg-violet-100' },
                { label: t('quickAccess.attendance.label'), desc: t('quickAccess.attendance.desc'), href: `/${slug}/presences`, Icon: CheckSquare, color: 'text-teal-600   bg-teal-100' },
                { label: t('quickAccess.settings.label'), desc: t('quickAccess.settings.desc'), href: `/${slug}/parametres`, Icon: Calendar, color: 'text-blue-600   bg-blue-100' },
              ].map(({ label, desc, href, Icon, color }, i) => (
                <Link key={i} href={href}
                  className="bg-white rounded-2xl border border-slate-200 p-4 hover:border-emerald-400 hover:shadow-sm transition-all group flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${color}`}>
                    <Icon size={18} />
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-slate-800 group-hover:text-emerald-600 transition-colors">{label}</p>
                    <p className="text-xs text-slate-400 mt-0.5">{desc}</p>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        </div>

      </div>
    </PageShell>
  )
}

