    setLoading(true)
    const res = await fetch(`/api/eleves/${id}`)
    if (!res.ok) { router.push(`/${slug}/eleves`); return }
    const data = await res.json()
    setEleve(data.eleve)
    setForm(data.eleve)
    setParents(data.parents || [])
    setPaiements(data.paiements || [])
    setNotes(data.notes || [])
    setPresences(data.presences || [])
