                        ? <span className="text-xs font-medium px-2 py-1 rounded-full bg-blue-50 text-blue-700">{t('detail.installment', { n: p.tranche_numero })}</span>
                        : <span className="text-xs text-slate-400">{t('detail.miscFees')}</span>}
                    </td>
                    <td className="px-4 py-3 font-semibold text-slate-800 text-sm">{p.montant.toLocaleString('fr-FR')} F</td>
                    <td className="px-4 py-3 text-sm text-slate-500">{p.mode_paiement ? te.paymentMethod(p.mode_paiement) : 'ΓÇö'}</td>
                    <td className="px-4 py-3 text-xs font-mono text-slate-400">{p.recu_numero || 'ΓÇö'}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-slate-50 border-t border-slate-200">
                <tr>
                  <td colSpan={2} className="px-4 py-3 text-sm font-semibold text-slate-600">{t('detail.total')}</td>
                  <td className="px-4 py-3 font-bold text-slate-800">{totalPaye.toLocaleString('fr-FR')} F</td>
                  <td colSpan={2} />
                </tr>
              </tfoot>
            </table>
          )}
        </div>
      )}

      {onglet === 'notes' && (
        <div>
          <div className="flex items-center gap-3 mb-4">
            <span className="text-sm text-slate-500">{t('detail.period')}</span>
            <div className="flex gap-2 flex-wrap">
              <button onClick={() => setPeriodeFiltre('tous')} className={`text-xs px-3 py-1.5 rounded-lg font-medium transition-colors ${periodeFiltre === 'tous' ? 'bg-slate-800 text-white' : 'bg-white border border-slate-200 text-slate-600'}`}>{t('detail.allPeriods')}</button>
              {periodes.map(p => (
                <button key={p} onClick={() => setPeriodeFiltre(p)} className={`text-xs px-3 py-1.5 rounded-lg font-medium capitalize transition-colors ${periodeFiltre === p ? 'bg-slate-800 text-white' : 'bg-white border border-slate-200 text-slate-600'}`}>{p}</button>
              ))}
            </div>
          </div>
          <div className="card overflow-hidden">
            {notesFiltrees.length === 0 ? (
              <div className="p-12 text-center text-slate-400 text-sm">{t('detail.noGrades')}</div>
            ) : (
              <table className="w-full">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>{[
                    t('detail.columns.subject'),
                    t('detail.columns.period'),
                    t('detail.columns.grade', { max: getNoteMax(eleve.section || 'francophone') }),
                    t('detail.columns.coef'),
                    t('detail.columns.appreciation'),
                  ].map(h => (
                    <th key={h} className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">{h}</th>
                  ))}</tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {notesFiltrees.map(n => (
                    <tr key={n.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3 text-sm font-medium text-slate-800">{n.matiere_nom}</td>
                      <td className="px-4 py-3"><span className="text-xs capitalize px-2 py-1 rounded-full bg-slate-100 text-slate-600">{n.periode}</span></td>
                      <td className={`px-4 py-3 text-sm ${noteColor(n.note)}`}>{n.note}</td>
                      <td className="px-4 py-3 text-sm text-slate-500">{n.coefficient}</td>
                      <td className="px-4 py-3 text-sm text-slate-500 italic">{n.appreciation || 'ΓÇö'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      )}

      {onglet === 'presences' && (
        <div>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-6">
            {presenceStats.map(({ statut, color }) => (
              <div key={statut} className="card p-4 text-center">
                <p className={`text-2xl font-bold ${color}`}>{presences.filter(p => p.statut === statut).length}</p>
                <p className="text-xs text-slate-500 mt-0.5">{te.presenceStatus(statut)}</p>
              </div>
            ))}
          </div>
          <div className="card overflow-hidden">
            {presences.length === 0 ? (
              <div className="p-12 text-center text-slate-400 text-sm">{t('detail.noAttendance')}</div>
            ) : (
              <table className="w-full">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>{[
                    t('detail.columns.date'),
                    t('detail.columns.status'),
                    t('detail.columns.observation'),
                  ].map(h => (
                    <th key={h} className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">{h}</th>
                  ))}</tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {presences.map(p => (
                    <tr key={p.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3 text-sm text-slate-600">{p.date}</td>
                      <td className="px-4 py-3"><span className={`text-xs font-semibold px-2.5 py-1 rounded-full ${statutPresenceStyle(p.statut)}`}>{te.presenceStatus(p.statut)}</span></td>
                      <td className="px-4 py-3 text-sm text-slate-500">{p.note || 'ΓÇö'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (<div><label className="block text-xs font-medium text-slate-500 mb-1">{label}</label>{children}</div>)
}

function InfoRow({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) {
  return (
    <div className="flex items-center justify-between py-2 border-b border-slate-50 last:border-0">
      <span className="flex items-center gap-1.5 text-xs text-slate-400">{icon} {label}</span>
      <span className="text-sm text-slate-700 font-medium">{value}</span>
    </div>
  )
}

'use client'

import { Suspense, useCallback, useEffect, useMemo, useState } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { Plus, Upload, UserX } from 'lucide-react'
import PageShell from '@/components/layout/PageShell'
import Badge from '@/components/ui/Badge'
import EmptyState from '@/components/ui/EmptyState'
import SmartFilterBar from '@/components/filters/SmartFilterBar'
import { useSmartFilters } from '@/hooks/useSmartFilters'
import { useClasses } from '@/hooks/useClasses'
import {
  useSectionOptions,
  useStudentStatutOptions,
  useStudentFilters,
  useTranslatedEnums,
} from '@/hooks/useTranslatedEnums'

interface Eleve {
  id: string
  numero_matricule: string
  nom: string
  prenom: string
  sexe: string
  section: string
  classe_nom: string
  photo_url: string | null
  parent_nom: string
  parent_telephone: string
  total_paye: number
  total_attendu: number
}

function ElevesPageContent() {
  const { slug } = useParams()
  const router = useRouter()
  const t = useTranslations('eleves')
  const tc = useTranslations('common')
  const tf = useTranslations('filters')
  const te = useTranslatedEnums()
  const { classes } = useClasses()
  const sectionOptions = useSectionOptions()
  const statutOptions = useStudentStatutOptions()
  const presets = useStudentFilters()
  const [eleves, setEleves] = useState<Eleve[]>([])
  const [loading, setLoading] = useState(true)

  const filterFields = useMemo(() => [
    {
      key: 'q',
      type: 'search' as const,
      placeholder: t('list.searchPlaceholder'),
      debounce: true,
    },
    {
      key: 'section',
      type: 'select' as const,
      label: tf('section.label'),
      options: sectionOptions,
      defaultValue: '',
    },
    {
      key: 'classe',
      type: 'select' as const,
      label: tf('class.label'),
      options: [{ value: '', label: t('list.allClasses') }],
      defaultValue: '',
    },
    {
      key: 'statut',
      type: 'select' as const,
      label: tf('payment.label'),
      options: statutOptions,
      defaultValue: 'tous',
    },
  ], [t, tf, sectionOptions, statutOptions])

  const fields = useMemo(() => {
    const classeOptions = [
      { value: '', label: t('list.allClasses') },
      { value: '__none__', label: tf('students.noClass') },
      ...classes.map(c => ({ value: c.id, label: c.nom })),
    ]
    return filterFields.map(f =>
      f.key === 'classe' ? { ...f, options: classeOptions } : f
    )
  }, [filterFields, classes, t, tf])

  const {
    values,
    debouncedValues,
    setFilter,
    applyPreset,
    reset,
    activeFilters,
  } = useSmartFilters(fields)

  const fetchEleves = useCallback(async () => {
    setLoading(true)
    const params = new URLSearchParams()
    if (debouncedValues.q) params.set('search', debouncedValues.q)
    if (debouncedValues.section) params.set('section', debouncedValues.section)
    if (debouncedValues.classe) params.set('classe_id', debouncedValues.classe)
    if (debouncedValues.statut && debouncedValues.statut !== 'tous') {
      params.set('statut_paiement', debouncedValues.statut)
    }

    const res = await fetch(`/api/eleves?${params}`)
    const data = await res.json()
    setEleves(data.eleves || [])
    setLoading(false)
  }, [debouncedValues])

  useEffect(() => { fetchEleves() }, [fetchEleves])

  const getStatutPaiement = (paye: number, attendu: number) => {
    if (attendu === 0) return { label: t('list.paymentNa'), variant: 'neutral' as const }
    const reste = attendu - paye
    if (reste <= 0) return { label: te.paymentStatus('paye'), variant: 'success' as const }
    if (paye > 0) return { label: te.paymentStatus('partiel'), variant: 'warning' as const }
    return { label: te.paymentStatus('impaye'), variant: 'danger' as const }
  }

  const columnHeaders = [
    t('list.columns.student'),
    t('list.columns.matricule'),
    t('list.columns.class'),
    t('list.columns.section'),
    t('list.columns.parentContact'),
    t('list.columns.payment'),
    '',
  ]

  return (
    <PageShell
      title={t('list.title')}
      subtitle={t('list.subtitle', { count: eleves.length })}
      breadcrumb={t('list.breadcrumb')}
      actions={
        <div className="flex items-center gap-2">
          <button onClick={() => router.push(`/${slug}/donnees`)}
            className="btn-secondary flex items-center gap-2 py-2.5">
            <Upload className="w-5 h-5" /> {t('list.importCsv')}
          </button>
          <button onClick={() => router.push(`/${slug}/eleves/nouveau`)}
            className="btn-primary flex items-center gap-2 py-2.5">
            <Plus className="w-5 h-5" /> {t('list.newStudent')}
          </button>
        </div>
      }
    >
      <SmartFilterBar
        fields={fields}
        values={values}
        onChange={setFilter}
        onReset={reset}
        activeFilters={activeFilters}
        presets={presets}
        onPreset={applyPreset}
        resultCount={eleves.length}
        resultLabel={t('list.resultLabel')}
        loading={loading}
        className="mb-6"
      />

      <div className="card overflow-hidden">
        {loading ? (
          <div className="p-16 text-center text-slate-400 text-base">{tc('loading')}</div>
        ) : eleves.length === 0 ? (
          <EmptyState
            icon={UserX}
            title={t('list.emptyTitle')}
            description={t('list.emptyDescription')}
            action={
              <button onClick={() => router.push(`/${slug}/eleves/nouveau`)} className="btn-primary">
                {t('list.emptyAction')}
              </button>
            }
          />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  {columnHeaders.map(h => (
                    <th key={h} className="text-left px-5 py-3.5 text-sm font-semibold text-slate-500 uppercase tracking-wide">
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {eleves.map((eleve) => {
                  const statut = getStatutPaiement(eleve.total_paye, eleve.total_attendu)
                  return (
                    <tr key={eleve.id}
                      onClick={() => router.push(`/${slug}/eleves/${eleve.id}`)}
                      className="hover:bg-emerald-50/50 transition-colors cursor-pointer group">
                      <td className="px-5 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 rounded-xl bg-slate-100 overflow-hidden shrink-0">
                            {eleve.photo_url ? (
                              <img src={eleve.photo_url} alt="" className="w-full h-full object-cover" />
                            ) : (
                              <div className="w-full h-full flex items-center justify-center text-slate-400 text-sm font-bold">
                                {eleve.prenom[0]}{eleve.nom[0]}
                              </div>
                            )}
                          </div>
                          <div>
                            <p className="font-semibold text-slate-800 text-base group-hover:text-emerald-700 transition-colors">
                              {eleve.nom} {eleve.prenom}
                            </p>
                            <p className="text-sm text-slate-400">{te.sex(eleve.sexe)}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-5 py-4 font-mono text-sm text-slate-500">{eleve.numero_matricule}</td>
                      <td className="px-5 py-4 text-base text-slate-600">{eleve.classe_nom || 'ΓÇö'}</td>
                      <td className="px-5 py-4">
                        <Badge variant="neutral">{eleve.section ? te.section(eleve.section) : 'ΓÇö'}</Badge>
                      </td>
                      <td className="px-5 py-4">
                        <p className="text-base text-slate-700">{eleve.parent_nom || 'ΓÇö'}</p>
                        <p className="text-sm text-slate-400">{eleve.parent_telephone}</p>
                      </td>
                      <td className="px-5 py-4">
                        <Badge variant={statut.variant}>{statut.label}</Badge>
                      </td>
                      <td className="px-5 py-4 text-emerald-600 text-sm font-medium opacity-0 group-hover:opacity-100 transition-opacity">
                        {tc('viewProfile')}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </PageShell>
  )
}

function ElevesPageFallback() {
  const t = useTranslations('eleves')

  return (
    <PageShell title={t('list.title')} breadcrumb={t('list.breadcrumb')}>
      <div className="card p-16 text-center text-slate-400">{t('list.loadingFilters')}</div>
    </PageShell>
  )
}

export default function ElevesPage() {
  return (
    <Suspense fallback={<ElevesPageFallback />}>
      <ElevesPageContent />
    </Suspense>
  )
}

'use client'

import { Suspense, useState, useEffect, useCallback, useMemo } from 'react'
import { useParams } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { Plus, Trash2, Save, ChevronDown, Settings, X, Printer, Sprout } from 'lucide-react'
import SmartFilterBar from '@/components/filters/SmartFilterBar'
import StudentContextBanner from '@/components/students/StudentContextBanner'
import EmptyState from '@/components/ui/EmptyState'
import { useSmartFilters } from '@/hooks/useSmartFilters'
import { useStudentDeepLink } from '@/hooks/useStudentDeepLink'
import { useTranslatedEnums } from '@/hooks/useTranslatedEnums'

interface Eleve {
  id: string
  nom: string
  prenom: string
  numero_matricule: string
  classe_nom: string
}

interface Classe {
  id: string
  nom: string
}

interface Competence {
  eleve_id: string
  periode: string
  domaine: string
  competence: string
  statut: 'acquis' | 'en_cours' | 'non_acquis'
  observation: string
}

interface Domaine {
  nom: string
  competences: string[]
}

const PERIODE_VALUES = [
  'sequence1', 'sequence2', 'sequence3', 'sequence4', 'sequence5', 'sequence6',
] as const

const STATUT_VALUES = ['acquis', 'en_cours', 'non_acquis'] as const

const STATUT_STYLES: Record<string, { color: string; light: string }> = {
  acquis: { color: 'bg-emerald-500', light: 'bg-emerald-50 text-emerald-700 border-emerald-200' },
  en_cours: { color: 'bg-amber-500', light: 'bg-amber-50 text-amber-700 border-amber-200' },
  non_acquis: { color: 'bg-red-500', light: 'bg-red-50 text-red-700 border-red-200' },
}

export default function MaternellePage() {
  const tc = useTranslations('common')

  return (
    <Suspense fallback={<div className="p-12 text-center text-slate-400">{tc('loading')}</div>}>
      <MaternellePageContent />
    </Suspense>
  )
}

function MaternellePageContent() {
  const { slug } = useParams() as { slug: string }
  const t = useTranslations('maternelle')
  const tc = useTranslations('common')
  const tf = useTranslations('filters')
  const te = useTranslatedEnums()

  const [eleves, setEleves] = useState<Eleve[]>([])
  const [classes, setClasses] = useState<Classe[]>([])
  const [domaines, setDomaines] = useState<Domaine[]>([])
  const [competences, setCompetences] = useState<Competence[]>([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState<string | null>(null)

  const periodes = useMemo(
    () => PERIODE_VALUES.map(value => ({
      value,
      label: t(`sequences.${value}` as 'sequences.sequence1'),
    })),
    [t],
  )

  const statuts = useMemo(
    () => STATUT_VALUES.map(value => ({
      value,
      label: te.maternelleStatus(value),
      ...STATUT_STYLES[value],
    })),
    [te],
  )

  const filterFields = useMemo(() => [
    {
      key: 'classe',
      type: 'select' as const,
      label: tf('class.label'),
      options: [
        { value: '', label: t('allNurseryClasses') },
        ...classes.map(c => ({ value: c.id, label: c.nom })),
      ],
      defaultValue: '',
    },
    {
      key: 'eleve',
      type: 'select' as const,
      label: t('student'),
      options: [
        { value: '', label: t('allStudents') },
        ...eleves.map(e => ({ value: e.id, label: `${e.nom} ${e.prenom}` })),
      ],
      defaultValue: '',
    },
    {
      key: 'periode',
      type: 'pills' as const,
      label: t('sequence'),
      options: periodes.map(p => ({ value: p.value, label: p.label })),
      defaultValue: 'sequence1',
    },
  ], [classes, eleves, periodes, t, tf])

  const { values, setFilter, setFilters, reset, activeFilters } = useSmartFilters(filterFields)
  const { student } = useStudentDeepLink(setFilters, {
    apply: s => {
      const patch: Record<string, string> = { eleve: s.id }
      if (s.classe_id) patch.classe = s.classe_id
      return patch
    },
  })

  const classeId = values.classe ?? ''
  const eleveId = values.eleve ?? ''
  const periode = values.periode || 'sequence1'

  const [showSettings, setShowSettings] = useState(false)
  const [domainesEdit, setDomainesEdit] = useState<Domaine[]>([])
  const [savingDomaines, setSavingDomaines] = useState(false)
  const [newDomaine, setNewDomaine] = useState('')
  const [newCompetences, setNewCompetences] = useState<{ [key: number]: string }>({})
  const [domainesOpen, setDomainesOpen] = useState<{ [key: number]: boolean }>({})

  const handleClasseChange = (key: string, value: string) => {
    if (key === 'classe') {
      setFilter('classe', value)
      setFilter('eleve', '')
      return
    }
    setFilter(key, value)
  }

  const fetchData = useCallback(async () => {
    setLoading(true)
    const params = new URLSearchParams({ periode })
    if (classeId) params.set('classe_id', classeId)
    if (eleveId) params.set('eleve_id', eleveId)

    const res = await fetch(`/api/maternelle?${params}`)
    const data = await res.json()
    setEleves(data.eleves || [])
    setClasses(data.classes || [])
    setDomaines(data.domaines || [])
    setCompetences(data.competences || [])
    setLoading(false)
  }, [classeId, eleveId, periode])

  useEffect(() => { fetchData() }, [fetchData])

  const getStatut = (eleve_id: string, domaine: string, competence: string) => {
    return competences.find(
      c => c.eleve_id === eleve_id && c.domaine === domaine && c.competence === competence
    )?.statut || null
  }

  const handleStatut = async (eleve_id: string, domaine: string, competence: string, statut: string) => {
    const key = `${eleve_id}-${domaine}-${competence}`
    setSaving(key)
    await fetch('/api/maternelle', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ eleve_id, domaine, competence, statut, periode }),
    })
    await fetchData()
    setSaving(null)
  }

  const cycleStatut = (eleve_id: string, domaine: string, competence: string) => {
    const current = getStatut(eleve_id, domaine, competence)
    const order: (string | null)[] = [null, 'non_acquis', 'en_cours', 'acquis']
    const idx = order.indexOf(current)
    const next = order[(idx + 1) % order.length]
    if (next) handleStatut(eleve_id, domaine, competence, next)
    else handleStatut(eleve_id, domaine, competence, 'non_acquis')
  }

  const statutLabel = (statut: string | null) => {
    if (!statut) return t('notEvaluated')
    return statuts.find(s => s.value === statut)?.label ?? t('notEvaluated')
  }

  const StatutBadge = ({ eleve_id, domaine, competence }: { eleve_id: string; domaine: string; competence: string }) => {
    const statut = getStatut(eleve_id, domaine, competence)
    const key = `${eleve_id}-${domaine}-${competence}`
    const isSaving = saving === key
    const s = statuts.find(s => s.value === statut)

    return (
      <button
        onClick={() => cycleStatut(eleve_id, domaine, competence)}
        disabled={isSaving}
        className={`w-24 text-xs font-semibold px-2 py-1.5 rounded-lg border transition-all ${
          s ? s.light : 'bg-slate-50 text-slate-400 border-slate-200 hover:border-slate-300'
        } ${isSaving ? 'opacity-50' : 'hover:opacity-80'}`}
      >
        {isSaving ? '...' : statutLabel(statut)}
      </button>
    )
  }

  const getStats = (eleve_id: string) => {
    const cs = competences.filter(c => c.eleve_id === eleve_id)
    return {
      acquis: cs.filter(c => c.statut === 'acquis').length,
      en_cours: cs.filter(c => c.statut === 'en_cours').length,
      non_acquis: cs.filter(c => c.statut === 'non_acquis').length,
    }
  }

  const openSettings = () => {
    setDomainesEdit(JSON.parse(JSON.stringify(domaines)))
    setShowSettings(true)
  }

  const saveDomaines = async () => {
    setSavingDomaines(true)
    await fetch('/api/maternelle', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ domaines: domainesEdit }),
    })
    await fetchData()
    setSavingDomaines(false)
    setShowSettings(false)
  }

  const addDomaine = () => {
    if (!newDomaine.trim()) return
    setDomainesEdit(prev => [...prev, { nom: newDomaine.trim(), competences: [] }])
    setNewDomaine('')
  }

  const removeDomaine = (i: number) => {
    setDomainesEdit(prev => prev.filter((_, idx) => idx !== i))
  }

  const addCompetence = (domaineIdx: number) => {
    const val = newCompetences[domaineIdx]?.trim()
    if (!val) return
    setDomainesEdit(prev => {
      const copy = [...prev]
      copy[domaineIdx] = { ...copy[domaineIdx], competences: [...copy[domaineIdx].competences, val] }
      return copy
    })
    setNewCompetences(prev => ({ ...prev, [domaineIdx]: '' }))
  }

  const removeCompetence = (domaineIdx: number, compIdx: number) => {
    setDomainesEdit(prev => {
      const copy = [...prev]
      copy[domaineIdx] = {
        ...copy[domaineIdx],
        competences: copy[domaineIdx].competences.filter((_, i) => i !== compIdx)
      }
      return copy
    })
  }

  const elevesFiltres = eleveId
    ? eleves.filter(e => e.id === eleveId)
    : eleves

  const periodeLabel = periodes.find(p => p.value === periode)?.label || periode

  const statsLabels = [
    { key: 'acquis', color: 'text-emerald-600' },
    { key: 'en_cours', color: 'text-amber-600' },
    { key: 'non_acquis', color: 'text-red-600' },
  ] as const

  const handlePrint = () => {
    window.print()
  }

  return (
    <div className="p-8">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">{t('title')}</h1>
          <p className="text-slate-500 text-sm mt-1">{t('subtitle')}</p>
        </div>
        <div className="flex gap-2">
          {eleveId && (
            <button onClick={handlePrint}
              className="flex items-center gap-2 bg-emerald-500 hover:bg-emerald-600 text-white px-3 py-2 rounded-lg text-sm transition-colors print:hidden">
              <Printer className="w-4 h-4" /> {t('printBooklet')}
            </button>
          )}
          <button onClick={openSettings}
            className="flex items-center gap-2 border border-slate-200 hover:border-slate-300 text-slate-600 px-3 py-2 rounded-lg text-sm transition-colors print:hidden">
            <Settings className="w-4 h-4" /> {t('domains')}
          </button>
        </div>
      </div>

      <SmartFilterBar
        fields={filterFields}
        values={values}
        onChange={handleClasseChange}
        onReset={reset}
        activeFilters={activeFilters}
        resultCount={elevesFiltres.length}
        resultLabel={tf('resultLabel.students')}
        loading={loading}
        className="mb-6"
      />

      {student && (
        <StudentContextBanner slug={slug} student={student} className="mb-6" />
      )}

      {loading ? (
        <div className="p-12 text-center text-slate-400 text-sm">{tc('loading')}</div>
      ) : elevesFiltres.length === 0 ? (
        <EmptyState
          icon={Sprout}
          title={t('emptyTitle')}
          description={t('emptyDescription')}
        />
      ) : eleveId ? (
        <div className="space-y-4 print-area" id="livret-print">
          {(() => {
            const eleve = elevesFiltres[0]
            const stats = getStats(eleve.id)
            return (
              <>
                <div className="hidden print:block mb-6 border-b border-slate-300 pb-4">
                  <h1 className="text-xl font-bold">{t('printHeader')}</h1>
                  <p className="text-sm mt-1">{eleve.nom} {eleve.prenom} ┬╖ {eleve.classe_nom} ┬╖ {periodeLabel}</p>
                  <p className="text-xs text-slate-500 mt-1">
                    {t('matricule', { value: eleve.numero_matricule || 'ΓÇö' })}
                  </p>
                </div>
                <div className="bg-white rounded-xl border border-slate-200 p-4 flex items-center gap-6 print:border-0 print:p-0">
                  <div>
                    <p className="font-bold text-slate-800">{eleve.nom} {eleve.prenom}</p>
                    <p className="text-xs text-slate-400">{eleve.classe_nom}</p>
                  </div>
                  <div className="ml-auto flex gap-4">
                    {statsLabels.map(s => (
                      <div key={s.key} className="text-center">
                        <p className={`text-xl font-bold ${s.color}`}>{stats[s.key]}</p>
                        <p className="text-xs text-slate-500">{te.maternelleStatus(s.key)}</p>
                      </div>
                    ))}
                  </div>
                </div>

                {domaines.map((domaine, di) => (
                  <div key={di} className="bg-white rounded-xl border border-slate-200 overflow-hidden">
                    <div className="bg-slate-50 border-b border-slate-200 px-4 py-3">
                      <h2 className="font-semibold text-slate-700 text-sm">{domaine.nom}</h2>
                    </div>
                    <div className="divide-y divide-slate-50">
                      {domaine.competences.map((comp, ci) => (
                        <div key={ci} className="flex items-center justify-between px-4 py-3">
                          <p className="text-sm text-slate-700 flex-1 pr-4">{comp}</p>
                          <span className="print:hidden">
                            <StatutBadge eleve_id={eleve.id} domaine={domaine.nom} competence={comp} />
                          </span>
                          <span className="hidden print:inline text-xs font-semibold">
                            {statutLabel(getStatut(eleve.id, domaine.nom, comp))}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </>
            )
          })()}
        </div>
      ) : (
        <div className="space-y-8">
          {domaines.map((domaine, di) => (
            <div key={di} className="bg-white rounded-xl border border-slate-200 overflow-hidden">
              <div className="bg-slate-50 border-b border-slate-200 px-4 py-3">
                <h2 className="font-semibold text-slate-700">{domaine.nom}</h2>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="border-b border-slate-100">
                    <tr>
                      <th className="text-left px-4 py-2 text-xs font-semibold text-slate-500 w-48">{t('competence')}</th>
                      {elevesFiltres.map(e => (
                        <th key={e.id} className="text-center px-2 py-2 text-xs font-medium text-slate-600 min-w-28">
                          <button onClick={() => setFilter('eleve', e.id)} className="hover:text-emerald-600 transition-colors">
                            {e.nom} {e.prenom.charAt(0)}.
                          </button>
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {domaine.competences.map((comp, ci) => (
                      <tr key={ci} className="hover:bg-slate-50">
                        <td className="px-4 py-2 text-xs text-slate-600">{comp}</td>
                        {elevesFiltres.map(e => (
                          <td key={e.id} className="px-2 py-2 text-center">
                            <StatutBadge eleve_id={e.id} domaine={domaine.nom} competence={comp} />
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ))}
        </div>
      )}

      {showSettings && (
        <div className="fixed inset-0 bg-black/40 flex items-start justify-center z-50 p-4 overflow-y-auto">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl my-8">
            <div className="flex items-center justify-between p-6 border-b border-slate-200">
              <h2 className="font-bold text-slate-800">{t('settingsTitle')}</h2>
              <button onClick={() => setShowSettings(false)}>
                <X className="w-5 h-5 text-slate-400" />
              </button>
            </div>

            <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">
              {domainesEdit.map((domaine, di) => (
                <div key={di} className="border border-slate-200 rounded-xl overflow-hidden">
                  <div className="flex items-center justify-between bg-slate-50 px-4 py-3">
                    <button onClick={() => setDomainesOpen(p => ({ ...p, [di]: !p[di] }))}
                      className="flex items-center gap-2 text-sm font-semibold text-slate-700 flex-1 text-left">
                      <ChevronDown className={`w-4 h-4 text-slate-400 transition-transform ${domainesOpen[di] ? 'rotate-180' : ''}`} />
                      {domaine.nom}
                      <span className="text-xs font-normal text-slate-400">({domaine.competences.length})</span>
                    </button>
                    <button onClick={() => removeDomaine(di)}
                      className="text-slate-300 hover:text-red-500 transition-colors ml-2">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>

                  {domainesOpen[di] && (
                    <div className="p-4 space-y-2">
                      {domaine.competences.map((comp, ci) => (
                        <div key={ci} className="flex items-center gap-2 group">
                          <span className="text-sm text-slate-600 flex-1">{comp}</span>
                          <button onClick={() => removeCompetence(di, ci)}
                            className="text-slate-200 group-hover:text-red-400 transition-colors">
                            <X className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      ))}
                      <div className="flex gap-2 mt-3">
                        <input
                          value={newCompetences[di] || ''}
                          onChange={e => setNewCompetences(p => ({ ...p, [di]: e.target.value }))}
                          onKeyDown={e => e.key === 'Enter' && addCompetence(di)}
                          placeholder={t('newCompetencePlaceholder')}
                          className="flex-1 border border-slate-200 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400"
                        />
                        <button onClick={() => addCompetence(di)}
                          className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 py-1.5 rounded-lg text-sm transition-colors">
                          <Plus className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))}

              <div className="flex gap-2 pt-2">
                <input
                  value={newDomaine}
                  onChange={e => setNewDomaine(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && addDomaine()}
                  placeholder={t('newDomainPlaceholder')}
                  className="flex-1 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400"
                />
                <button onClick={addDomaine}
                  className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors">
                  <Plus className="w-4 h-4" /> {tc('add')}
                </button>
              </div>
            </div>

            <div className="flex gap-3 p-6 border-t border-slate-200">
              <button onClick={() => setShowSettings(false)}
                className="flex-1 border border-slate-200 text-slate-600 py-2.5 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors">
                {tc('cancel')}
              </button>
              <button onClick={saveDomaines} disabled={savingDomaines}
                className="flex-1 flex items-center justify-center gap-2 bg-emerald-500 hover:bg-emerald-600 text-white py-2.5 rounded-lg text-sm font-semibold transition-colors disabled:opacity-60">
                <Save className="w-4 h-4" />
                {savingDomaines ? tc('saving') : tc('save')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { Suspense, useState, useEffect, useMemo, useCallback, useRef } from 'react'
import { useParams } from 'next/navigation'
import Link from 'next/link'
import { useLocale, useTranslations } from 'next-intl'
import { Printer, FileText, Download, Users, AlertTriangle } from 'lucide-react'
import toast from 'react-hot-toast'
import PageShell from '@/components/layout/PageShell'
import EmptyState from '@/components/ui/EmptyState'
import DocumentHeaderPreview from '@/components/documents/DocumentHeaderPreview'
import SmartFilterBar from '@/components/filters/SmartFilterBar'
import StudentContextBanner from '@/components/students/StudentContextBanner'
import { useSmartFilters } from '@/hooks/useSmartFilters'
import { useStudentDeepLink } from '@/hooks/useStudentDeepLink'
import { studentLinks } from '@/lib/student-context-links'
import { useClasses } from '@/hooks/useClasses'
import { useTranslatedEnums } from '@/hooks/useTranslatedEnums'
import type { DocumentSection } from '@/lib/school-documents'

interface Classe { id: string; nom: string; section: string }

interface BulletinData {
  ecole: {
    nom: string; directeur_nom: string; adresse: string
    telephone?: string; email?: string; entete_url?: string | null
  }
  classe: { nom: string; section: string }
  periode: string
  noteMax: number
  anneeScolaire: string | null
  effectif: number
  bulletins: {
    eleve: {
      id: string
      nom: string; prenom: string; numero_matricule: string; sexe: string
      date_naissance?: string | null; lieu_naissance?: string | null
    }
    notes: { matiere: string; coefficient: number; note: number | null; appreciation: string | null }[]
    moyenne: number | null
    mention: string | null
    rang: number | null
    noteMax: number
  }[]
}

function formatDate(dateStr: string | null | undefined, locale: string): string {
  if (!dateStr) return 'ΓÇö'
  const d = new Date(dateStr)
  if (isNaN(d.getTime())) return dateStr
  return d.toLocaleDateString(locale, { day: '2-digit', month: '2-digit', year: 'numeric' })
}

function BulletinsPageFallback() {
  const t = useTranslations('notes')
  const tc = useTranslations('common')

  return (
    <PageShell title={t('bulletins.title')} breadcrumb={t('bulletins.breadcrumb')}>
      <div className="card p-16 text-center text-slate-400">{tc('loading')}</div>
    </PageShell>
  )
}

export default function BulletinsPage() {
  return (
    <Suspense fallback={<BulletinsPageFallback />}>
      <BulletinsPageContent />
    </Suspense>
  )
}

function BulletinsPageContent() {
  const { slug } = useParams() as { slug: string }
  const locale = useLocale()
  const t = useTranslations('notes')
  const tc = useTranslations('common')
  const tf = useTranslations('filters')
  const te = useTranslatedEnums()
  const { classes } = useClasses()
  const [section, setSection] = useState('francophone')
  const [data, setData] = useState<BulletinData | null>(null)
  const [loading, setLoading] = useState(false)
  const [selectedIdx, setSelectedIdx] = useState(0)
  const [examWarning, setExamWarning] = useState<{
    label: string
    reste: number
    statut: string
  } | null>(null)
  const targetEleveId = useRef<string | null>(null)

  const periodes = section === 'anglophone'
    ? ['S1', 'S2', 'S3', 'S4', 'S5', 'S6']
    : ['T1', 'T2', 'T3']

  const filterFields = useMemo(() => [
    {
      key: 'classe',
      type: 'select' as const,
      label: tf('labels.class'),
      options: [
        { value: '', label: t('bulletins.selectClassOption') },
        ...classes.map(c => ({ value: c.id, label: `${c.nom} (${te.section(c.section)})` })),
      ],
      defaultValue: '',
    },
    {
      key: 'periode',
      type: 'select' as const,
      label: tf('labels.period'),
      options: periodes.map(p => ({ value: p, label: p })),
      defaultValue: section === 'anglophone' ? 'S1' : 'T1',
    },
    {
      key: 'q',
      type: 'search' as const,
      placeholder: t('bulletins.searchPlaceholder'),
      debounce: true,
    },
    {
      key: 'mention',
      type: 'pills' as const,
      label: tf('labels.mention'),
      options: [
        { value: 'tous', label: t('bulletins.mentionFilters.all') },
        { value: 'TB', label: t('bulletins.mentionFilters.TB') },
        { value: 'B', label: t('bulletins.mentionFilters.B') },
        { value: 'AB', label: t('bulletins.mentionFilters.AB') },
        { value: 'P', label: t('bulletins.mentionFilters.P') },
        { value: 'I', label: t('bulletins.mentionFilters.I') },
      ],
      defaultValue: 'tous',
    },
  ], [classes, periodes, section, t, tf, te])

  const { values, debouncedValues, setFilter, setFilters, reset, activeFilters } = useSmartFilters(filterFields)
  const { student } = useStudentDeepLink(setFilters, {
    apply: s => {
      targetEleveId.current = s.id
      const patch: Record<string, string> = {
        q: s.numero_matricule || `${s.nom} ${s.prenom}`.trim(),
      }
      if (s.classe_id) patch.classe = s.classe_id
      return patch
    },
  })
  const classeId = values.classe
  const periode = values.periode || (section === 'anglophone' ? 'S1' : 'T1')

  useEffect(() => {
    if (!classeId) { setData(null); return }
    const c = classes.find(x => x.id === classeId)
    if (c) {
      setSection(c.section)
      if (!values.periode) {
        setFilter('periode', c.section === 'anglophone' ? 'S1' : 'T1')
      }
    }
  }, [classeId, classes])

  const loadBulletins = useCallback(async () => {
    if (!classeId || !periode) return
    setLoading(true)
    const res = await fetch(`/api/bulletins?classe_id=${classeId}&periode=${periode}`)
    const d = await res.json()
    if (!res.ok) {
      toast.error(d.error || tc('errorLoad'))
      setLoading(false)
      return
    }
    setData(d)
    if (!targetEleveId.current) setSelectedIdx(0)
    setLoading(false)
  }, [classeId, periode, tc])

  useEffect(() => { loadBulletins() }, [loadBulletins])

  const mentionMatch = (mention: string | null, filter: string) => {
    if (!filter || filter === 'tous' || !mention) return filter === 'tous'
    const map: Record<string, string[]> = {
      TB: ['Tr├¿s Bien', 'A'],
      B: ['Bien', 'B'],
      AB: ['Assez Bien', 'C'],
      P: ['Passable', 'D'],
      I: ['Insuffisant', 'F'],
    }
    return map[filter]?.some(m => mention.includes(m)) ?? true
  }

  const filteredBulletins = useMemo(() => {
    if (!data) return []
    let list = data.bulletins
    const q = debouncedValues.q?.toLowerCase().trim()
    if (q) {
      list = list.filter(b =>
        `${b.eleve.nom} ${b.eleve.prenom} ${b.eleve.numero_matricule}`.toLowerCase().includes(q)
      )
    }
    if (debouncedValues.mention && debouncedValues.mention !== 'tous') {
      list = list.filter(b => mentionMatch(b.mention, debouncedValues.mention))
    }
    return list
  }, [data, debouncedValues.q, debouncedValues.mention])

  useEffect(() => {
    if (selectedIdx >= filteredBulletins.length) setSelectedIdx(0)
  }, [filteredBulletins.length, selectedIdx])

  useEffect(() => {
    if (!targetEleveId.current || filteredBulletins.length === 0) return
    const idx = filteredBulletins.findIndex(b => b.eleve.id === targetEleveId.current)
    if (idx >= 0) {
      setSelectedIdx(idx)
      targetEleveId.current = null
    }
  }, [filteredBulletins])

  const bulletin = filteredBulletins[selectedIdx] ?? filteredBulletins[0]
  const isAng = data?.classe.section === 'anglophone'
  const docPrefix = isAng ? 'bulletins.docAng' : 'bulletins.docFr'
  const doc = (key: string, values?: Record<string, string | number>) =>
    t(`${docPrefix}.${key}` as 'bulletins.docFr.fullName', values)

  useEffect(() => {
    if (!bulletin?.eleve.id) {
      setExamWarning(null)
      return
    }
    fetch(`/api/frais-examens?eleve_id=${bulletin.eleve.id}`)
      .then(r => (r.ok ? r.json() : null))
      .then(d => {
        const s = d?.situation
        if (s?.config && (s.statut === 'impaye' || s.statut === 'partiel')) {
          setExamWarning({
            label: s.config.label,
            reste: s.reste,
            statut: s.statut,
          })
        } else {
          setExamWarning(null)
        }
      })
      .catch(() => setExamWarning(null))
  }, [bulletin?.eleve.id])

  const showExamWarningToast = () => {
    if (!examWarning) return
    toast(
      t('bulletins.toasts.examUnpaid', {
        label: examWarning.label,
        amount: Number(examWarning.reste).toLocaleString(locale),
      }),
      { icon: 'ΓÜá∩╕Å', duration: 6000 },
    )
  }

  const handlePrint = () => {
    if (!classeId || !periode || !bulletin?.eleve.id) return
    showExamWarningToast()
    const url = `/api/bulletins/print?classe_id=${classeId}&periode=${periode}&eleve_id=${bulletin.eleve.id}`
    const win = window.open(url, '_blank', 'width=800,height=1000')
    if (!win) toast.error(t('bulletins.toasts.popupBlocked'))
  }

  const handlePrintAll = async () => {
    if (!classeId || !periode) return
    const res = await fetch(`/api/frais-examens?classe_id=${classeId}`)
    const d = res.ok ? await res.json() : null
    if (d?.frais_examen && d.impayes > 0) {
      toast(
        t('bulletins.toasts.examUnpaidBulk', {
          count: d.impayes,
          label: d.frais_examen.label,
        }),
        { icon: 'ΓÜá∩╕Å', duration: 6000 },
      )
    }
    const url = `/api/bulletins/print?classe_id=${classeId}&periode=${periode}`
    const win = window.open(url, '_blank', 'width=800,height=1000')
    if (!win) toast.error(t('bulletins.toasts.popupBlocked'))
    else toast.success(t('bulletins.toasts.printAll', { count: data?.bulletins.length ?? 0 }))
  }

  return (
    <PageShell
      title={t('bulletins.title')}
      subtitle={t('bulletins.subtitle')}
      breadcrumb={t('bulletins.breadcrumb')}
      actions={
        data && data.bulletins.length > 0 ? (
          <div className="flex gap-2">
            <button onClick={handlePrint} className="btn-primary flex items-center gap-2 py-2.5">
              <Printer className="w-4 h-4" /> {t('bulletins.print')}
            </button>
            <button onClick={handlePrintAll}
              className="border border-slate-200 text-slate-700 font-semibold rounded-xl px-4 py-2.5 text-base hover:bg-white transition-colors flex items-center gap-2 bg-white">
              <Download className="w-4 h-4" /> {t('bulletins.printAll')}
            </button>
          </div>
        ) : undefined
      }
    >
      <SmartFilterBar
        fields={filterFields}
        values={values}
        onChange={setFilter}
        onReset={reset}
        activeFilters={activeFilters}
        resultCount={data ? filteredBulletins.length : undefined}
        resultLabel={t('bulletins.resultLabel')}
        loading={loading}
        className="mb-4"
      />

      {student && (
        <StudentContextBanner slug={slug} student={student} className="mb-6" />
      )}

      {examWarning && (
        <div className="flex items-start gap-3 px-4 py-3 mb-4 bg-amber-50 border border-amber-200 rounded-xl text-sm">
          <AlertTriangle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
          <div>
            <p className="font-semibold text-amber-900">{t('bulletins.examWarningTitle')}</p>
            <p className="text-amber-800 mt-0.5">
              {t('bulletins.examWarningBody', {
                label: examWarning.label,
                amount: Number(examWarning.reste).toLocaleString(locale),
              })}
            </p>
          </div>
        </div>
      )}

      {!classeId ? (
        <EmptyState
          icon={FileText}
          title={t('bulletins.emptySelectClass')}
          description={t('bulletins.emptySelectClassDesc')}
        />
      ) : loading ? (
        <div className="card p-16 text-center text-slate-400 text-base">{t('bulletins.generating')}</div>
      ) : !bulletin ? (
        <EmptyState
          icon={Users}
          title={t('bulletins.emptyNone')}
          description={t('bulletins.emptyNoneDesc')}
        />
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          <div className="lg:col-span-1 space-y-2 max-h-[600px] overflow-y-auto">
            {filteredBulletins.map((b, i) => (
              <div key={b.eleve.id} className={`rounded-xl border transition-all ${
                  selectedIdx === i
                    ? 'border-emerald-400 bg-emerald-50 shadow-sm'
                    : 'border-slate-200 bg-white hover:border-slate-300'
                }`}>
                <button type="button" onClick={() => setSelectedIdx(i)}
                  className="w-full text-left p-4">
                  <p className="font-semibold text-slate-800 text-base">{b.eleve.nom} {b.eleve.prenom}</p>
                  <p className="text-sm text-slate-500 mt-0.5">{b.eleve.numero_matricule}</p>
                  {b.moyenne !== null && (
                    <p className="text-sm font-bold text-emerald-600 mt-1">
                      {b.moyenne.toFixed(2)}/{b.noteMax} {b.mention && `┬╖ ${b.mention}`}
                    </p>
                  )}
                </button>
                <div className="px-4 pb-3">
                  <Link href={studentLinks(slug, {
                    id: b.eleve.id,
                    nom: b.eleve.nom,
                    prenom: b.eleve.prenom,
                    numero_matricule: b.eleve.numero_matricule,
                  }).fiche}
                    className="text-xs text-emerald-600 hover:underline font-medium">
                    {t('bulletins.viewProfile')}
                  </Link>
                </div>
              </div>
            ))}
          </div>

          <div className="lg:col-span-3">
            <div className="card p-8 print-area">
              <DocumentHeaderPreview
                ecole={data!.ecole}
                section={data!.classe.section as DocumentSection}
                periode={periode}
                anneeScolaire={data!.anneeScolaire}
                kind="bulletin"
              />

              <div className="grid grid-cols-2 gap-3 mb-6 text-sm">
                <div><span className="text-slate-500">{doc('fullName')} : </span><strong>{bulletin.eleve.nom} {bulletin.eleve.prenom}</strong></div>
                <div><span className="text-slate-500">{doc('matricule')} : </span>{bulletin.eleve.numero_matricule}</div>
                <div><span className="text-slate-500">{doc('birth')} : </span>{formatDate(bulletin.eleve.date_naissance, locale)} {doc('birthAt')} {bulletin.eleve.lieu_naissance || 'ΓÇö'}</div>
                <div><span className="text-slate-500">{doc('sex')} : </span>{bulletin.eleve.sexe === 'M' ? doc('sexMale') : doc('sexFemale')}</div>
                <div><span className="text-slate-500">{doc('class')} : </span><strong>{data!.classe.nom}</strong></div>
                <div><span className="text-slate-500">{doc('classSize')} : </span>{data!.effectif} {doc('students')}</div>
              </div>

              <table className="w-full border-collapse">
                <thead>
                  <tr className="bg-slate-50">
                    <th className="text-left p-2.5 border border-slate-200 text-xs uppercase">{doc('subject')}</th>
                    <th className="text-center p-2.5 border border-slate-200 text-xs uppercase w-16">{doc('coef')}</th>
                    <th className="text-center p-2.5 border border-slate-200 text-xs uppercase w-20">{doc('grade', { max: data!.noteMax })}</th>
                    <th className="text-left p-2.5 border border-slate-200 text-xs uppercase">{doc('appreciation')}</th>
                    <th className="text-center p-2.5 border border-slate-200 text-xs uppercase w-14">{doc('sign')}</th>
                  </tr>
                </thead>
                <tbody>
                  {bulletin.notes.map((n, i) => (
                    <tr key={i}>
                      <td className="p-2.5 border border-slate-200 text-sm font-medium">{n.matiere}</td>
                      <td className="p-2.5 border border-slate-200 text-sm text-center">{n.coefficient}</td>
                      <td className="p-2.5 border border-slate-200 text-sm text-center font-semibold">
                        {n.note !== null ? n.note.toFixed(2) : 'ΓÇö'}
                      </td>
                      <td className="p-2.5 border border-slate-200 text-sm text-slate-500 italic">
                        {n.appreciation || 'ΓÇö'}
                      </td>
                      <td className="p-2.5 border border-slate-200"></td>
                    </tr>
                  ))}
                </tbody>
              </table>

              <div className="flex justify-around my-6 p-5 bg-slate-50 rounded-xl border border-slate-200">
                <div className="text-center">
                  <p className="text-2xl font-bold text-emerald-600">
                    {bulletin.moyenne !== null ? bulletin.moyenne.toFixed(2) : 'ΓÇö'}
                  </p>
                  <p className="text-xs text-slate-500 mt-1">{doc('average', { max: data!.noteMax })}</p>
                </div>
                <div className="text-center">
                  <p className="text-2xl font-bold text-slate-800">
                    {bulletin.rang ? `${bulletin.rang} / ${data!.effectif}` : 'ΓÇö'}
                  </p>
                  <p className="text-xs text-slate-500 mt-1">{doc('rank')}</p>
                </div>
                <div className="text-center">
                  <p className="text-xl font-bold text-blue-600">{bulletin.mention ?? 'ΓÇö'}</p>
                  <p className="text-xs text-slate-500 mt-1">{doc('gradeLabel')}</p>
                </div>
              </div>

              <div className="text-sm mb-6 space-y-3">
                <div>
                  <strong>{doc('conduct')} :</strong>
                  <div className="border-b border-dotted border-slate-300 mt-1 min-h-[20px]"></div>
                </div>
                <div>
                  <strong>{doc('councilObs')} :</strong>
                  <div className="border-b border-dotted border-slate-300 mt-1 min-h-[20px]"></div>
                </div>
              </div>

              <div className="flex justify-between mt-10 gap-4">
                <div className="border-t border-slate-300 pt-2 w-[30%] text-center text-xs text-slate-500">
                  {doc('parent')}
                </div>
                <div className="border-t border-slate-300 pt-2 w-[30%] text-center text-xs text-slate-500">
                  {doc('teacher')}
                </div>
                <div className="border-t border-slate-300 pt-2 w-[30%] text-center text-xs text-slate-500">
                  {data!.ecole.directeur_nom || doc('director')}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </PageShell>
  )
}

'use client'

import { Suspense, useState, useEffect, useMemo } from 'react'
import Link from 'next/link'
import { useParams } from 'next/navigation'
import { useTranslations } from 'next-intl'
import { Save, Plus, X, ClipboardList } from 'lucide-react'
import toast from 'react-hot-toast'
import PageShell from '@/components/layout/PageShell'
import EmptyState from '@/components/ui/EmptyState'
import SmartFilterBar from '@/components/filters/SmartFilterBar'
import StudentContextBanner from '@/components/students/StudentContextBanner'
import { useSmartFilters } from '@/hooks/useSmartFilters'
import { useStudentDeepLink } from '@/hooks/useStudentDeepLink'
import { useClasses } from '@/hooks/useClasses'
import { studentLinks } from '@/lib/student-context-links'
import { getNoteMax, getMention } from '@/lib/notes-utils'

interface Matiere { id: string; nom: string; coefficient: number }
interface Eleve { id: string; nom: string; prenom: string; numero_matricule: string }
interface Note { eleve_id: string; note: number; appreciation: string }

function SaisieNotesPageFallback() {
  const t = useTranslations('notes')
  const tc = useTranslations('common')

  return (
    <PageShell title={t('entry.title')} breadcrumb={t('entry.breadcrumb')}>
      <div className="card p-12 text-center text-slate-400">{tc('loading')}</div>
    </PageShell>
  )
}

export default function SaisieNotesPage() {
  return (
    <Suspense fallback={<SaisieNotesPageFallback />}>
      <SaisieNotesPageContent />
    </Suspense>
  )
}

function SaisieNotesPageContent() {
  const { slug } = useParams() as { slug: string }
  const t = useTranslations('notes')
  const tc = useTranslations('common')
  const tf = useTranslations('filters')
  const { classes } = useClasses()
  const [matieres, setMatieres] = useState<Matiere[]>([])
  const [eleves, setEleves] = useState<Eleve[]>([])
  const [notes, setNotes] = useState<Record<string, string>>({})
  const [section, setSection] = useState('')
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)
  const [showMatForm, setShowMatForm] = useState(false)
  const [newMat, setNewMat] = useState({ nom: '', coefficient: '1' })

  const periodes = section === 'anglophone'
    ? ['S1', 'S2', 'S3', 'S4', 'S5', 'S6']
    : ['T1', 'T2', 'T3']

  const matiereOptions = useMemo(() => [
    { value: '', label: t('entry.selectSubjectOption') },
    ...matieres.map(m => ({
      value: m.id,
      label: t('entry.subjectWithCoef', { name: m.nom, coef: m.coefficient }),
    })),
  ], [matieres, t])

  const filterFields = useMemo(() => [
    {
      key: 'classe',
      type: 'select' as const,
      label: tf('labels.class'),
      options: [{ value: '', label: t('entry.selectClassOption') }, ...classes.map(c => ({ value: c.id, label: c.nom }))],
      defaultValue: '',
    },
    {
      key: 'matiere',
      type: 'select' as const,
      label: tf('labels.subject'),
      options: matiereOptions,
      defaultValue: '',
    },
    {
      key: 'periode',
      type: 'select' as const,
      label: tf('labels.period'),
      options: periodes.map(p => ({ value: p, label: p })),
      defaultValue: section === 'anglophone' ? 'S1' : 'T1',
    },
    {
      key: 'q',
      type: 'search' as const,
      placeholder: t('entry.filterStudent'),
      debounce: true,
    },
  ], [classes, matiereOptions, periodes, section, t, tf])

  const { values, debouncedValues, setFilter, setFilters, reset, activeFilters } = useSmartFilters(filterFields)
  const { student } = useStudentDeepLink(setFilters)
  const classeId = values.classe
  const matiereId = values.matiere
  const periode = values.periode || (section === 'anglophone' ? 'S1' : 'T1')

  useEffect(() => {
    if (!classeId) {
      setMatieres([])
      setEleves([])
      setNotes({})
      return
    }
    const classe = classes.find(c => c.id === classeId)
    setSection(classe?.section || '')
    fetch(`/api/notes?classe_id=${classeId}`)
      .then(r => r.json())
      .then(d => {
        setMatieres(d.matieres || [])
        setEleves(d.eleves || [])
        if (d.section) setSection(d.section)
      })
    setFilter('matiere', '')
    setNotes({})
  }, [classeId, classes])

  useEffect(() => {
    if (!classeId || !matiereId || !periode) return
    fetch(`/api/notes?classe_id=${classeId}&matiere_id=${matiereId}&periode=${periode}`)
      .then(r => r.json())
      .then(d => {
        const map: Record<string, string> = {}
        d.notes?.forEach((n: Note) => { map[n.eleve_id] = String(n.note) })
        setNotes(map)
      })
  }, [classeId, matiereId, periode])

  const filteredEleves = useMemo(() => {
    const q = debouncedValues.q?.toLowerCase().trim()
    if (!q) return eleves
    return eleves.filter(e =>
      `${e.nom} ${e.prenom} ${e.numero_matricule}`.toLowerCase().includes(q)
    )
  }, [eleves, debouncedValues.q])

  const noteMax = getNoteMax(section)

  const handleSave = async () => {
    setSaving(true)
    const promises = Object.entries(notes).map(([eleve_id, note]) =>
      fetch('/api/notes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ eleve_id, matiere_id: matiereId, periode, note: parseFloat(note), ecole_id: '' }),
      })
    )
    await Promise.all(promises)
    setSaving(false)
    setSaved(true)
    toast.success(t('entry.toasts.saved'))
    setTimeout(() => setSaved(false), 2000)
  }

  const handleAddMatiere = async () => {
    if (!newMat.nom || !classeId) return
    const classe = classes.find(c => c.id === classeId)
    await fetch('/api/matieres', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...newMat, classe_id: classeId, section: classe?.section }),
    })
    const d = await fetch(`/api/notes?classe_id=${classeId}`).then(r => r.json())
    setMatieres(d.matieres || [])
    setNewMat({ nom: '', coefficient: '1' })
    setShowMatForm(false)
  }

  const getMentionLabel = (note: number) => getMention(note, section)

  return (
    <PageShell
      title={t('entry.title')}
      subtitle={section === 'anglophone' ? t('entry.subtitleAnglophone') : t('entry.subtitleFrancophone')}
      breadcrumb={t('entry.breadcrumb')}
    >
      <SmartFilterBar
        fields={filterFields}
        values={values}
        onChange={setFilter}
        onReset={reset}
        activeFilters={activeFilters}
        resultCount={matiereId ? filteredEleves.length : undefined}
        resultLabel={t('entry.resultLabel')}
        extra={
          <div className="flex gap-2">
            {classeId && (
              <button onClick={() => setShowMatForm(true)}
                className="text-xs font-semibold px-3 py-1.5 rounded-full border border-slate-200 text-slate-600 hover:bg-slate-50">
                <Plus className="w-3.5 h-3.5 inline mr-1" /> {t('entry.addSubject')}
              </button>
            )}
            {matiereId && (
              <button onClick={handleSave} disabled={saving}
                className="flex items-center gap-1.5 bg-emerald-500 hover:bg-emerald-600 disabled:bg-slate-200 text-white text-xs font-semibold px-3 py-1.5 rounded-full">
                <Save className="w-3.5 h-3.5" />
                {saving ? tc('saving') : saved ? tc('saved') : tc('save')}
              </button>
            )}
          </div>
        }
        className="mb-4"
      />

      {student && <StudentContextBanner slug={slug} student={student} className="mb-6" />}

      {showMatForm && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-slate-800">{t('entry.newSubjectTitle')}</h3>
              <button onClick={() => setShowMatForm(false)}><X className="w-5 h-5 text-slate-400" /></button>
            </div>
            <div className="space-y-3">
              <input value={newMat.nom} onChange={e => setNewMat(p => ({ ...p, nom: e.target.value }))}
                placeholder={t('entry.subjectNamePlaceholder')}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
              <input type="number" value={newMat.coefficient}
                onChange={e => setNewMat(p => ({ ...p, coefficient: e.target.value }))}
                placeholder={t('entry.coefficientPlaceholder')}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
              <button onClick={handleAddMatiere}
                className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-semibold rounded-lg px-4 py-2.5 text-sm">
                {tc('add')}
              </button>
            </div>
          </div>
        </div>
      )}

      {!classeId ? (
        <div className="card p-12 text-center text-slate-400 text-sm">{t('entry.selectClass')}</div>
      ) : !matiereId ? (
        <div className="card p-12 text-center text-slate-400 text-sm">{t('entry.selectSubject')}</div>
      ) : filteredEleves.length === 0 ? (
        <EmptyState
          icon={ClipboardList}
          title={t('entry.emptyTitle')}
          description={t('entry.emptyDescription')}
        />
      ) : (
        <div className="card overflow-hidden">
          <table className="w-full">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">#</th>
                <th className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">{t('entry.columns.student')}</th>
                <th className="text-left px-4 py-3 text-sm font-semibold text-slate-500 uppercase tracking-wide w-32">{t('entry.columns.grade', { max: noteMax || 20 })}</th>
                <th className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">{t('entry.columns.mention')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredEleves.map((eleve, i) => {
                const noteVal = parseFloat(notes[eleve.id] || '')
                const mention = !isNaN(noteVal) ? getMentionLabel(noteVal) : null
                return (
                  <tr key={eleve.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-4 py-3 text-sm text-slate-400">{i + 1}</td>
                    <td className="px-4 py-3">
                      <Link href={studentLinks(slug, { id: eleve.id, nom: eleve.nom, prenom: eleve.prenom, numero_matricule: eleve.numero_matricule }).fiche}
                        className="group block">
                        <p className="font-medium text-slate-800 text-sm group-hover:text-emerald-700">{eleve.nom} {eleve.prenom}</p>
                        <p className="text-xs text-slate-400">{eleve.numero_matricule}</p>
                      </Link>
                    </td>
                    <td className="px-4 py-3">
                      <input
                        type="number" min="0" max={noteMax || 20} step="0.25"
                        value={notes[eleve.id] || ''}
                        onChange={e => setNotes(prev => ({ ...prev, [eleve.id]: e.target.value }))}
                        placeholder="ΓÇö"
                        className="w-24 border border-slate-200 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400 text-center"
                      />
                    </td>
                    <td className="px-4 py-3">
                      {mention && <span className={`text-xs font-semibold ${mention.color}`}>{mention.label}</span>}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      )}
    </PageShell>
  )
}

'use client'

import { Suspense, useState, useEffect, useRef, useMemo } from 'react'
import { useParams, useRouter, useSearchParams } from 'next/navigation'
import { Check, Search } from 'lucide-react'
import { useTranslations } from 'next-intl'
import RecuPrint from '@/components/paiements/RecuPrint'
import PageShell from '@/components/layout/PageShell'
import { usePaymentMethodOptions } from '@/hooks/useTranslatedEnums'
import type { EleveSituation } from '@/lib/paiements-utils'

interface FraisExamenSituation {
  config: { id: string; label: string; montant: number; date_limite: string | null } | null
  montant_attendu: number
  montant_paye: number
  reste: number
  statut: string
  date_limite: string | null
  jours_restants: number | null
  en_retard: boolean
}

interface Eleve {
  id: string
  nom: string
  prenom: string
  numero_matricule: string
  classe_nom: string
  total_paye: number
  total_attendu: number
}

function NouveauPaiementFallback() {
  const t = useTranslations('paiements')
  const tc = useTranslations('common')

  return (
    <PageShell title={t('new.title')} breadcrumb={t('new.breadcrumb')}>
      <div className="card p-12 text-center text-slate-400">{tc('loading')}</div>
    </PageShell>
  )
}

export default function NouveauPaiementPage() {
  return (
    <Suspense fallback={<NouveauPaiementFallback />}>
      <NouveauPaiementContent />
    </Suspense>
  )
}

function NouveauPaiementContent() {
  const { slug } = useParams()
  const router = useRouter()
  const searchParams = useSearchParams()
  const t = useTranslations('paiements')
  const tc = useTranslations('common')
  const paymentMethodOptions = usePaymentMethodOptions()

  const prefillDone = useRef(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [search, setSearch] = useState('')
  const [eleves, setEleves] = useState<Eleve[]>([])
  const [eleveSelectionne, setEleveSelectionne] = useState<Eleve | null>(null)
  const [situation, setSituation] = useState<EleveSituation | null>(null)
  const [fraisExamen, setFraisExamen] = useState<FraisExamenSituation | null>(null)
  const isFraisExamen = searchParams.get('type') === 'frais_examen'
  const [recu, setRecu] = useState<{ id: string; recu_numero?: string } | null>(null)

  const [form, setForm] = useState({
    eleve_id: '',
    tranche_numero: '1',
    frais_annexe_id: '',
    montant: '',
    mode_paiement: 'especes',
    date_paiement: new Date().toISOString().split('T')[0],
  })

  const paymentMethods = useMemo(
    () => paymentMethodOptions.filter(o => o.value !== ''),
    [paymentMethodOptions]
  )

  const up = (field: string, value: string) =>
    setForm(prev => ({ ...prev, [field]: value }))

  useEffect(() => {
    if (search.length < 2) { setEleves([]); return }
    const timer = setTimeout(async () => {
      const res = await fetch(`/api/eleves?search=${search}`)
      const data = await res.json()
      setEleves(data.eleves || [])
    }, 300)
    return () => clearTimeout(timer)
  }, [search])

  useEffect(() => {
    if (!eleveSelectionne) {
      setSituation(null)
      setFraisExamen(null)
      return
    }
    if (isFraisExamen) {
      fetch(`/api/frais-examens?eleve_id=${eleveSelectionne.id}`)
        .then(r => r.json())
        .then(data => {
          const s = data.situation as FraisExamenSituation | null
          setFraisExamen(s)
          setSituation(null)
          if (s?.config && s.reste > 0) {
            setForm(prev => ({
              ...prev,
              frais_annexe_id: s.config!.id,
              montant: String(s.reste),
            }))
          }
        })
      return
    }
    fetch(`/api/paiements?view=situation&eleve_id=${eleveSelectionne.id}`)
      .then(r => r.json())
      .then(data => {
        const s = data.situation as EleveSituation | null
        setSituation(s)
        setFraisExamen(null)
        if (s?.tranches.length) {
          const firstDue = s.tranches.find(t => t.reste > 0) ?? s.tranches[0]
          setForm(prev => ({
            ...prev,
            tranche_numero: String(firstDue.tranche_numero),
            montant: firstDue.reste > 0 ? String(firstDue.reste) : '',
          }))
        }
      })
  }, [eleveSelectionne, isFraisExamen])

  const selectEleve = (eleve: Eleve) => {
    setEleveSelectionne(eleve)
    setForm(prev => ({ ...prev, eleve_id: eleve.id, tranche_numero: '1', frais_annexe_id: '', montant: '' }))
    setSearch('')
    setEleves([])
  }

  useEffect(() => {
    const eleveId = searchParams.get('eleve_id')
    if (!eleveId || prefillDone.current) return
    prefillDone.current = true
    fetch(`/api/eleves/${eleveId}`)
      .then(r => (r.ok ? r.json() : null))
      .then(data => {
        if (!data?.eleve) return
        const e = data.eleve
        selectEleve({
          id: e.id,
          nom: e.nom,
          prenom: e.prenom,
          numero_matricule: e.numero_matricule,
          classe_nom: e.classe_nom || '',
          total_paye: 0,
          total_attendu: 0,
        })
      })
  }, [searchParams])

  const trancheActive = situation?.tranches.find(
    tr => tr.tranche_numero === Number(form.tranche_numero),
  )

  const handleTrancheChange = (numero: string) => {
    up('tranche_numero', numero)
    const tr = situation?.tranches.find(t => t.tranche_numero === Number(numero))
    if (tr && tr.reste > 0) up('montant', String(tr.reste))
  }

  const handleSubmit = async () => {
    if (!form.eleve_id || !form.montant) {
      setError(t('new.errors.selectStudent'))
      return
    }
    if (isFraisExamen && !form.frais_annexe_id) {
      setError(t('new.errors.noExamFees'))
      return
    }
    setLoading(true)
    setError('')

    const payload = isFraisExamen
      ? {
          eleve_id: form.eleve_id,
          frais_annexe_id: form.frais_annexe_id,
          montant: form.montant,
          mode_paiement: form.mode_paiement,
          date_paiement: form.date_paiement,
        }
      : form

    const res = await fetch('/api/paiements', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })
    const data = await res.json()

    if (!res.ok) {
      setError(data.error || t('new.errors.saveFailed'))
      setLoading(false)
      return
    }

    setRecu(data.recu)
    setLoading(false)
  }

  const totalAttendu = isFraisExamen
    ? (fraisExamen?.montant_attendu ?? 0)
    : (situation?.total_attendu ?? eleveSelectionne?.total_attendu ?? 0)
  const totalPaye = isFraisExamen
    ? (fraisExamen?.montant_paye ?? 0)
    : (situation?.total_paye ?? eleveSelectionne?.total_paye ?? 0)
  const reste = isFraisExamen
    ? (fraisExamen?.reste ?? 0)
    : (situation?.total_reste ?? (totalAttendu - totalPaye))

  return (
    <PageShell
      title={isFraisExamen ? t('new.titleExam') : t('new.title')}
      breadcrumb={isFraisExamen ? t('new.breadcrumbExam') : t('new.breadcrumb')}
      subtitle={isFraisExamen ? t('new.subtitleExam') : t('new.subtitle')}
    >
      <div className="max-w-2xl">
      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-lg px-4 py-3 mb-6 text-base">
          {error}
        </div>
      )}

      <div className="card p-6 space-y-5">
        <div>
          <label className="block text-base font-medium text-slate-700 mb-1">{t('new.studentLabel')}</label>
          {eleveSelectionne ? (
            <div className="flex items-center justify-between p-3 bg-emerald-50 border border-emerald-200 rounded-lg">
              <div>
                <p className="font-semibold text-slate-800 text-base">
                  {eleveSelectionne.nom} {eleveSelectionne.prenom}
                </p>
                <p className="text-sm text-slate-500">
                  {eleveSelectionne.numero_matricule} ΓÇö {eleveSelectionne.classe_nom}
                </p>
              </div>
              <button onClick={() => { setEleveSelectionne(null); setSituation(null); setForm(p => ({ ...p, eleve_id: '' })) }}
                className="text-sm text-slate-400 hover:text-slate-600">
                {tc('change')}
              </button>
            </div>
          ) : (
            <div className="relative">
              <div className="flex items-center gap-2 border border-slate-200 rounded-lg px-3 py-2.5">
                <Search className="w-5 h-5 text-slate-400 shrink-0" />
                <input
                  type="text"
                  placeholder={t('new.searchPlaceholder')}
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="flex-1 text-base focus:outline-none"
                />
              </div>
              {eleves.length > 0 && (
                <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 rounded-lg shadow-lg mt-1 z-10 max-h-48 overflow-y-auto">
                  {eleves.map(eleve => (
                    <button key={eleve.id} onClick={() => selectEleve(eleve)}
                      className="w-full text-left px-4 py-3 hover:bg-slate-50 border-b border-slate-100 last:border-0">
                      <p className="font-medium text-slate-800 text-base">
                        {eleve.nom} {eleve.prenom}
                      </p>
                      <p className="text-sm text-slate-400">
                        {eleve.numero_matricule} ΓÇö {eleve.classe_nom || t('new.noClass')}
                      </p>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {eleveSelectionne && (
          <>
            <div className="grid grid-cols-3 gap-3 p-4 bg-slate-50 rounded-lg text-center">
              <div>
                <p className="text-sm text-slate-500 mb-1">{t('new.totalExpected')}</p>
                <p className="font-bold text-slate-800 text-base">
                  {Number(totalAttendu).toLocaleString('fr-FR')} {tc('currency')}
                </p>
              </div>
              <div>
                <p className="text-sm text-slate-500 mb-1">{t('new.alreadyPaid')}</p>
                <p className="font-bold text-emerald-600 text-base">
                  {Number(totalPaye).toLocaleString('fr-FR')} {tc('currency')}
                </p>
              </div>
              <div>
                <p className="text-sm text-slate-500 mb-1">{t('new.remainingDue')}</p>
                <p className={`font-bold text-base ${reste > 0 ? 'text-red-600' : 'text-emerald-600'}`}>
                  {Number(reste).toLocaleString('fr-FR')} {tc('currency')}
                </p>
              </div>
            </div>

            {isFraisExamen && fraisExamen?.config ? (
              <div className="p-4 bg-violet-50 border border-violet-200 rounded-xl">
                <p className="text-sm font-semibold text-violet-800">{fraisExamen.config.label}</p>
                {fraisExamen.date_limite && (
                  <p className={`text-xs mt-1 ${fraisExamen.en_retard ? 'text-red-600' : 'text-slate-500'}`}>
                    {t('new.dueDate', { date: new Date(fraisExamen.date_limite).toLocaleDateString('fr-FR') })}
                    {fraisExamen.en_retard && ` ${t('new.dueDateOverdue')}`}
                  </p>
                )}
              </div>
            ) : situation && situation.tranches.length > 0 ? (
              <div className="space-y-2">
                <p className="text-sm font-medium text-slate-600">{t('new.installmentDetail')}</p>
                <div className="grid gap-2">
                  {situation.tranches.map(tr => (
                    <div
                      key={tr.tranche_numero}
                      className={`flex items-center justify-between px-4 py-3 rounded-xl border text-sm ${
                        Number(form.tranche_numero) === tr.tranche_numero
                          ? 'border-emerald-400 bg-emerald-50'
                          : 'border-slate-200 bg-white'
                      }`}
                    >
                      <span className="font-semibold text-slate-700">{t('new.installment', { num: tr.tranche_numero })}</span>
                      <span className="text-slate-500">
                        {Number(tr.montant_paye).toLocaleString('fr-FR')} / {Number(tr.montant_attendu).toLocaleString('fr-FR')} {tc('currency')}
                      </span>
                      <span className={tr.reste > 0 ? 'text-red-600 font-semibold' : 'text-emerald-600 font-semibold'}>
                        {tr.reste > 0 ? t('new.remaining', { amount: Number(tr.reste).toLocaleString('fr-FR') }) : t('new.paid')}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            ) : null}
          </>
        )}

        {!isFraisExamen && (
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-base font-medium text-slate-700 mb-1">{t('new.installmentLabel')}</label>
            <select
              value={form.tranche_numero}
              onChange={e => handleTrancheChange(e.target.value)}
              className="input-field"
              disabled={!eleveSelectionne}
            >
              {(situation?.tranches.length ? situation.tranches : [{ tranche_numero: 1 }, { tranche_numero: 2 }, { tranche_numero: 3 }]).map(tr => (
                <option key={tr.tranche_numero} value={tr.tranche_numero}>
                  {t('new.installment', { num: tr.tranche_numero })}
                  {'montant_attendu' in tr && tr.montant_attendu
                    ? ` ΓÇö ${Number(tr.montant_attendu).toLocaleString('fr-FR')} ${tc('currency')}`
                    : ''}
                </option>
              ))}
            </select>
            {trancheActive && (
              <p className="text-xs text-slate-500 mt-1">
                {t('new.remainingOnInstallment', { amount: Number(trancheActive.reste).toLocaleString('fr-FR') })}
              </p>
            )}
          </div>
          <div>
            <label className="block text-base font-medium text-slate-700 mb-1">{t('new.amountLabel')}</label>
            <input type="number" value={form.montant} onChange={e => up('montant', e.target.value)}
              placeholder="50000"
              className="input-field" />
          </div>
        </div>
        )}

        {isFraisExamen && (
          <div>
            <label className="block text-base font-medium text-slate-700 mb-1">{t('new.amountLabel')}</label>
            <input type="number" value={form.montant} onChange={e => up('montant', e.target.value)}
              placeholder="15000"
              className="input-field" />
            {fraisExamen && fraisExamen.reste > 0 && (
              <p className="text-xs text-slate-500 mt-1">
                {t('new.remainingToPay', { amount: Number(fraisExamen.reste).toLocaleString('fr-FR') })}
              </p>
            )}
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-base font-medium text-slate-700 mb-1">{t('new.paymentMethod')}</label>
            <select value={form.mode_paiement} onChange={e => up('mode_paiement', e.target.value)}
              className="input-field">
              {paymentMethods.map(o => (
                <option key={o.value} value={o.value}>{o.label}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-base font-medium text-slate-700 mb-1">{t('new.dateLabel')}</label>
            <input type="date" value={form.date_paiement} onChange={e => up('date_paiement', e.target.value)}
              className="input-field" />
          </div>
        </div>

        <button onClick={handleSubmit}
          disabled={loading || !form.eleve_id || !form.montant || (isFraisExamen && !form.frais_annexe_id)}
          className="w-full btn-primary flex items-center justify-center gap-2">
          {loading ? tc('saving') : <><Check className="w-5 h-5" /> {isFraisExamen ? t('new.submitExam') : t('new.submit')}</>}
        </button>
      </div>

      {recu && (
        <RecuPrint
          paiementId={recu.id}
          numero={recu.recu_numero}
          onClose={() => router.push(`/${slug}/paiements`)}
        />
      )}
      </div>
    </PageShell>
  )
}

'use client'

import { Suspense, useState, useEffect, useCallback, useMemo } from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import { Plus, TrendingUp, AlertCircle, Calendar, Clock, History, Users, Pencil, Printer, X, CreditCard } from 'lucide-react'
import { useTranslations } from 'next-intl'
import PageShell from '@/components/layout/PageShell'
import EmptyState from '@/components/ui/EmptyState'
import SituationParEleve from '@/components/paiements/SituationParEleve'
import RecuPrint from '@/components/paiements/RecuPrint'
import SmartFilterBar from '@/components/filters/SmartFilterBar'
import StudentContextBanner from '@/components/students/StudentContextBanner'
import { useSmartFilters } from '@/hooks/useSmartFilters'
import { useStudentDeepLink } from '@/hooks/useStudentDeepLink'
import { useClasses } from '@/hooks/useClasses'
import {
  useTranslatedEnums,
  useSituationStatutOptions,
  usePaymentMethodOptions,
  usePaymentFilters,
} from '@/hooks/useTranslatedEnums'
import { studentLinks } from '@/lib/student-context-links'
import type { EleveSituation } from '@/lib/paiements-utils'
import toast from 'react-hot-toast'

interface Paiement {
  id: string
  eleve_id: string
  recu_numero: string
  eleve_nom: string
  eleve_prenom: string
  numero_matricule: string
  classe_nom: string
  montant: number
  tranche_numero: number
  mode_paiement: string
  date_paiement: string
}

interface Retard {
  eleve_id: string
  nom: string
  prenom: string
  numero_matricule: string
  classe_nom: string
  tranche_numero: number
  montant_attendu: number
  montant_paye: number
  date_limite: string
  jours_retard: number
}

interface Stats {
  today: number
  mois: number
  impaye: number
  retards: number
  retardsCritiques: number
}

type Tab = 'situation' | 'historique'

function PaiementsPageContent() {
  const { slug } = useParams()
  const router = useRouter()
  const { classes } = useClasses()
  const t = useTranslations('paiements')
  const tc = useTranslations('common')
  const te = useTranslatedEnums()
  const situationStatutOptions = useSituationStatutOptions()
  const paymentMethodOptions = usePaymentMethodOptions()
  const paymentFilters = usePaymentFilters()

  const [paiements, setPaiements] = useState<Paiement[]>([])
  const [situations, setSituations] = useState<EleveSituation[]>([])
  const [retards, setRetards] = useState<Retard[]>([])
  const [stats, setStats] = useState<Stats>({ today: 0, mois: 0, impaye: 0, retards: 0, retardsCritiques: 0 })
  const [loading, setLoading] = useState(true)
  const [anneeScolaire, setAnneeScolaire] = useState('')

  const [editPaiement, setEditPaiement] = useState<Paiement | null>(null)
  const [editForm, setEditForm] = useState({
    montant: '', tranche_numero: '1',
    mode_paiement: 'especes', date_paiement: '',
  })
  const [savingEdit, setSavingEdit] = useState(false)
  const [recuAReimprimer, setRecuAReimprimer] = useState<{ id: string; recu_numero: string } | null>(null)

  const classeOptions = useMemo(() => [
    { value: '', label: t('list.allClasses') },
    ...classes.map(c => ({ value: c.id, label: c.nom })),
  ], [classes, t])

  const defaultMois = useMemo(() => new Date().toISOString().slice(0, 7), [])

  const filterFields = useMemo(() => [
    { key: 'tab', type: 'select' as const, defaultValue: 'situation' },
    { key: 'q', type: 'search' as const, placeholder: t('list.searchPlaceholder'), debounce: true },
    { key: 'classe', type: 'select' as const, label: t('list.filterLabels.class'), options: classeOptions, defaultValue: '' },
    { key: 'statut', type: 'select' as const, label: t('list.filterLabels.situation'), options: situationStatutOptions, defaultValue: 'tous' },
    { key: 'mois', type: 'month' as const, label: t('list.filterLabels.month'), defaultValue: defaultMois },
    { key: 'mode', type: 'select' as const, label: t('list.filterLabels.method'), options: paymentMethodOptions, defaultValue: '' },
  ], [classeOptions, defaultMois, situationStatutOptions, paymentMethodOptions, t])

  const filters = useSmartFilters(filterFields)
  const { student } = useStudentDeepLink(filters.setFilters)
  const tab = (filters.values.tab || 'situation') as Tab

  const activeFields = useMemo(() => {
    if (tab === 'situation') {
      return filterFields.filter(f => ['q', 'classe', 'statut'].includes(f.key))
    }
    return filterFields.filter(f => ['mois', 'q', 'classe', 'mode'].includes(f.key))
  }, [tab, filterFields])

  const visibleActiveFilters = useMemo(
    () => filters.activeFilters.filter(af => activeFields.some(f => f.key === af.key)),
    [filters.activeFilters, activeFields]
  )

  const overdueColumns = useMemo(() => [
    t('list.columns.student'),
    t('list.columns.class'),
    t('list.columns.installment'),
    t('list.columns.remainingDue'),
    t('list.columns.dueDate'),
    t('list.columns.delay'),
  ], [t])

  const historyColumns = useMemo(() => [
    t('list.columns.receipt'),
    t('list.columns.student'),
    t('list.columns.class'),
    t('list.columns.installment'),
    t('list.columns.amount'),
    t('list.columns.method'),
    t('list.columns.date'),
    t('list.columns.actions'),
  ], [t])

  const editPaymentMethods = useMemo(
    () => paymentMethodOptions.filter(o => o.value !== ''),
    [paymentMethodOptions]
  )

  const fetchHistorique = useCallback(async () => {
    const v = filters.debouncedValues
    const params = new URLSearchParams()
    params.set('mois', v.mois || defaultMois)
    if (v.q) params.set('search', v.q)
    if (v.classe) params.set('classe_id', v.classe)
    if (v.mode) params.set('mode', v.mode)
    const res = await fetch(`/api/paiements?${params}`)
    const data = await res.json()
    setPaiements(data.paiements || [])
    setStats(data.stats || { today: 0, mois: 0, impaye: 0, retards: 0, retardsCritiques: 0 })
    setRetards(data.retards || [])
  }, [filters.debouncedValues, defaultMois])

  const fetchSituation = useCallback(async () => {
    const v = filters.debouncedValues
    const params = new URLSearchParams({ view: 'situation' })
    if (v.q) params.set('search', v.q)
    if (v.classe) params.set('classe_id', v.classe)
    if (v.statut && v.statut !== 'tous') params.set('statut', v.statut)
    const res = await fetch(`/api/paiements?${params}`)
    const data = await res.json()
    setSituations(data.situations || [])
    setAnneeScolaire(data.annee_scolaire || '')
  }, [filters.debouncedValues])

  useEffect(() => {
    setLoading(true)
    Promise.all([fetchHistorique(), fetchSituation()]).finally(() => setLoading(false))
  }, [fetchHistorique, fetchSituation])

  const retardsCritiques = retards.filter(r => r.jours_retard >= 3)

  const openEdit = (p: Paiement) => {
    setEditPaiement(p)
    setEditForm({
      montant: String(p.montant),
      tranche_numero: String(p.tranche_numero),
      mode_paiement: p.mode_paiement,
      date_paiement: p.date_paiement,
    })
  }

  const handleEdit = async () => {
    if (!editPaiement) return
    if (!editForm.montant || Number(editForm.montant) <= 0) {
      toast.error(t('list.invalidAmount'))
      return
    }
    setSavingEdit(true)
    const res = await fetch('/api/paiements', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: editPaiement.id, ...editForm }),
    })
    setSavingEdit(false)
    if (!res.ok) { toast.error(t('list.toasts.editError')); return }
    toast.success(t('list.toasts.edited'))
    setEditPaiement(null)
    fetchHistorique()
    fetchSituation()
  }

  const imprimerRecu = (p: Paiement) => {
    setRecuAReimprimer({ id: p.id, recu_numero: p.recu_numero })
  }

  return (
    <PageShell
      title={t('list.title')}
      subtitle={t('list.subtitle')}
      breadcrumb={t('list.breadcrumb')}
      actions={
        <button onClick={() => router.push(`/${slug}/paiements/nouveau`)}
          className="btn-primary flex items-center gap-2 py-2.5">
          <Plus className="w-5 h-5" /> {t('list.newPayment')}
        </button>
      }
    >
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <div className="card p-6">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-10 h-10 bg-emerald-100 rounded-lg flex items-center justify-center">
              <Calendar className="w-5 h-5 text-emerald-600" />
            </div>
            <span className="text-base text-slate-500">{t('list.stats.today')}</span>
          </div>
          <p className="text-2xl font-bold text-slate-800">{Number(stats.today).toLocaleString('fr-FR')} {tc('currency')}</p>
        </div>
        <div className="card p-6">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
              <TrendingUp className="w-5 h-5 text-blue-600" />
            </div>
            <span className="text-base text-slate-500">{t('list.stats.thisMonth')}</span>
          </div>
          <p className="text-2xl font-bold text-slate-800">{Number(stats.mois).toLocaleString('fr-FR')} {tc('currency')}</p>
        </div>
        <div className="card p-6 cursor-pointer hover:border-red-200 transition-colors"
          onClick={() => filters.setFilters({ tab: 'situation', statut: 'impaye' })}>
          <div className="flex items-center gap-3 mb-3">
            <div className="w-10 h-10 bg-red-100 rounded-lg flex items-center justify-center">
              <AlertCircle className="w-5 h-5 text-red-600" />
            </div>
            <span className="text-base text-slate-500">{t('list.stats.unpaid')}</span>
          </div>
          <p className="text-2xl font-bold text-slate-800">{t('list.stats.studentsCount', { count: stats.impaye })}</p>
        </div>
        <div className="card p-6">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-10 h-10 bg-amber-100 rounded-lg flex items-center justify-center">
              <Clock className="w-5 h-5 text-amber-600" />
            </div>
            <span className="text-base text-slate-500">{t('list.stats.overdue')}</span>
          </div>
          <p className="text-2xl font-bold text-amber-600">{stats.retardsCritiques}</p>
        </div>
      </div>

      {retardsCritiques.length > 0 && (
        <div className="card mb-6 overflow-hidden border-amber-200">
          <div className="px-6 py-4 bg-amber-50 border-b border-amber-200 flex items-center gap-2">
            <Clock className="w-5 h-5 text-amber-600" />
            <h2 className="font-semibold text-amber-800 text-base">{t('list.overdueTitle', { count: retardsCritiques.length })}</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full min-w-[640px]">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  {overdueColumns.map((h, i) => (
                    <th key={h} className={`px-4 py-3 text-sm font-semibold text-slate-500 uppercase tracking-wide ${i === 3 ? 'text-right' : 'text-left'}`}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {retardsCritiques.map(r => (
                  <tr key={`${r.eleve_id}-${r.tranche_numero}`} className="hover:bg-amber-50/50">
                    <td className="px-4 py-3">
                      <Link href={studentLinks(slug as string, { id: r.eleve_id, nom: r.nom, prenom: r.prenom, numero_matricule: r.numero_matricule }).fiche}
                        className="block hover:text-emerald-700">
                        <p className="font-semibold text-slate-800 text-base">{r.nom} {r.prenom}</p>
                        <p className="text-sm text-slate-400">{r.numero_matricule}</p>
                      </Link>
                    </td>
                    <td className="px-4 py-3 text-base text-slate-600">{r.classe_nom}</td>
                    <td className="px-4 py-3">
                      <span className="text-sm font-medium px-2.5 py-1 rounded-full bg-amber-100 text-amber-700">{t('list.installment', { num: r.tranche_numero })}</span>
                    </td>
                    <td className="px-4 py-3 font-semibold text-red-600 text-base text-right tabular-nums whitespace-nowrap">
                      {(r.montant_attendu - r.montant_paye).toLocaleString('fr-FR')} {tc('currency')}
                    </td>
                    <td className="px-4 py-3 text-base text-slate-500">{r.date_limite}</td>
                    <td className="px-4 py-3">
                      <span className="text-sm font-bold px-2.5 py-1 rounded-full bg-red-100 text-red-700">{t('list.daysLate', { n: r.jours_retard })}</span>
                      <Link href={studentLinks(slug as string, { id: r.eleve_id, nom: r.nom, prenom: r.prenom, numero_matricule: r.numero_matricule }).encaisser}
                        className="block text-xs text-emerald-600 hover:underline font-medium mt-1">
                        {t('list.collectLink')}
                      </Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <div className="flex gap-1 mb-6 p-1 bg-slate-100 rounded-xl w-fit">
        <button type="button" onClick={() => filters.setFilter('tab', 'situation')}
          className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-semibold transition-all ${
            tab === 'situation' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}>
          <Users className="w-4 h-4" /> {t('list.tabs.situation')}
        </button>
        <button type="button" onClick={() => filters.setFilter('tab', 'historique')}
          className={`flex items-center gap-2 px-5 py-2.5 rounded-lg text-sm font-semibold transition-all ${
            tab === 'historique' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}>
          <History className="w-4 h-4" /> {t('list.tabs.history')}
        </button>
      </div>

      {student && (
        <StudentContextBanner slug={slug as string} student={student} className="mb-4" />
      )}

      <SmartFilterBar
        fields={activeFields}
        values={filters.values}
        onChange={filters.setFilter}
        onReset={filters.reset}
        activeFilters={visibleActiveFilters}
        presets={tab === 'situation' ? paymentFilters : undefined}
        onPreset={tab === 'situation' ? filters.applyPreset : undefined}
        resultCount={tab === 'situation' ? situations.length : paiements.length}
        resultLabel={tab === 'situation' ? t('list.resultSituation') : t('list.resultHistory')}
        loading={loading}
        extra={tab === 'situation' && anneeScolaire ? (
          <span className="text-sm text-slate-400 whitespace-nowrap">{t('list.year', { year: anneeScolaire })}</span>
        ) : undefined}
        className="mb-4"
      />

      {tab === 'situation' ? (
        <SituationParEleve slug={slug as string} situations={situations} loading={loading} />
      ) : (
        <div className="card overflow-hidden">
          {loading ? (
            <div className="p-12 text-center text-slate-400 text-base">{tc('loading')}</div>
          ) : paiements.length === 0 ? (
            <EmptyState
              icon={CreditCard}
              title={t('list.emptyTitle')}
              description={t('list.emptyDescription')}
              action={
                <Link href={`/${slug}/paiements/nouveau`} className="btn-primary inline-flex items-center gap-2">
                  <Plus className="w-4 h-4" /> {t('list.newPayment')}
                </Link>
              }
            />
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full min-w-[720px]">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>
                    {historyColumns.map((h, i) => (
                      <th key={h} className={`px-4 py-3 text-sm font-semibold text-slate-500 uppercase tracking-wide ${i === 4 ? 'text-right' : 'text-left'}`}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {paiements.map((p, i) => (
                    <tr key={p.id} className={`hover:bg-slate-50 transition-colors ${i % 2 === 0 ? '' : 'bg-slate-50/50'}`}>
                      <td className="px-4 py-3 font-mono text-sm text-slate-500">{p.recu_numero}</td>
                      <td className="px-4 py-3">
                        <Link href={studentLinks(slug as string, { id: p.eleve_id, nom: p.eleve_nom, prenom: p.eleve_prenom, numero_matricule: p.numero_matricule }).fiche}
                          className="block hover:text-emerald-700">
                          <p className="font-semibold text-slate-800 text-base">{p.eleve_nom} {p.eleve_prenom}</p>
                          <p className="text-sm text-slate-400">{p.numero_matricule}</p>
                        </Link>
                      </td>
                      <td className="px-4 py-3 text-base text-slate-600">{p.classe_nom || 'ΓÇö'}</td>
                      <td className="px-4 py-3">
                        <span className="text-sm font-medium px-2.5 py-1 rounded-full bg-blue-100 text-blue-700">{t('list.installment', { num: p.tranche_numero })}</span>
                      </td>
                      <td className="px-4 py-3 font-semibold text-slate-800 text-base text-right tabular-nums whitespace-nowrap">{Number(p.montant).toLocaleString('fr-FR')} {tc('currency')}</td>
                      <td className="px-4 py-3 text-base text-slate-600">{te.paymentMethod(p.mode_paiement)}</td>
                      <td className="px-4 py-3 text-base text-slate-500">{p.date_paiement}</td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-3">
                          <button onClick={() => openEdit(p)} className="text-sm text-blue-600 hover:text-blue-700 font-medium flex items-center gap-1">
                            <Pencil className="w-3.5 h-3.5" /> {tc('edit')}
                          </button>
                          <button onClick={() => imprimerRecu(p)} className="text-sm text-emerald-600 hover:text-emerald-700 font-medium flex items-center gap-1">
                            <Printer className="w-3.5 h-3.5" /> {t('list.editReceipt')}
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {editPaiement && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-6">
            <div className="flex items-center justify-between mb-6">
              <h2 className="font-bold text-slate-800">{t('list.editTitle')}</h2>
              <button onClick={() => setEditPaiement(null)}><X className="w-5 h-5 text-slate-400" /></button>
            </div>
            <div className="space-y-4">
              <div className="text-sm text-slate-500 -mt-2">
                {editPaiement.eleve_nom} {editPaiement.eleve_prenom} ΓÇö {editPaiement.recu_numero}
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">{t('list.amountLabel')}</label>
                <input type="number" value={editForm.montant}
                  onChange={e => setEditForm(p => ({ ...p, montant: e.target.value }))}
                  className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">{t('list.installmentLabel')}</label>
                  <select value={editForm.tranche_numero}
                    onChange={e => setEditForm(p => ({ ...p, tranche_numero: e.target.value }))}
                    className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400">
                    {[1, 2, 3].map(n => (
                      <option key={n} value={String(n)}>{t('list.installmentN', { n })}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">{t('list.modeLabel')}</label>
                  <select value={editForm.mode_paiement}
                    onChange={e => setEditForm(p => ({ ...p, mode_paiement: e.target.value }))}
                    className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400">
                    {editPaymentMethods.map(o => (
                      <option key={o.value} value={o.value}>{o.label}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">{t('list.dateLabel')}</label>
                <input type="date" value={editForm.date_paiement}
                  onChange={e => setEditForm(p => ({ ...p, date_paiement: e.target.value }))}
                  className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
              </div>
              <div className="flex gap-3 pt-2">
                <button onClick={() => setEditPaiement(null)}
                  className="flex-1 border border-slate-200 text-slate-600 font-semibold rounded-lg px-4 py-2.5 text-sm">{tc('cancel')}</button>
                <button onClick={handleEdit} disabled={savingEdit}
                  className="flex-1 bg-emerald-500 hover:bg-emerald-600 text-white font-semibold rounded-lg px-4 py-2.5 text-sm disabled:opacity-50">
                  {savingEdit ? tc('saving') : tc('save')}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {recuAReimprimer && (
        <RecuPrint paiementId={recuAReimprimer.id} numero={recuAReimprimer.recu_numero}
          onClose={() => setRecuAReimprimer(null)} />
      )}
    </PageShell>
  )
}

function PaiementsPageFallback() {
  const t = useTranslations('paiements')
  const tc = useTranslations('common')

  return (
    <PageShell title={t('list.title')} breadcrumb={t('list.breadcrumb')}>
      <div className="card p-16 text-center text-slate-400">{tc('loading')}</div>
    </PageShell>
  )
}

export default function PaiementsPage() {
  return (
    <Suspense fallback={<PaiementsPageFallback />}>
      <PaiementsPageContent />
    </Suspense>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useParams } from 'next/navigation'
import { useTranslations } from 'next-intl'
import {
  Save, Database, Calendar, FolderOpen,
  Check, AlertTriangle, Plus, Upload, X, Building2,
  Phone, Mail, MapPin, User, Link as LinkIcon, HardDrive,
  Clock, ChevronRight,
} from 'lucide-react'
import PageShell from '@/components/layout/PageShell'
import UsersManagement from '@/components/parametres/UsersManagement'
import AuditLogPanel from '@/components/parametres/AuditLogPanel'
import DesktopAppPanel from '@/components/parametres/DesktopAppPanel'
import AppUpdates from '@/components/parametres/AppUpdates'
import SectionIcon from '@/components/ui/SectionIcon'
import { useSchool } from '@/components/layout/SchoolProvider'
import toast from 'react-hot-toast'
import { getDefaultAnneeScolaireLabel } from '@/lib/school-year'

interface AnneeScolaire {
  id: string
  label: string
  is_active: number
}

interface Backup {
  name: string
  date: string
  size: number
}

const STORAGE_PATHS = [
  { label: 'schoolmanager.db', descKey: 'database' as const },
  { label: 'uploads/eleves/', descKey: 'photos' as const },
  { label: 'backups/', descKey: 'backups' as const },
  { label: 'exports/', descKey: 'exports' as const },
]

export default function ParametresPage() {
  const { slug } = useParams()
  const { userRole, setLogoUrl } = useSchool()
  const t = useTranslations('parametres')
  const tc = useTranslations('common')

  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [annees, setAnnees] = useState<AnneeScolaire[]>([])
  const [backups, setBackups] = useState<Backup[]>([])
  const [newAnnee, setNewAnnee] = useState('')
  const [dataPath, setDataPath] = useState('Documents/SchoolManager')
  const [confirmActivate, setConfirmActivate] = useState<AnneeScolaire | null>(null)
  const [backingUp, setBackingUp] = useState(false)
  const [exporting, setExporting] = useState(false)
  const [restoring, setRestoring] = useState(false)
  const [logoPreview, setLogoPreview] = useState<string | null>(null)
  const [entetePreview, setEntetePreview] = useState<string | null>(null)
  const [savingEntete, setSavingEntete] = useState(false)

  const [form, setForm] = useState({
    nom: '', telephone: '', adresse: '',
    email: '', directeur_nom: '', logo_url: '', entete_url: '',
    nom_caissier: '',
  })

  const up = (f: string, v: string) => setForm(p => ({ ...p, [f]: v }))

  useEffect(() => {
    if (typeof window !== 'undefined' && window.electronAPI?.getDataPath) {
      window.electronAPI.getDataPath().then(setDataPath)
    }
  }, [])

  useEffect(() => {
    Promise.all([
      fetch('/api/ecole').then(r => r.json()),
      fetch('/api/annees-scolaires').then(r => r.json()),
      fetch('/api/backup').then(r => r.json()),
    ]).then(([ecoleData, anneeData, backupData]) => {
      if (ecoleData.ecole) {
        setForm({
          nom: ecoleData.ecole.nom || '',
          telephone: ecoleData.ecole.telephone || '',
          adresse: ecoleData.ecole.adresse || '',
          email: ecoleData.ecole.email || '',
          directeur_nom: ecoleData.ecole.directeur_nom || '',
          logo_url: ecoleData.ecole.logo_url || '',
          entete_url: ecoleData.ecole.entete_url || '',
          nom_caissier: ecoleData.ecole.nom_caissier || '',
        })
        if (ecoleData.ecole.logo_url) setLogoPreview(ecoleData.ecole.logo_url)
        if (ecoleData.ecole.entete_url) setEntetePreview(ecoleData.ecole.entete_url)
      }
      setAnnees(anneeData.annees || [])
      setBackups(backupData.backups || [])
      setLoading(false)
    })
  }, [])

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => {
      const result = reader.result as string
      setLogoPreview(result)
      up('logo_url', result)
      setLogoUrl(result)
    }
    reader.readAsDataURL(file)
  }

  const handleEnteteChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    if (file.size > 2 * 1024 * 1024) {
      toast.error(t('toasts.imageTooLarge'))
      return
    }
    const reader = new FileReader()
    reader.onload = () => {
      const result = reader.result as string
      setEntetePreview(result)
      up('entete_url', result)
    }
    reader.readAsDataURL(file)
  }

  const handleEnteteSave = async () => {
    setSavingEntete(true)
    const res = await fetch('/api/ecole', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ entete_url: form.entete_url, nom_caissier: form.nom_caissier }),
    })
    setSavingEntete(false)
    if (res.ok) toast.success(t('toasts.headerSaved'))
    else toast.error(t('toasts.saveError'))
  }

  const handleEnteteDelete = async () => {
    setEntetePreview(null)
    up('entete_url', '')
    setSavingEntete(true)
    const res = await fetch('/api/ecole', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ entete_url: '' }),
    })
    setSavingEntete(false)
    if (res.ok) toast.success(t('toasts.headerDeleted'))
    else toast.error(t('toasts.headerDeleteError'))
  }

  const handleSave = async () => {
    setSaving(true)
    const res = await fetch('/api/ecole', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form),
    })
    setSaving(false)
    if (res.ok) {
      setLogoUrl(form.logo_url || null)
      toast.success(t('toasts.saved'))
    }
    else toast.error(t('toasts.saveError'))
  }

  const handleAddAnnee = async () => {
    if (!newAnnee.trim()) return
    const res = await fetch('/api/annees-scolaires', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ label: newAnnee, is_active: annees.length === 0 }),
    })
    if (!res.ok) { toast.error(t('toasts.yearAddError')); return }
    const data = await fetch('/api/annees-scolaires').then(r => r.json())
    setAnnees(data.annees || [])
    setNewAnnee('')
    toast.success(t('toasts.yearAdded'))
  }

  const handleActivateAnnee = async (annee: AnneeScolaire) => {
    await fetch('/api/annees-scolaires', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: annee.id, is_active: true }),
    })
    const data = await fetch('/api/annees-scolaires').then(r => r.json())
    setAnnees(data.annees || [])
    setConfirmActivate(null)
    toast.success(t('toasts.yearActivated', { label: annee.label }))
  }

  const handleBackup = async (action: 'manual' | 'export') => {
    if (action === 'manual') setBackingUp(true)
    else setExporting(true)

    const res = await fetch('/api/backup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action }),
    })
    const data = await res.json()

    if (action === 'manual') setBackingUp(false)
    else setExporting(false)

    if (data.success) {
      toast.success(action === 'manual' ? t('toasts.backupCreated') : t('toasts.exportDone'))
      const backupData = await fetch('/api/backup').then(r => r.json())
      setBackups(backupData.backups || [])
    } else {
      toast.error(t('toasts.backupError'))
    }
  }

  const handleRestore = async () => {
    if (typeof window === 'undefined' || !window.electronAPI?.restoreDatabase) return

    setRestoring(true)
    try {
      const result = await window.electronAPI.restoreDatabase()
      if (!result?.success && !result?.canceled) {
        toast.error(result?.error || t('toasts.restoreError'))
      }
