function PersonnelPageContent() {
  const t = useTranslations('personnel')
  const tc = useTranslations('common')
  const tf = useTranslations('filters')
  const te = useTranslatedEnums()

  const [personnel, setPersonnel] = useState<Staff[]>([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [saving, setSaving] = useState(false)

  const filterFields = useMemo(() => [
    { key: 'q', type: 'search' as const, placeholder: t('searchPlaceholder'), debounce: true },
    {
      key: 'type',
      type: 'pills' as const,
      label: tf('labels.type'),
      options: [
        { value: '', label: tc('all') },
        ...TYPE_VALUES.map(value => ({ value, label: te.personnelType(value) })),
      ],
      defaultValue: '',
    },
    {
      key: 'contrat',
      type: 'select' as const,
      label: tf('labels.contract'),
      options: [
        { value: '', label: t('allContracts') },
        ...CONTRAT_VALUES.map(value => ({ value, label: te.contractType(value) })),
      ],
      defaultValue: '',
    },
  ], [t, tc, tf, te])

  const { values, debouncedValues, setFilter, reset, activeFilters } = useSmartFilters(filterFields)

  const [form, setForm] = useState({
    nom: '', prenom: '', telephone: '', email: '',
    type: 'enseignant', contrat: 'cdi',
    date_embauche: '', salaire: '',
  })

  const up = (f: string, v: string) => setForm(p => ({ ...p, [f]: v }))

  const fetchPersonnel = useCallback(async () => {
    setLoading(true)
    const params = new URLSearchParams()
    if (debouncedValues.q) params.set('search', debouncedValues.q)
    if (debouncedValues.type) params.set('type', debouncedValues.type)
    if (debouncedValues.contrat) params.set('contrat', debouncedValues.contrat)
    const res = await fetch(`/api/personnel?${params}`)
    const data = await res.json()
    setPersonnel(data.personnel || [])
    setLoading(false)
  }, [debouncedValues])

  useEffect(() => { fetchPersonnel() }, [fetchPersonnel])

  const handleCreate = async () => {
    if (!form.nom || !form.type) return
    setSaving(true)
    await fetch('/api/personnel', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form),
    })
    toast.success(t('toasts.added'))
    setShowForm(false)
    setForm({ nom: '', prenom: '', telephone: '', email: '', type: 'enseignant', contrat: 'cdi', date_embauche: '', salaire: '' })
    await fetchPersonnel()
    setSaving(false)
  }

  const handleDelete = async (id: string) => {
    if (!confirm(t('deleteConfirm'))) return
    await fetch(`/api/personnel?id=${id}`, { method: 'DELETE' })
    await fetchPersonnel()
    toast.success(t('toasts.deleted'))
  }

  const columnHeaders = [
    t('columns.fullName'),
    t('columns.type'),
    t('columns.contract'),
    t('columns.contact'),
    t('columns.salary'),
    '',
  ]

  return (
    <PageShell
      title={t('title')}
      subtitle={t('subtitle', { count: personnel.length })}
      breadcrumb={t('breadcrumb')}
      actions={
        <button onClick={() => setShowForm(true)} className="btn-primary flex items-center gap-2 py-2.5">
          <Plus className="w-5 h-5" /> {t('add')}
        </button>
      }
    >
      <SmartFilterBar
        fields={filterFields}
        values={values}
        onChange={setFilter}
        onReset={reset}
        activeFilters={activeFilters}
        resultCount={personnel.length}
        resultLabel={t('resultLabel')}
        loading={loading}
        className="mb-6"
      />

      <Modal open={showForm} onClose={() => setShowForm(false)} title={t('newMember')} size="lg">
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">{t('fields.lastName')} *</label>
              <input value={form.nom} onChange={e => up('nom', e.target.value)}
                placeholder={t('placeholders.lastName')}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">{t('fields.firstName')}</label>
              <input value={form.prenom} onChange={e => up('prenom', e.target.value)}
                placeholder={t('placeholders.firstName')}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">{t('fields.phone')}</label>
              <input value={form.telephone} onChange={e => up('telephone', e.target.value)}
                placeholder={t('placeholders.phone')}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">{t('fields.email')}</label>
              <input value={form.email} onChange={e => up('email', e.target.value)}
                placeholder={t('placeholders.email')}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">{t('fields.type')} *</label>
              <select value={form.type} onChange={e => up('type', e.target.value)}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400">
                {TYPE_VALUES.map(value => (
                  <option key={value} value={value}>{te.personnelType(value)}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">{t('fields.contract')}</label>
              <select value={form.contrat} onChange={e => up('contrat', e.target.value)}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400">
                {CONTRAT_VALUES.map(value => (
                  <option key={value} value={value}>{te.contractType(value)}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">{t('fields.hireDate')}</label>
              <input type="date" value={form.date_embauche} onChange={e => up('date_embauche', e.target.value)}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">{t('fields.salary')}</label>
              <input type="number" value={form.salaire} onChange={e => up('salaire', e.target.value)}
                placeholder={t('placeholders.salary')}
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-400" />
            </div>
          </div>

          <button onClick={handleCreate} disabled={saving || !form.nom} className="w-full btn-primary">
            {saving ? tc('saving') : t('submit')}
          </button>
        </div>
      </Modal>

      <div className="card overflow-hidden">
        {loading ? (
          <div className="p-12 text-center text-slate-400 text-sm">{tc('loading')}</div>
        ) : personnel.length === 0 ? (
          <div className="p-12 text-center">
            <p className="text-slate-400 text-sm mb-4">{t('empty')}</p>
            <button onClick={() => setShowForm(true)}
              className="text-emerald-500 hover:text-emerald-600 text-sm font-medium">
              {t('emptyAction')}
            </button>
          </div>
        ) : (
          <table className="w-full">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                {columnHeaders.map(h => (
                  <th key={h} className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {personnel.map((s, i) => (
                <tr key={s.id} className={`hover:bg-slate-50 transition-colors ${i % 2 === 0 ? '' : 'bg-slate-50/50'}`}>
                  <td className="px-4 py-3">
                    <p className="font-semibold text-slate-800 text-sm">{s.nom} {s.prenom}</p>
                    <p className="text-xs text-slate-400">{s.date_embauche || 'ΓÇö'}</p>
                  </td>
                  <td className="px-4 py-3">
                    <span className={`text-xs font-medium px-2 py-1 rounded-full ${typeColor(s.type)}`}>
                      {te.personnelType(s.type)}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-sm text-slate-600">{te.contractType(s.contrat)}</td>
                  <td className="px-4 py-3">
                    <p className="text-sm text-slate-600">{s.telephone || 'ΓÇö'}</p>
                    <p className="text-xs text-slate-400">{s.email || ''}</p>
                  </td>
                  <td className="px-4 py-3 text-sm text-slate-600">
                    {s.salaire ? `${Number(s.salaire).toLocaleString()} ${tc('currency')}` : 'ΓÇö'}
                  </td>
                  <td className="px-4 py-3">
                    <button onClick={() => handleDelete(s.id)}
                      className="text-slate-300 hover:text-red-500 transition-colors">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </PageShell>
  )
}

function typeColor(type: string) {
  const map: Record<string, string> = {
    enseignant: 'bg-blue-100 text-blue-700',
    administratif: 'bg-purple-100 text-purple-700',
    assistant_maternelle: 'bg-pink-100 text-pink-700',
    securite: 'bg-red-100 text-red-700',
    entretien: 'bg-amber-100 text-amber-700',
    chauffeur: 'bg-slate-100 text-slate-700',
  }
  return map[type] || 'bg-slate-100 text-slate-700'
}

'use client'

import { Suspense, useEffect, useMemo, useState } from 'react'
import { useParams } from 'next/navigation'
import Link from 'next/link'
import { useTranslations } from 'next-intl'
import { Save, CheckSquare } from 'lucide-react'
import toast from 'react-hot-toast'
import PageShell from '@/components/layout/PageShell'
import EmptyState from '@/components/ui/EmptyState'
import SmartFilterBar from '@/components/filters/SmartFilterBar'
import StudentContextBanner from '@/components/students/StudentContextBanner'
import { useSmartFilters } from '@/hooks/useSmartFilters'
import { useStudentDeepLink } from '@/hooks/useStudentDeepLink'
import { useClasses } from '@/hooks/useClasses'
import { studentLinks } from '@/lib/student-context-links'
import { dateWithOffset } from '@/lib/filter-presets'
import { usePresenceDatePresets, useTranslatedEnums } from '@/hooks/useTranslatedEnums'

interface ElevePresence {
  id: string
  nom: string
  prenom: string
  numero_matricule: string
  statut: string | null
  obs: string | null
}

type Statut = 'present' | 'absent' | 'retard' | 'excuse'

function PresencesPageFallback() {
  const t = useTranslations('presences')
  const tc = useTranslations('common')

  return (
    <PageShell title={t('title')} breadcrumb={t('breadcrumb')}>
      <div className="card p-12 text-center text-slate-400">{tc('loading')}</div>
    </PageShell>
  )
}

function PresencesPageContent() {
  const { slug } = useParams() as { slug: string }
  const t = useTranslations('presences')
  const tc = useTranslations('common')
  const tf = useTranslations('filters')
  const te = useTranslatedEnums()
  const datePresets = usePresenceDatePresets()
  const { classes } = useClasses()
  const [eleves, setEleves] = useState<ElevePresence[]>([])
  const [presences, setPresences] = useState<Record<string, Statut>>({})
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [saved, setSaved] = useState(false)

  const filterFields = useMemo(() => [
    {
      key: 'classe',
      type: 'select' as const,
      label: tf('labels.class'),
      options: [{ value: '', label: t('selectClassOption') }, ...classes.map(c => ({ value: c.id, label: c.nom }))],
      defaultValue: '',
    },
    {
      key: 'date',
      type: 'date' as const,
      label: tf('labels.date'),
      defaultValue: new Date().toISOString().split('T')[0],
    },
    {
      key: 'q',
      type: 'search' as const,
      placeholder: t('filterStudent'),
      debounce: true,
    },
    {
      key: 'statut',
      type: 'pills' as const,
      label: t('filterShow'),
      options: [
        { value: 'tous', label: tc('all') },
        { value: 'present', label: t('summary.present') },
        { value: 'absent', label: t('summary.absent') },
        { value: 'retard', label: t('summary.retard') },
        { value: 'excuse', label: t('summary.excuse') },
      ],
      defaultValue: 'tous',
    },
  ], [classes, t, tc, tf])

  const { values, debouncedValues, setFilter, setFilters, reset, activeFilters } = useSmartFilters(filterFields)
  const { student } = useStudentDeepLink(setFilters)
  const classeId = values.classe
  const date = values.date || new Date().toISOString().split('T')[0]

  useEffect(() => {
    if (!classeId) { setEleves([]); return }
    setLoading(true)
    fetch(`/api/presences?classe_id=${classeId}&date=${date}`)
      .then(r => r.json())
      .then(d => {
        setEleves(d.eleves || [])
        const map: Record<string, Statut> = {}
        d.eleves?.forEach((e: ElevePresence) => {
          map[e.id] = (e.statut as Statut) || 'present'
        })
        setPresences(map)
        setLoading(false)
      })
  }, [classeId, date])

  const filteredEleves = useMemo(() => {
    let list = eleves
    const q = debouncedValues.q?.toLowerCase().trim()
    if (q) {
      list = list.filter(e =>
        `${e.nom} ${e.prenom} ${e.numero_matricule}`.toLowerCase().includes(q)
      )
    }
    const statutFiltre = debouncedValues.statut
    if (statutFiltre && statutFiltre !== 'tous') {
      list = list.filter(e => presences[e.id] === statutFiltre)
    }
    return list
  }, [eleves, debouncedValues.q, debouncedValues.statut, presences])

  const setTousPresents = () => {
    const map: Record<string, Statut> = {}
    eleves.forEach(e => { map[e.id] = 'present' })
    setPresences(map)
  }

  const toggleStatut = (eleveId: string, statut: Statut) => {
    setPresences(prev => ({ ...prev, [eleveId]: statut }))
  }

  const handleSave = async () => {
    setSaving(true)
    const data = Object.entries(presences).map(([eleve_id, statut]) => ({
      eleve_id, statut, note: null,
    }))
    await fetch('/api/presences', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ date, presences: data }),
    })
    setSaving(false)
    setSaved(true)
    toast.success(t('toasts.saved'))
    setTimeout(() => setSaved(false), 2000)
  }

  const stats = {
    present: Object.values(presences).filter(s => s === 'present').length,
    absent: Object.values(presences).filter(s => s === 'absent').length,
    retard: Object.values(presences).filter(s => s === 'retard').length,
    excuse: Object.values(presences).filter(s => s === 'excuse').length,
  }

  const statutConfig: Record<Statut, { label: string; active: string; inactive: string }> = {
    present: { label: te.presenceStatus('present'), active: 'bg-emerald-500 text-white', inactive: 'bg-slate-100 text-slate-500 hover:bg-emerald-50' },
    absent: { label: te.presenceStatus('absent'), active: 'bg-red-500 text-white', inactive: 'bg-slate-100 text-slate-500 hover:bg-red-50' },
    retard: { label: te.presenceStatus('retard'), active: 'bg-amber-500 text-white', inactive: 'bg-slate-100 text-slate-500 hover:bg-amber-50' },
    excuse: { label: te.presenceStatus('excuse'), active: 'bg-blue-500 text-white', inactive: 'bg-slate-100 text-slate-500 hover:bg-blue-50' },
  }

  const summaryLabels: Record<keyof typeof stats, string> = {
    present: t('summary.present'),
    absent: t('summary.absent'),
    retard: t('summary.retard'),
    excuse: t('summary.excuse'),
  }

  return (
    <PageShell title={t('title')} subtitle={t('subtitle')} breadcrumb={t('breadcrumb')}>
      <SmartFilterBar
        fields={filterFields}
        values={values}
        onChange={setFilter}
        onReset={reset}
        activeFilters={activeFilters}
        resultCount={classeId ? filteredEleves.length : undefined}
        resultLabel={t('resultLabel')}
        loading={loading}
        extra={
          <div className="flex flex-wrap gap-1.5">
            {datePresets.map(p => (
              <button
                key={p.label}
                type="button"
                onClick={() => setFilter('date', dateWithOffset(p.offset))}
                className="text-xs font-semibold px-2.5 py-1 rounded-full bg-slate-100 text-slate-600 hover:bg-emerald-50 hover:text-emerald-700"
              >
                {p.label}
              </button>
            ))}
            {eleves.length > 0 && (
              <>
                <button onClick={setTousPresents}
                  className="text-xs font-semibold px-3 py-1.5 rounded-full border border-emerald-200 text-emerald-600 hover:bg-emerald-50">
                  {t('markAllPresent')}
                </button>
                <button onClick={handleSave} disabled={saving}
                  className="flex items-center gap-1.5 bg-emerald-500 hover:bg-emerald-600 disabled:bg-slate-200 text-white text-xs font-semibold px-3 py-1.5 rounded-full">
                  <Save className="w-3.5 h-3.5" />
                  {saving ? tc('saving') : saved ? tc('saved') : t('validate')}
                </button>
              </>
            )}
          </div>
        }
        className="mb-4"
      />

      {student && <StudentContextBanner slug={slug} student={student} className="mb-6" />}

      {eleves.length > 0 && (
        <div className="grid grid-cols-4 gap-3 mb-6">
          {(Object.keys(stats) as Array<keyof typeof stats>).map(key => (
            <button
              key={key}
              type="button"
              onClick={() => setFilter('statut', key === values.statut ? 'tous' : key)}
              className={`bg-white rounded-lg border px-4 py-3 flex items-center justify-between transition-colors ${
                values.statut === key ? 'border-emerald-400 bg-emerald-50' : 'border-slate-200 hover:border-slate-300'
              }`}
            >
              <span className="text-sm text-slate-500">{summaryLabels[key]}</span>
              <span className="font-bold text-slate-800">{stats[key]}</span>
            </button>
          ))}
        </div>
      )}

      {!classeId ? (
        <div className="card p-12 text-center text-slate-400 text-sm">{t('selectClass')}</div>
      ) : loading ? (
        <div className="card p-12 text-center text-slate-400 text-sm">{tc('loading')}</div>
      ) : filteredEleves.length === 0 ? (
        <EmptyState
          icon={CheckSquare}
          title={t('emptyTitle')}
          description={t('emptyDescription')}
        />
      ) : (
        <div className="card overflow-hidden">
          <table className="w-full">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">#</th>
                <th className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">{t('columns.student')}</th>
                <th className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide">{t('columns.status')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredEleves.map((eleve, i) => (
                <tr key={eleve.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-4 py-3 text-sm text-slate-400">{i + 1}</td>
                  <td className="px-4 py-3">
                    <Link href={studentLinks(slug, { id: eleve.id, nom: eleve.nom, prenom: eleve.prenom, numero_matricule: eleve.numero_matricule }).fiche}
                      className="group block">
                      <p className="font-medium text-slate-800 text-sm group-hover:text-emerald-700">{eleve.nom} {eleve.prenom}</p>
                      <p className="text-xs text-slate-400">{eleve.numero_matricule}</p>
                    </Link>
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex gap-2 flex-wrap">
                      {(Object.keys(statutConfig) as Statut[]).map(s => (
                        <button key={s} onClick={() => toggleStatut(eleve.id, s)}
                          className={`text-xs font-medium px-3 py-1.5 rounded-lg transition-colors ${
                            presences[eleve.id] === s ? statutConfig[s].active : statutConfig[s].inactive
                          }`}>
                          {statutConfig[s].label}
                        </button>
                      ))}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </PageShell>
  )
}

export default function PresencesPage() {
  return (
    <Suspense fallback={<PresencesPageFallback />}>
      <PresencesPageContent />
    </Suspense>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { Copy, Check, Plus, Gift, Pencil, Search } from 'lucide-react'
import { useTranslations } from 'next-intl'
import { AdminLicencesShell, AdminBadge } from '@/components/admin-licences/AdminShell'
import { SchoolIdentity } from '@/components/admin-licences/SchoolIdentity'
import { CreateKeyModal } from '@/components/admin-licences/CreateKeyModal'
import { EditSchoolModal } from '@/components/admin-licences/EditSchoolModal'
import {
  type AdminLicence,
  PLAN_COLORS,
  isLicenceAssigned,
  hasSchoolName,
  resolveEcoleNom,
  licenceStatus,
  formatDateFr,
} from '@/lib/admin-licences-types'

type Filter = 'toutes' | 'disponibles' | 'attribuees' | 'sans_nom'

function LicenceCard({
  l,
  onRevoke,
  onCopy,
  onEdit,
  copied,
}: {
  l: AdminLicence
  onRevoke: (id: string) => void
  onCopy: (key: string) => void
  onEdit: (l: AdminLicence) => void
  copied: string
}) {
  const t = useTranslations('adminLicences')
  const assigned = isLicenceAssigned(l)
  const status = licenceStatus(l)

  const statusLabel = () => {
    if (!l.is_active) return t('licences.status.revoked')
    if (status.daysLeft < 0) return t('licences.status.expired')
    if (status.daysLeft <= 30) return t('licences.status.daysLeft', { days: status.daysLeft })
    return t('licences.status.active')
  }

  return (
    <article className="rounded-2xl border border-slate-800 bg-gradient-to-br from-slate-900/90 to-slate-950/90 p-4 space-y-4">
      <SchoolIdentity licence={l} onEdit={assigned && !hasSchoolName(l) ? () => onEdit(l) : undefined} />

      <div className="rounded-xl bg-slate-950 border border-slate-800 p-3">
        <p className="text-[10px] uppercase tracking-wide text-slate-600 mb-1.5">{t('licences.columns.key')}</p>
        <div className="flex items-center gap-2">
