              <p className="text-[10px] text-slate-600 mt-2">{formatDateFr(p.created_at)}</p>
            </article>
          ))}
        </div>
      )}

      {edit && <EditModal p={edit} onClose={() => setEdit(null)} onSaved={load} />}
    </>
  )
