import { NextRequest, NextResponse } from 'next/server'
import { getDbPath, ensureUserDataDir } from '@/lib/paths'

const LICENCE_SERVER_URL = 'https://schoolmanager-eosin.vercel.app'

function getDb() {
  if (process.env.VERCEL) return null

  try {
    const Database = require('better-sqlite3')
    ensureUserDataDir()
    const db = new Database(getDbPath())
    db.pragma('journal_mode = WAL')
    db.pragma('foreign_keys = ON')
    db.exec(`
      CREATE TABLE IF NOT EXISTS licence_cache (
        cle TEXT PRIMARY KEY,
        plan TEXT NOT NULL,
        date_fin TEXT NOT NULL,
        last_verified TEXT NOT NULL,
        is_active INTEGER DEFAULT 1
      );
    `)
    return db
  } catch (e) {
    console.error('[verify] getDb error:', e)
    return null
  }
}

async function verifyOnVercel(cle: string) {
  try {
    const { createClient } = await import('@supabase/supabase-js')
    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    )

    const { data: licence } = await supabase
      .from('licences')
      .select('cle_licence, type, date_fin, is_active, ecole_id')
      .eq('cle_licence', cle)
      .single()

    if (!licence) return NextResponse.json({ valid: false, error: 'Cl├⌐ invalide' })
    if (!licence.is_active) return NextResponse.json({ valid: false, error: 'Licence r├⌐voqu├⌐e' })
    if (licence.ecole_id) return NextResponse.json({ valid: false, error: 'Cl├⌐ d├⌐j├á utilis├⌐e' })

    const today = new Date().toISOString().split('T')[0]
    if (licence.date_fin < today) return NextResponse.json({ valid: false, error: 'Licence expir├⌐e' })

    return NextResponse.json({
      valid: true,
      plan: licence.type,
      date_fin: licence.date_fin,
      message: `Licence ${licence.type} valide jusqu'au ${licence.date_fin}`,
    })
  } catch (e) {
    console.error('[verify] supabase error:', e)
    return NextResponse.json({ valid: false, error: 'Erreur serveur' }, { status: 500 })
  }
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const cle = searchParams.get('cle')?.trim().toUpperCase()

  if (!cle) {
    return NextResponse.json({ valid: false, error: 'Cl├⌐ requise' })
  }

  if (process.env.VERCEL) {
    return verifyOnVercel(cle)
  }

  // En local (Electron) : appel Vercel + cache SQLite
  const today = new Date().toISOString().split('T')[0]
  const db = getDb()

  try {
    const res = await fetch(
      `${LICENCE_SERVER_URL}/api/auth/verify-licence?cle=${encodeURIComponent(cle)}`,
      {
        headers: {
          'User-Agent': 'SchoolManager-Desktop/1.0',
          'Accept': 'application/json',
        },
        signal: AbortSignal.timeout(8000),
      }
    )

    const data = await res.json()
    console.log('[verify] r├⌐ponse Vercel:', JSON.stringify(data))

    if (data.valid) {
      if (db) {
        try {
          db.prepare(`
            INSERT INTO licence_cache (cle, plan, date_fin, last_verified, is_active)
            VALUES (?, ?, ?, ?, 1)
            ON CONFLICT(cle) DO UPDATE SET
              plan = excluded.plan,
              date_fin = excluded.date_fin,
              last_verified = excluded.last_verified,
              is_active = 1
          `).run(cle, data.plan, data.date_fin, new Date().toISOString())
        } catch (e) {
          console.error('[verify] cache save error:', e)
        }
      }

      return NextResponse.json({
        valid: true,
        plan: data.plan,
        date_fin: data.date_fin,
        message: data.message,
        source: 'online',
      })
    }

    return NextResponse.json({
      valid: false,
      error: data.error || 'Cl├⌐ invalide',
      source: 'online',
    })

  } catch (err: any) {
    console.error('[verify] serveur inaccessible:', err?.message)
  }

  // Fallback cache offline
  if (db) {
    try {
      const cached = db.prepare('SELECT * FROM licence_cache WHERE cle = ?').get(cle) as any

      if (!cached) {
        return NextResponse.json({
          valid: false,
          error: 'Connexion internet requise pour la premi├¿re activation',
          source: 'offline',
        })
      }

      if (!cached.is_active) {
        return NextResponse.json({ valid: false, error: 'Licence r├⌐voqu├⌐e', source: 'offline' })
      }

      if (cached.date_fin < today) {
        return NextResponse.json({ valid: false, error: 'Licence expir├⌐e', source: 'offline' })
      }

      const daysSince = (Date.now() - new Date(cached.last_verified).getTime()) / 86400000
      if (daysSince > 30) {
        return NextResponse.json({
          valid: false,
          error: `Connexion requise (derni├¿re v├⌐rif. il y a ${Math.floor(daysSince)} jours)`,
          source: 'offline',
        })
      }

      return NextResponse.json({
        valid: true,
        plan: cached.plan,
        date_fin: cached.date_fin,
        message: `Licence ${cached.plan} valide (mode offline)`,
        source: 'offline',
      })
    } catch (e) {
      console.error('[verify] cache read error:', e)
    }
  }

  return NextResponse.json({
    valid: false,
    error: 'Erreur de v├⌐rification ΓÇö r├⌐essayez',
    source: 'error',
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { getUserFromRequest } from '../../../lib/auth'
import { getDb } from '../../../lib/db-server'
import { runDailyBackup, listBackups, exportDatabase } from '../../../lib/backup'
import { requireModule } from '../../../lib/rbac.server'
import path from 'path'
import { getBackupsDir } from '../../../lib/paths'

export async function GET(request: NextRequest) {
  const user = await getUserFromRequest(request)
  if (!user?.ecole_id) {
    return NextResponse.json({ error: 'Non autoris├⌐' }, { status: 401 })
  }
  const denied = requireModule(user, 'parametres', 'GET')
  if (denied) return denied

  runDailyBackup()
  const backups = listBackups()

  return NextResponse.json({ backups })
}

export async function POST(request: NextRequest) {
  const user = await getUserFromRequest(request)
  if (!user?.ecole_id) {
    return NextResponse.json({ error: 'Non autoris├⌐' }, { status: 401 })
  }
  const denied = requireModule(user, 'parametres', 'POST')
  if (denied) return denied

  const body = await request.json()
  const action = body.action as string

  if (action === 'manual') {
    const result = runDailyBackup()
    if (!result.success) {
      return NextResponse.json({ error: '├ëchec de la sauvegarde' }, { status: 500 })
    }
    return NextResponse.json({ success: true, path: result.path, skipped: result.skipped })
  }

  if (action === 'export') {
    const timestamp = new Date().toISOString().slice(0, 10)
    const exportPath = path.join(getBackupsDir(), `export-manuel-${timestamp}.db`)
    const ok = exportDatabase(exportPath)
    if (!ok) {
      return NextResponse.json({ error: '├ëchec de l\'export' }, { status: 500 })
    }
    return NextResponse.json({ success: true, path: exportPath })
  }

  return NextResponse.json({ error: 'Action inconnue' }, { status: 400 })
}

import { NextRequest, NextResponse } from 'next/server'
import { getUserFromRequest } from '../../../../lib/auth'
import { getDb } from '../../../../lib/db-server'
import { requireModule } from '../../../../lib/rbac.server'
import {
  fetchExportDataset,
  formatExport,
  ENTITY_MODULES,
  EXPORT_FORMATS,
  type ExportEntity,
  type ExportFormat,
} from '../../../../lib/data-export'

const ENTITIES: ExportEntity[] = ['eleves', 'classes', 'paiements', 'notes', 'presences', 'personnel']

export async function GET(request: NextRequest) {
  const user = await getUserFromRequest(request)
  if (!user?.ecole_id) return NextResponse.json({ error: 'Non autoris├⌐' }, { status: 401 })

  const { searchParams } = new URL(request.url)
  const entity = searchParams.get('entity') as ExportEntity | null
  const format = (searchParams.get('format') || 'csv') as ExportFormat

  if (!entity || !ENTITIES.includes(entity)) {
    return NextResponse.json({ error: 'Entit├⌐ invalide' }, { status: 400 })
  }
  if (!EXPORT_FORMATS.includes(format)) {
    return NextResponse.json({ error: 'Format invalide' }, { status: 400 })
  }

  const module = ENTITY_MODULES[entity]
  const denied = requireModule(user, module, 'GET')
  if (denied) return denied

  const db = getDb()
  const dataset = fetchExportDataset(db, user.ecole_id, entity)
  const { buffer, mime, extension } = formatExport(dataset, format)

  return new NextResponse(new Uint8Array(buffer), {
    headers: {
      'Content-Type': mime,
      'Content-Disposition': `attachment; filename="${extension}"`,
      'Cache-Control': 'no-store',
    },
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { getUserFromRequest } from '../../../../lib/auth'
import { getDb } from '../../../../lib/db-server'
import { getEleveSituation } from '../../../../lib/paiements-utils'
import { getFraisExamenSituationForEleve } from '../../../../lib/frais-examens-utils'
import { requireModule } from '../../../../lib/rbac.server'

export async function GET(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getUserFromRequest(request)
  if (!user?.ecole_id) return NextResponse.json({ error: 'Non autoris├⌐' }, { status: 401 })
  const denied = requireModule(user, 'eleves', 'GET')
  if (denied) return denied

  const { id } = await params
  const db = getDb()

  const eleve = db.prepare(`
    SELECT e.*, c.nom as classe_nom, c.section as classe_section
    FROM eleves e
    LEFT JOIN classes c ON c.id = e.classe_id
    WHERE e.id = ? AND e.ecole_id = ?
  `).get(id, user.ecole_id)

  if (!eleve) return NextResponse.json({ error: '├ël├¿ve introuvable' }, { status: 404 })

  const parents   = db.prepare('SELECT * FROM parents WHERE eleve_id = ?').all(id)
  const paiements = db.prepare('SELECT * FROM paiements WHERE eleve_id = ? ORDER BY date_paiement DESC').all(id)
  const notes     = db.prepare(`
    SELECT n.*, m.nom as matiere_nom, m.coefficient, e.section
    FROM notes n
    LEFT JOIN matieres m ON m.id = n.matiere_id
    LEFT JOIN eleves e ON e.id = n.eleve_id
    WHERE n.eleve_id = ? ORDER BY n.periode, m.nom
  `).all(id)
  const presences = db.prepare(
    'SELECT * FROM presences WHERE eleve_id = ? ORDER BY date DESC LIMIT 60'
  ).all(id)

  const situation = getEleveSituation(db, user.ecole_id, id)
  const fraisExamen = getFraisExamenSituationForEleve(db, user.ecole_id, id)

  const classes = db.prepare(`
    SELECT id, nom, section, niveau FROM classes
    WHERE ecole_id = ? ORDER BY section, nom
  `).all(user.ecole_id)

  const ecole = db.prepare(`
    SELECT nom, adresse, telephone, email, directeur_nom, entete_url
    FROM ecoles WHERE id = ?
  `).get(user.ecole_id) as {
    nom: string; adresse: string; telephone: string; email: string
    directeur_nom: string; entete_url: string | null
  } | undefined

  const anneeRow = db.prepare(
    'SELECT label FROM annees_scolaires WHERE ecole_id = ? AND is_active = 1 LIMIT 1'
  ).get(user.ecole_id) as { label: string } | undefined

  return NextResponse.json({
    eleve, parents, paiements, notes, presences, situation, fraisExamen, classes,
    ecoleNom: ecole?.nom,
    ecole,
    anneeScolaire: anneeRow?.label ?? null,
  })
}

export async function PUT(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getUserFromRequest(request)
  if (!user?.ecole_id) return NextResponse.json({ error: 'Non autoris├⌐' }, { status: 401 })
  const denied = requireModule(user, 'eleves', 'PUT')
  if (denied) return denied

  const { id } = await params
  const body = await request.json()
  const db = getDb()

  let section = body.section
  if (body.classe_id) {
    const classe = db.prepare(
      'SELECT section FROM classes WHERE id = ? AND ecole_id = ?'
    ).get(body.classe_id, user.ecole_id) as { section: string } | undefined
    if (classe) section = classe.section
  }

  db.prepare(`
    UPDATE eleves SET
      nom = ?, prenom = ?, date_naissance = ?,
      lieu_naissance = ?, sexe = ?, classe_id = ?,
      section = ?, statut = ?, statut_annuel = ?,
      photo_url = COALESCE(?, photo_url)
    WHERE id = ? AND ecole_id = ?
  `).run(
    body.nom, body.prenom, body.date_naissance,
    body.lieu_naissance, body.sexe, body.classe_id,
    section, body.statut, body.statut_annuel,
    body.photo_url ?? null,
    id, user.ecole_id
  )

  return NextResponse.json({ success: true })
}
  
export async function DELETE(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getUserFromRequest(request)
  if (!user?.ecole_id) return NextResponse.json({ error: 'Non autoris├⌐' }, { status: 401 })
  const denied = requireModule(user, 'eleves', 'DELETE')
  if (denied) return denied

  const { id } = await params
  const { searchParams } = new URL(request.url)
  const force = searchParams.get('force') === 'true'
  const db = getDb()

  const eleve = db.prepare(
    'SELECT id, nom, prenom FROM eleves WHERE id = ? AND ecole_id = ?'
  ).get(id, user.ecole_id) as any

  if (!eleve) return NextResponse.json({ error: '├ël├¿ve introuvable' }, { status: 404 })

  const paiements = db.prepare(
    'SELECT COUNT(*) as count FROM paiements WHERE eleve_id = ?'
  ).get(id) as { count: number }

  // Si paiements et pas force ΓåÆ demander confirmation
  if (paiements.count > 0 && !force) {
    return NextResponse.json({
      warning: true,
      message: `Cet ├⌐l├¿ve a ${paiements.count} paiement(s) enregistr├⌐(s). Confirmer la suppression ?`,
      nb_paiements: paiements.count
    }, { status: 409 })
  }

  // Supprimer dans l'ordre (contraintes FK)
  db.prepare('DELETE FROM presences WHERE eleve_id = ?').run(id)
  db.prepare('DELETE FROM notes WHERE eleve_id = ?').run(id)
  db.prepare('DELETE FROM competences_maternelle WHERE eleve_id = ?').run(id)
  db.prepare('DELETE FROM paiements WHERE eleve_id = ?').run(id)
  db.prepare('DELETE FROM parents WHERE eleve_id = ?').run(id)
  db.prepare('DELETE FROM liste_attente WHERE eleve_id = ?').run(id)
  db.prepare('DELETE FROM academic_histories WHERE eleve_id = ?').run(id)
  db.prepare('DELETE FROM eleves WHERE id = ? AND ecole_id = ?').run(id, user.ecole_id)

  return NextResponse.json({ success: true, message: `${eleve.prenom} ${eleve.nom} supprim├⌐(e)` })

}

