const CREATION_ROLES: Role[] = ['secretaire', 'comptable', 'enseignant']

export async function GET(request: NextRequest) {
  const user = await getUserFromRequest(request)
  if (!user?.ecole_id) return NextResponse.json({ error: 'Non autoris├⌐' }, { status: 401 })

  if (user.role !== 'admin' && user.role !== 'super_admin') {
    return NextResponse.json({ error: 'R├⌐serv├⌐ ├á l\'administrateur' }, { status: 403 })
  }

  const db = getDb()
  const users = db.prepare(`
    SELECT id, email, nom, prenom, role, telephone, created_at
    FROM users
    WHERE ecole_id = ?
    ORDER BY role, nom
  `).all(user.ecole_id)

