            <span className="text-emerald-400/90 text-xs font-medium tracking-wide">{tCommon('schoolManagement')}</span>
          </div>
        </div>
      </div>

      <nav className="flex-1 p-3 overflow-y-auto space-y-4">
        {NAV_GROUPS(slug, t).map((group, gi) => {
          const visibleItems = group.items.filter(item => {
            const module = NAV_MODULE_MAP[item.key] as Module
            return hasModuleAccess(userRole, module)
          })
          if (visibleItems.length === 0) return null
          return (
            <div key={gi}>
              {group.labelKey && (
                <p className="px-3.5 mb-1 text-[10px] font-semibold uppercase tracking-widest text-slate-500">
                  {t(group.labelKey)}
                </p>
              )}
              <div className="space-y-0.5">
                {visibleItems.map(item => {
                  const active = isActive(pathname, item.href, item.match)
                  return (
                    <a
                      key={item.href}
                      href={item.href}
                      onClick={() => setMobileOpen(false)}
                      className={`group flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all text-[15px] font-medium ${
                        active
                          ? 'bg-emerald-500 text-white shadow-md shadow-emerald-500/25'
                          : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                      }`}
                    >
                      <NavIcon icon={item.icon} active={active} />
                      {t(item.labelKey)}
                    </a>
                  )
                })}
              </div>
            </div>
          )
        })}
      </nav>

      <div className="p-3 border-t border-slate-700/50 space-y-1">
        {showLicence && <SyncStatusBadge slug={slug} />}
        {showLicence && <LicenceSidebarButton />}
        <LanguageSwitcher />
        <button
          onClick={toggleTheme}
          className="group flex items-center gap-3 px-3 py-2.5 rounded-xl text-slate-400 hover:bg-slate-800 hover:text-white transition-colors text-[15px] font-medium w-full"
        >
          <NavIcon icon={theme === 'dark' ? Sun : Moon} />
          {theme === 'dark' ? t('lightMode') : t('darkMode')}
        </button>
        <button
          onClick={handleLogout}
          className="group flex items-center gap-3 px-3 py-2.5 rounded-xl text-slate-400 hover:bg-slate-800 hover:text-white transition-colors text-[15px] font-medium w-full"
        >
          <NavIcon icon={LogOut} />
          {t('logout')}
        </button>
      </div>
    </>
  )

  return (
    <>
      <button
        type="button"
        onClick={() => setMobileOpen(true)}
        className="lg:hidden fixed top-3 left-3 z-40 w-10 h-10 bg-slate-900 text-white rounded-xl flex items-center justify-center shadow-lg"
        aria-label={t('openMenu')}
      >
        <Menu className="w-5 h-5" />
      </button>

      {mobileOpen && (
        <div
          className="lg:hidden fixed inset-0 z-40 bg-black/50"
          onClick={() => setMobileOpen(false)}
          aria-hidden
        />
      )}

      <aside
        className={`fixed lg:static inset-y-0 left-0 z-50 w-[272px] bg-slate-900 flex flex-col h-full shrink-0 border-r border-slate-800 transform transition-transform duration-200 ${
          mobileOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        }`}
      >
        <button
          type="button"
          onClick={() => setMobileOpen(false)}
          className="lg:hidden absolute top-4 right-4 text-slate-400 hover:text-white"
          aria-label={t('closeMenu')}
        >
          <X className="w-5 h-5" />
        </button>
        {navContent}
      </aside>
    </>
  )
}

'use client'

import { useState } from 'react'
import { useTranslations } from 'next-intl'
import { Key, Loader2 } from 'lucide-react'
import { useRouter } from 'next/navigation'
import toast from 'react-hot-toast'

export default function LicenceRenewForm() {
  const t = useTranslations('licence.renewForm')
  const router = useRouter()
  const [cle, setCle] = useState('')
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const key = cle.trim()
    if (!key) return

    setLoading(true)
    try {
      const res = await fetch('/api/licence/renew', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cle: key }),
      })
      const data = await res.json()
      if (!res.ok) {
        toast.error(data.error || t('toasts.failed'))
        return
      }
      toast.success(t('toasts.success'))
      router.refresh()
      window.location.href = '/'
    } catch {
      toast.error(t('toasts.networkError'))
    } finally {
      setLoading(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} className="mt-6 pt-6 border-t border-white/10 space-y-3">
      <p className="text-sm text-slate-300 font-medium">{t('alreadyHaveKey')}</p>
      <div className="flex gap-2">
        <input
          value={cle}
          onChange={e => setCle(e.target.value.toUpperCase())}
          placeholder={t('keyPlaceholder')}
          className="flex-1 bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder:text-slate-500 font-mono text-sm uppercase tracking-wider focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
        />
        <button
          type="submit"
          disabled={loading || !cle.trim()}
          className="shrink-0 flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white font-semibold rounded-xl px-5 py-3 transition-colors"
        >
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Key className="w-4 h-4" />}
          {t('activate')}
        </button>
      </div>
      <p className="text-xs text-slate-500">{t('adminOnly')}</p>
    </form>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useLocale, useTranslations } from 'next-intl'
import { Copy, Check, Gift, UserPlus, Phone, Building2, MessageCircle } from 'lucide-react'
import toast from 'react-hot-toast'
import { getSupportWhatsAppUrl } from '@/lib/support'
import { getIntlLocale, type Locale } from '@/i18n/config'

interface Parrainage {
  id: string
  contact_nom: string
  contact_ecole: string | null
  contact_telephone: string
  statut: string
  commission_montant: number | null
  created_at: string
}

interface ReferralData {
  code: string
  commissionPct: number
  ecoleNom: string
  directeurNom: string | null
  parrainages: Parrainage[]
  stats: {
    enCours: number
    actifs: number
    verses: number
    totalCommission: number
  }
}

export default function ReferralProgram() {
  const t = useTranslations('licence.referral')
  const tc = useTranslations('common')
  const locale = useLocale() as Locale
  const intlLocale = getIntlLocale(locale)
  const [data, setData] = useState<ReferralData | null>(null)
  const [loading, setLoading] = useState(true)
  const [copied, setCopied] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [form, setForm] = useState({
    contact_nom: '',
    contact_ecole: '',
    contact_telephone: '',
    notes: '',
  })

  const fetchReferral = useCallback(async () => {
    setLoading(true)
    const res = await fetch('/api/licence/referral')
    if (res.ok) {
      setData(await res.json())
    }
    setLoading(false)
  }, [])

  useEffect(() => { fetchReferral() }, [fetchReferral])

  const copyCode = async () => {
    if (!data?.code) return
    await navigator.clipboard.writeText(data.code)
    setCopied(true)
    toast.success(t('codeCopied'))
    setTimeout(() => setCopied(false), 2000)
  }

  const shareWhatsApp = () => {
    if (!data) return
    const director = data.directeurNom
      ? t('directorLine', { name: data.directeurNom })
      : ''
    const msg = t('whatsappMessage', {
      code: data.code,
      school: data.ecoleNom,
      director,
    })
    window.open(getSupportWhatsAppUrl(msg), '_blank', 'noopener,noreferrer')
  }

  const submitContact = async () => {
    if (!form.contact_nom.trim() || !form.contact_telephone.trim()) {
      toast.error(t('requiredFields'))
      return
    }
    setSubmitting(true)
    const res = await fetch('/api/licence/referral', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form),
    })
    const json = await res.json()
    setSubmitting(false)
    if (!res.ok) {
      toast.error(json.error || tc('errorLoad'))
      return
    }
    toast.success(json.cloudSynced ? t('savedSynced') : t('savedOffline'))
    setForm({ contact_nom: '', contact_ecole: '', contact_telephone: '', notes: '' })
    setData(prev => prev ? { ...prev, parrainages: json.parrainages, stats: json.stats } : prev)
  }

  if (loading) {
    return (
      <div className="card p-8 text-center text-slate-400 text-sm">{t('loading')}</div>
    )
  }

  if (!data) return null

  return (
    <div className="card overflow-hidden">
      <div className="p-6 bg-gradient-to-br from-violet-50 to-emerald-50 border-b border-slate-100">
        <div className="flex items-start gap-4">
          <div className="w-12 h-12 rounded-2xl bg-violet-500 flex items-center justify-center shrink-0 shadow-lg shadow-violet-500/25">
            <Gift className="w-6 h-6 text-white" />
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="text-lg font-bold text-slate-800">{t('title')}</h3>
            <p className="text-sm text-slate-600 mt-1 leading-relaxed">
              {t.rich('description', {
                pct: data.commissionPct,
                strong: (chunks) => <strong className="text-violet-700">{chunks}</strong>,
              })}
            </p>
          </div>
        </div>

        <div className="mt-5 flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-xl px-4 py-2.5 font-mono text-sm font-semibold text-slate-800">
            {data.code}
            <button
              type="button"
              onClick={copyCode}
              className="p-1 rounded-lg hover:bg-slate-100 text-slate-500"
              title={t('copyCode')}
            >
              {copied ? <Check className="w-4 h-4 text-emerald-600" /> : <Copy className="w-4 h-4" />}
            </button>
          </div>
          <button
            type="button"
            onClick={shareWhatsApp}
            className="inline-flex items-center gap-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-semibold px-4 py-2.5 rounded-xl transition-colors"
          >
            <MessageCircle className="w-4 h-4" />
            {t('contactWithCode')}
          </button>
        </div>
      </div>

      <div className="p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div>
          <h4 className="text-sm font-semibold text-slate-800 mb-3 flex items-center gap-2">
            <UserPlus className="w-4 h-4 text-slate-400" />
            {t('reportContact')}
          </h4>
          <div className="space-y-3">
            <input
              value={form.contact_nom}
              onChange={e => setForm(f => ({ ...f, contact_nom: e.target.value }))}
              placeholder={t('contactName')}
              className="input-field text-sm"
            />
            <input
              value={form.contact_ecole}
              onChange={e => setForm(f => ({ ...f, contact_ecole: e.target.value }))}
              placeholder={t('contactSchool')}
              className="input-field text-sm"
            />
            <input
              value={form.contact_telephone}
              onChange={e => setForm(f => ({ ...f, contact_telephone: e.target.value }))}
              placeholder={t('contactPhone')}
              className="input-field text-sm"
            />
            <textarea
              value={form.notes}
              onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
              placeholder={t('contactNotes')}
              rows={2}
              className="input-field text-sm resize-none"
            />
            <button
              type="button"
              onClick={submitContact}
              disabled={submitting}
              className="btn-primary w-full text-sm py-2.5"
            >
              {submitting ? t('submitting') : t('saveContact')}
            </button>
          </div>
        </div>

        <div>
          <div className="grid grid-cols-3 gap-2 mb-4">
            <div className="rounded-xl bg-slate-50 p-3 text-center">
              <p className="text-lg font-bold text-slate-800">{data.stats.enCours}</p>
              <p className="text-[10px] uppercase tracking-wide text-slate-400">{t('statsInProgress')}</p>
            </div>
            <div className="rounded-xl bg-emerald-50 p-3 text-center">
              <p className="text-lg font-bold text-emerald-700">{data.stats.actifs}</p>
              <p className="text-[10px] uppercase tracking-wide text-emerald-600/80">{t('statsActive')}</p>
            </div>
            <div className="rounded-xl bg-violet-50 p-3 text-center">
              <p className="text-lg font-bold text-violet-700">
                {data.stats.totalCommission > 0
                  ? `${data.stats.totalCommission.toLocaleString(intlLocale)}`
                  : 'ΓÇö'}
              </p>
              <p className="text-[10px] uppercase tracking-wide text-violet-600/80">{t('statsEarned')}</p>
            </div>
          </div>

          {data.parrainages.length === 0 ? (
            <p className="text-sm text-slate-400 text-center py-6">{t('empty')}</p>
          ) : (
            <ul className="space-y-2 max-h-52 overflow-y-auto">
              {data.parrainages.map(p => (
                <li key={p.id} className="flex items-start gap-3 p-3 rounded-xl border border-slate-100 bg-slate-50/50">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-slate-800 truncate">{p.contact_nom}</p>
                    {p.contact_ecole && (
                      <p className="text-xs text-slate-500 flex items-center gap-1 truncate">
                        <Building2 className="w-3 h-3 shrink-0" /> {p.contact_ecole}
