                  <span className="text-[10px] font-semibold uppercase tracking-wide px-2 py-1 rounded-full bg-white border border-slate-200 text-slate-600 shrink-0">
                    {t(`status.${p.statut as 'en_cours'}`, { defaultValue: p.statut })}
