'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { usePathname, useRouter, useSearchParams } from 'next/navigation'

export interface SmartFilterField {
  key: string
  type: 'search' | 'select' | 'pills' | 'date' | 'month'
  label?: string
  placeholder?: string
  options?: { value: string; label: string }[]
  defaultValue?: string
  debounce?: boolean
  /** Ne pas inclure dans l'URL (ex. champs internes) */
  hiddenFromUrl?: boolean
}

export interface SmartFilterPreset {
  id: string
  label: string
  values: Record<string, string>
}

function readFromUrl(
  fields: SmartFilterField[],
  searchParams: URLSearchParams
): Record<string, string> {
  const out: Record<string, string> = {}
  for (const f of fields) {
    out[f.key] = searchParams.get(f.key) ?? f.defaultValue ?? ''
  }
  // Alias r├⌐trocompatibles (liens depuis pages classe, etc.)
  if (fields.some(f => f.key === 'classe') && !out.classe) {
    const alias = searchParams.get('classe_id')
    if (alias) out.classe = alias
  }
  if (fields.some(f => f.key === 'q') && !out.q) {
    const search = searchParams.get('search')
    if (search) out.q = search
  }
  return out
}

function shallowEqual(a: Record<string, string>, b: Record<string, string>): boolean {
  const keys = new Set([...Object.keys(a), ...Object.keys(b)])
  for (const k of keys) {
    if ((a[k] ?? '') !== (b[k] ?? '')) return false
  }
  return true
}

function buildUrlParams(
  fields: SmartFilterField[],
  values: Record<string, string>
): URLSearchParams {
  const params = new URLSearchParams()
  for (const f of fields) {
    if (f.hiddenFromUrl) continue
    const v = values[f.key]
    const def = f.defaultValue ?? ''
    if (v && v !== def && v !== 'tous') params.set(f.key, v)
  }
  return params
}

export function useSmartFilters(
  fields: SmartFilterField[],
  options?: { debounceMs?: number; syncUrl?: boolean }
) {
  const debounceMs = options?.debounceMs ?? 300
  const syncUrl = options?.syncUrl !== false
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const fieldsRef = useRef(fields)
  fieldsRef.current = fields

  const defaults = useMemo(() => {
    const out: Record<string, string> = {}
    for (const f of fields) out[f.key] = f.defaultValue ?? ''
    return out
  }, [fields])

  const [values, setValues] = useState<Record<string, string>>(() =>
    readFromUrl(fieldsRef.current, searchParams)
  )
  const [debouncedValues, setDebouncedValues] = useState(values)
  const skipUrlSync = useRef(true)
  const isInternalUrlUpdate = useRef(false)

  // R├⌐agir aux changements d'URL (navigation arri├¿re/avant, liens profonds)
  useEffect(() => {
    if (isInternalUrlUpdate.current) {
      isInternalUrlUpdate.current = false
      return
    }
    const fromUrl = readFromUrl(fieldsRef.current, searchParams)
    setValues(prev => (shallowEqual(prev, fromUrl) ? prev : fromUrl))
    setDebouncedValues(prev => (shallowEqual(prev, fromUrl) ? prev : fromUrl))
    skipUrlSync.current = true
  }, [searchParams])

  // Debounce des champs search
  useEffect(() => {
    const debouncedKeys = new Set(
      fieldsRef.current
        .filter(f => f.debounce || f.type === 'search')
        .map(f => f.key)
    )

    const applyUpdate = (patch: Record<string, string>) => {
      setDebouncedValues(prev => {
        const next = { ...prev, ...patch }
        return shallowEqual(prev, next) ? prev : next
      })
    }

    const immediate: Record<string, string> = {}
    const delayed: Record<string, string> = {}
    for (const [k, v] of Object.entries(values)) {
      if (debouncedKeys.has(k)) delayed[k] = v
      else immediate[k] = v
    }

    if (Object.keys(immediate).length > 0) applyUpdate(immediate)

    const timer = setTimeout(() => {
      if (Object.keys(delayed).length > 0) applyUpdate(delayed)
    }, debounceMs)

    return () => clearTimeout(timer)
  }, [values, debounceMs])

  // Sync URL sans boucle
  useEffect(() => {
    if (!syncUrl) return
    if (skipUrlSync.current) {
      skipUrlSync.current = false
      return
    }

    const params = buildUrlParams(fieldsRef.current, values)
    const nextQs = params.toString()
    const currentQs = searchParams.toString()
    if (nextQs === currentQs) return

    const next = nextQs ? `${pathname}?${nextQs}` : pathname
    isInternalUrlUpdate.current = true
    router.replace(next, { scroll: false })
  }, [values, pathname, router, syncUrl, searchParams])

  const setFilter = useCallback((key: string, value: string) => {
    setValues(prev => {
      if ((prev[key] ?? '') === value) return prev
      return { ...prev, [key]: value }
    })
  }, [])

  const setFilters = useCallback((patch: Record<string, string>) => {
    setValues(prev => ({ ...prev, ...patch }))
  }, [])

  const applyPreset = useCallback((preset: SmartFilterPreset) => {
    setValues({ ...defaults, ...preset.values })
  }, [defaults])

  const reset = useCallback(() => {
    setValues({ ...defaults })
  }, [defaults])

  const activeFilters = useMemo(() => {
    return fieldsRef.current
      .filter(f => {
        const v = values[f.key]
        const def = f.defaultValue ?? ''
        return v && v !== def && v !== 'tous'
      })
      .map(f => {
        const v = values[f.key]
        const opt = f.options?.find(o => o.value === v)
        return {
          key: f.key,
          label: f.label || f.key,
          value: v,
          display: opt?.label ?? v,
        }
      })
  }, [values])

  const hasActiveFilters = activeFilters.length > 0

  const buildParams = useCallback(
    (extra?: Record<string, string>) => {
      const params = buildUrlParams(fieldsRef.current, debouncedValues)
      if (extra) {
        for (const [k, v] of Object.entries(extra)) {
          if (v) params.set(k, v)
        }
      }
      return params
    },
    [debouncedValues]
  )

  return {
    values,
    debouncedValues,
    setFilter,
    setFilters,
    applyPreset,
    reset,
    activeFilters,
    hasActiveFilters,
    buildParams,
  }
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import { studentFilterPatch, type StudentContext } from '@/lib/student-context-links'

export function useStudentDeepLink(
  setFilters: (patch: Record<string, string>) => void,
  options?: {
    apply?: (student: StudentContext) => Record<string, string>
  },
) {
  const searchParams = useSearchParams()
  const appliedRef = useRef<string | null>(null)
  const applyRef = useRef(options?.apply)
  applyRef.current = options?.apply
  const [student, setStudent] = useState<StudentContext | null>(null)

  const eleveId = searchParams.get('eleve_id')

  useEffect(() => {
    if (!eleveId || appliedRef.current === eleveId) return

    appliedRef.current = eleveId
    fetch(`/api/eleves/${eleveId}`)
      .then(r => (r.ok ? r.json() : null))
      .then(data => {
        if (!data?.eleve) return
        const e = data.eleve
        const ctx: StudentContext = {
          id: e.id,
          nom: e.nom,
          prenom: e.prenom,
          numero_matricule: e.numero_matricule,
          classe_id: e.classe_id,
          section: e.section || e.classe_section,
        }
        setStudent(ctx)
        setFilters(applyRef.current?.(ctx) ?? studentFilterPatch(ctx))
      })
  }, [eleveId, setFilters])

  return { student, eleveId }
}

import { NextRequest, NextResponse } from 'next/server'
import { jwtVerify, SignJWT } from 'jose'
import bcrypt from 'bcryptjs'
import { getDb } from './db-server'
import { getJwtSecret, getJwtSecretKey } from './secrets'
import { getMachineFingerprint } from './paths'
import { runtimeEnv } from './runtime-env'
import {
  prepareSchoolDb,
  markSchoolDbDirty,
  scheduleSchoolDbFlush,
  resolveEcoleId,
} from './school-db'

export const JWT_EXPIRY = '8h'
export const COOKIE_NAME = 'sm_token'

export interface AuthUser {
  id: string
  role: string
  ecole_id: string | null
  ecole_slug: string | null
  nom: string | null
  auth_source?: 'local' | 'cloud'
  account_id?: string
  prenom?: string | null
}

export interface JwtPayload extends AuthUser {
  [key: string]: unknown
}

export async function signToken(payload: AuthUser): Promise<string> {
  return new SignJWT({ ...payload })
    .setProtectedHeader({ alg: 'HS256' })
    .setIssuedAt()
    .setExpirationTime(JWT_EXPIRY)
    .sign(getJwtSecretKey())
}

export async function verifyToken(token: string): Promise<JwtPayload | null> {
  try {
    const { payload } = await jwtVerify(token, getJwtSecretKey())
    return payload as JwtPayload
  } catch {
    return null
  }
}

export async function getUserFromRequest(request?: NextRequest): Promise<JwtPayload | null> {
  const token = request?.cookies.get(COOKIE_NAME)?.value
  if (!token) return null
  const user = await verifyToken(token)
  if (!user) return null

  if (process.env.VERCEL === '1' && user.ecole_slug) {
    await prepareSchoolDb(user.ecole_slug)
    const db = getDb(user.ecole_slug)
    const resolved = resolveEcoleId(db, user.ecole_slug, user.ecole_id)
    if (resolved) user.ecole_id = resolved
    scheduleSchoolDbFlush(user.ecole_slug)
  }

  if (user.ecole_slug && request && !['GET', 'HEAD', 'OPTIONS'].includes(request.method)) {
    markSchoolDbDirty(user.ecole_slug)
  }

  return user
}

export async function requireUser(request: NextRequest): Promise<JwtPayload | NextResponse> {
  const user = await getUserFromRequest(request)
  if (!user) {
    return NextResponse.json({ error: 'Non autoris├⌐' }, { status: 401 })
  }
  return user
}

export async function requireSuperAdmin(request: NextRequest): Promise<JwtPayload | null> {
  const user = await getUserFromRequest(request)
  if (!user || user.role !== 'super_admin') return null
  return user
}

export function setAuthCookie(response: import('next/server').NextResponse, token: string) {
  const secure = process.env.NODE_ENV === 'production' && runtimeEnv('SM_COOKIE_SECURE') !== 'false'
  response.cookies.set(COOKIE_NAME, token, {
    httpOnly: true,
    secure,
    sameSite: 'lax',
    maxAge: 60 * 60 * 8,
    path: '/',
  })
}

export function clearAuthCookie(response: import('next/server').NextResponse) {
  response.cookies.delete(COOKIE_NAME)
}

export async function loginUser(email: string, password: string) {
  const normalizedEmail = email.trim().toLowerCase()

  // ΓöÇΓöÇ Super admin : env ou fichier credentials local (Electron) ΓöÇΓöÇ
  const { getSuperAdminEmail, getSuperAdminPassword } = await import('./super-admin-credentials')
  const superAdminEmail = getSuperAdminEmail()
  const superAdminPassword = getSuperAdminPassword()

  if (superAdminPassword && normalizedEmail === superAdminEmail && password === superAdminPassword) {
    const payload: AuthUser = {
      id: 'super-admin',
      role: 'super_admin',
      ecole_id: null,
      ecole_slug: null,
      nom: 'Super Admin',
      auth_source: 'local',
    }
    const token = await signToken(payload)
    return { token, user: payload }
  }

  const { isCloudAuthAvailable, loginCloudUser, cloudAuthErrorMessage } = await import('./cloud-auth')

  // ΓöÇΓöÇ Web (Vercel) : auth cloud + base SQLite synchronis├⌐e ΓöÇΓöÇ
  if (process.env.VERCEL && isCloudAuthAvailable()) {
    const cloud = await loginCloudUser(normalizedEmail, password)
    if (!cloud.ok) {
      return { error: cloudAuthErrorMessage(cloud.error) as 'Email introuvable' | 'Mot de passe incorrect' | 'Licence expir├⌐e' }
    }

    const slug = cloud.result.user.ecole_slug!
    await prepareSchoolDb(slug)
    const db = getDb(slug)
    const ecoleId = resolveEcoleId(db, slug, cloud.result.user.ecole_id)

    const user: AuthUser = {
      ...cloud.result.user,
      ecole_id: ecoleId,
      auth_source: 'cloud',
    }
    const token = await signToken(user)
    return { token, user }
  }

  // ΓöÇΓöÇ Desktop : SQLite d'abord, puis cloud si email absent localement ΓöÇΓöÇ
  const localResult = await loginLocalUser(normalizedEmail, password)
  if (!('error' in localResult)) return localResult
  if (localResult.error === 'Mot de passe incorrect' || localResult.error === 'Licence expir├⌐e' || localResult.error === 'Licence utilis├⌐e sur un autre ordinateur') {
    return localResult
  }

  if (isCloudAuthAvailable()) {
    const cloud = await loginCloudUser(normalizedEmail, password)
    if (!cloud.ok) {
      return { error: cloudAuthErrorMessage(cloud.error) as 'Email introuvable' | 'Mot de passe incorrect' | 'Licence expir├⌐e' }
    }
    const { buildLocalAuthFromCloudLogin } = await import('./local-provision')
    const user = buildLocalAuthFromCloudLogin(cloud.result, normalizedEmail)
    const token = await signToken(user)
    return { token, user }
  }

  return localResult
}

async function loginLocalUser(email: string, password: string) {
  let db: ReturnType<typeof getDb>
  try {
    db = getDb()
  } catch {
    return { error: 'Email introuvable' as const }
  }

  const user = db.prepare(`
    SELECT u.*, e.slug as ecole_slug
    FROM users u
    LEFT JOIN ecoles e ON e.id = u.ecole_id
    WHERE u.email = ?
  `).get(email) as Record<string, unknown> | undefined

  if (!user) {
    return { error: 'Email introuvable' as const }
  }

  const valid = await bcrypt.compare(password, user.password_hash as string)
  if (!valid) {
    return { error: 'Mot de passe incorrect' as const }
  }

  if (user.role !== 'super_admin' && user.ecole_id) {
    const today = new Date().toISOString().split('T')[0]
    const licence = db.prepare(`
      SELECT id, machine_fingerprint FROM licences
      WHERE ecole_id = ? AND is_active = 1 AND date_fin >= ?
      ORDER BY date_fin DESC LIMIT 1
    `).get(user.ecole_id, today) as { id: string; machine_fingerprint: string | null } | undefined

    if (!licence) {
      return { error: 'Licence expir├⌐e' as const }
    }

    const fingerprint = getMachineFingerprint()
    if (licence.machine_fingerprint && licence.machine_fingerprint !== fingerprint) {
      return { error: 'Licence utilis├⌐e sur un autre ordinateur' as const }
    }
    if (!licence.machine_fingerprint) {
      db.prepare('UPDATE licences SET machine_fingerprint = ? WHERE id = ?').run(fingerprint, licence.id)
    }
  }

  const payload: AuthUser = {
    id: user.id as string,
    role: user.role as string,
    ecole_id: (user.ecole_id as string) || null,
    ecole_slug: (user.ecole_slug as string) || null,
    nom: (user.nom as string) || null,
    prenom: (user.prenom as string) as string | null | undefined,
    auth_source: 'local',
  }

  const token = await signToken(payload)
  return { token, user: payload }
}

export async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, 12)
}

import type Database from 'better-sqlite3'
import { getDb } from './db-server'
import { getDefaultAnneeScolaireBounds } from './school-year'
import type { CloudLoginResult } from './cloud-auth'
import { linkCloudUserLocalId } from './cloud-auth'
import { getMachineFingerprint } from './paths'

/** Cr├⌐e ou met ├á jour l'├⌐tablissement et l'utilisateur locaux apr├¿s connexion cloud (desktop). */
export function provisionLocalFromCloud(login: CloudLoginResult): AuthProvisionResult {
  const db = getDb()
  const slug = login.user.ecole_slug!

  let ecole = db.prepare('SELECT id FROM ecoles WHERE slug = ?').get(slug) as { id: string } | undefined

  if (!ecole) {
    db.prepare(`
      INSERT INTO ecoles (nom, slug, telephone, directeur_nom, sections, email)
      VALUES (?, ?, ?, ?, ?, ?)
    `).run(
      login.ecole_nom,
      slug,
      login.telephone ?? null,
      login.directeur_nom ?? login.user.nom,
      JSON.stringify(login.sections ?? ['francophone']),
      null,
    )
    ecole = db.prepare('SELECT id FROM ecoles WHERE slug = ?').get(slug) as { id: string }
  }

  const ecoleId = ecole.id

  if (login.cle_licence && login.licence_plan && login.licence_date_fin) {
    const existingLic = db.prepare(
      'SELECT id FROM licences WHERE ecole_id = ? AND cle_licence = ?',
    ).get(ecoleId, login.cle_licence) as { id: string } | undefined

    if (!existingLic) {
      db.prepare(`
        INSERT INTO licences (ecole_id, type, date_debut, date_fin, is_active, cle_licence, machine_fingerprint)
        VALUES (?, ?, date('now'), ?, 1, ?, ?)
      `).run(ecoleId, login.licence_plan, login.licence_date_fin, login.cle_licence, getMachineFingerprint())
    } else {
      db.prepare(`
        UPDATE licences SET is_active = 1, date_fin = ?, machine_fingerprint = ?
        WHERE id = ?
      `).run(login.licence_date_fin, getMachineFingerprint(), existingLic.id)
    }

    db.prepare(`
      INSERT INTO licence_cache (cle, plan, date_fin, last_verified, is_active)
      VALUES (?, ?, ?, ?, 1)
      ON CONFLICT(cle) DO UPDATE SET
        plan = excluded.plan,
        date_fin = excluded.date_fin,
        last_verified = excluded.last_verified,
        is_active = 1
    `).run(login.cle_licence, login.licence_plan, login.licence_date_fin, new Date().toISOString())
  }

  ensureAnneeScolaire(db, ecoleId)

  return { ecoleId, slug }
}

export interface AuthProvisionResult {
  ecoleId: string
  slug: string
}

export function provisionLocalUser(
  db: Database.Database,
  ecoleId: string,
  email: string,
  passwordHash: string,
  nom: string,
  accountId: string,
  ecoleSlug: string,
  cloudUserId: string,
): string {
  const normalized = email.trim().toLowerCase()
  let user = db.prepare('SELECT id FROM users WHERE email = ?').get(normalized) as { id: string } | undefined

  if (user) {
    db.prepare('UPDATE users SET password_hash = ?, nom = ?, ecole_id = ?, role = ? WHERE id = ?').run(
      passwordHash, nom, ecoleId, 'admin', user.id,
    )
  } else {
    db.prepare(`
      INSERT INTO users (email, password_hash, nom, role, ecole_id)
      VALUES (?, ?, ?, 'admin', ?)
    `).run(normalized, passwordHash, nom, ecoleId)
    user = db.prepare('SELECT id FROM users WHERE email = ?').get(normalized) as { id: string }
  }

  linkCloudUserLocalId(accountId, ecoleSlug, user.id).catch(() => {})
  return user.id
}

function ensureAnneeScolaire(db: Database.Database, ecoleId: string) {
  const active = db.prepare(
    'SELECT id FROM annees_scolaires WHERE ecole_id = ? AND is_active = 1',
  ).get(ecoleId)
  if (active) return

  const { label, date_debut, date_fin } = getDefaultAnneeScolaireBounds()
  db.prepare(`
    INSERT INTO annees_scolaires (ecole_id, label, date_debut, date_fin, is_active)
    VALUES (?, ?, ?, ?, 1)
  `).run(ecoleId, label, date_debut, date_fin)
}

export function buildLocalAuthFromCloudLogin(
  login: CloudLoginResult,
  email: string,
): { id: string; role: string; ecole_id: string; ecole_slug: string; nom: string | null; auth_source: 'local' } {
  const db = getDb()
  const { ecoleId, slug } = provisionLocalFromCloud(login)
  const localUserId = provisionLocalUser(
    db,
    ecoleId,
    email,
    login.password_hash,
    login.user.nom ?? 'Admin',
    login.user.account_id,
    slug,
    login.user.id,
  )

  return {
    id: localUserId,
    role: login.user.role,
    ecole_id: ecoleId,
    ecole_slug: slug,
    nom: login.user.nom,
    auth_source: 'local',
  }
}

